__NH_GAME_DATA["NpcTalk"] = [{"id":200000,"idx":1,"url":"afei","name":"wuming","leftRight":1,"NpcWords":"Today will be the end of Hidden Leaf Village and the start of a perfect world!"},{"id":200000,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"Who is it? How dare you raid Hidden Leaf Village? So our Great Three Ninjas are belittled~~"},{"id":200000,"idx":3,"url":"afei","name":"wuming","leftRight":1,"NpcWords":"Great Three Ninjas? You ninjas are the bane to this world! Look~"},{"id":200001,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Sharingan! Are you Madara\u2026Move, men!"},{"id":200002,"idx":1,"roleId":99,"leftRight":0,"NpcWords":"Bunta~Let's join them!"},{"id":200003,"idx":1,"url":"afei","name":"wuming","leftRight":1,"NpcWords":"It's no use resisting, Nine Tails! Wipe out the Hidden Leaf!"},{"id":200004,"idx":1,"roleId":99,"leftRight":0,"NpcWords":"Chakra of the Nine Tails is awesome, Kushina\u2026Please forgive my choice... "},{"id":200004,"idx":2,"roleId":99,"leftRight":0,"NpcWords":"I'll seal Nine Tails!"},{"id":200005,"idx":1,"roleId":17,"leftRight":1,"NpcWords":"Hah, I'll paint beard on the Hokage's statue!"},{"id":200005,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Naruto, you'll have a trial tomorrow. Why are you still walking around?"},{"id":200005,"idx":3,"roleId":17,"leftRight":1,"NpcWords":"I'll definitely become Hokage. Do I still need to prepare for the trial ^_^"},{"id":200005,"idx":4,"roleId":18,"leftRight":0,"NpcWords":"-_-# Idiot! \u2026go and find Teacher Iruka for practices with me!"},{"id":200006,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"My Ninjutsu even defeated Teacher Iruka, hah V^_^V"},{"id":200006,"idx":2,"roleId":18,"leftRight":1,"NpcWords":"Idiot! Your Sexy Jutsu is unlikely to pass the trial! Go back to school with me and make up missed lessons!"},{"id":200007,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Now I'll definitely pass the trial! Nothing else to do, just go back home and have a sleep zzZ"},{"id":200007,"idx":2,"roleId":18,"leftRight":1,"NpcWords":"Never stare blankly when you're free. Someone is looking for you at the top right corner. Immediately go and see what has happened!"},{"id":200008,"idx":1,"roleId":24,"leftRight":1,"NpcWords":"Oh\u2026I'm glad to be selected by you. Please transfer a Ninja's EXP to me. I won't have strong combat ability until my level is upgraded (*^__^*)"},{"id":200009,"idx":1,"roleId":24,"leftRight":1,"NpcWords":"Oh~Yeah~ My level is improved significantly at one time. Please let me demonstrate my strength in the fight!"},{"id":200010,"idx":1,"roleId":9,"leftRight":0,"NpcWords":"You've enabled the Deploy System. Sending different Ninjas may achieve different effects. Deploy me quickly!"},{"id":200011,"idx":1,"roleId":10,"leftRight":1,"NpcWords":"If adjacent Ninjas have the same Chakra color, combat attributes will increase. Now let me appear to form a pair of red colors."},{"id":200012,"idx":1,"roleId":10,"leftRight":1,"NpcWords":"A pair of red colors can increase attack by 10 points! Certain Ninjas may attain Combo skills. To attain more Combo skills, immediately go and collect Ninjas!"},{"id":200101,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Remember to enhance your Equip if you can't resist!"},{"id":200102,"idx":1,"roleId":1,"myRoleId":1,"level":10,"leftRight":0,"NpcWords":"Equip Refining can let an Equip to have multiple attributes. Wearing it is really cool V^O^V"},{"id":200103,"idx":1,"roleId":1,"myRoleId":1,"level":20,"leftRight":0,"NpcWords":"Class-S Equipment feature high basic attributes. Wearing Class-S Equipment will be amazing!"},{"id":200104,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Lack materials to combine equipment? Acquire lots of materials by Seizing Treasures :)"},{"id":200105,"idx":1,"roleId":1,"myRoleId":1,"level":16,"leftRight":0,"NpcWords":"Lack of material for Synthesize? You can obtain it from daily event:)"},{"id":200106,"idx":1,"roleId":1,"myRoleId":1,"level":16,"leftRight":0,"NpcWords":"How to obtain Ancient Black Iron? Go to higher level of Genin Trial to try your luck~"},{"id":200107,"idx":1,"roleId":1,"myRoleId":1,"level":40,"leftRight":0,"NpcWords":"Gold Bar is insufficient? You may obtain lots of Gold Bar in middle and higher level of Genin Trial!"},{"id":200108,"idx":1,"roleId":1,"myRoleId":1,"level":10,"leftRight":0,"NpcWords":"Don't you know? Senior Ninjas can be obtained from Shadow Ninja House. You may take the corresponding Ninja home as long as you win enough victories!"},{"id":200109,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Have you ever robbed in a Ramen House? Sh\u2026don't mention I've told you this..."},{"id":200110,"idx":1,"roleId":1,"myRoleId":1,"level":30,"leftRight":0,"NpcWords":"Deploy can increase many attributes. Remember to gather people with similar colors~"},{"id":200111,"idx":1,"roleId":1,"myRoleId":1,"level":30,"leftRight":0,"NpcWords":"Deployed 15 persons may constitute multiple Combo skills. To increase attributes or attack as reinforcement, it's up to you~"},{"id":200112,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"It's a Class-SS Ninja appeared in the village. Is it true...\u2299\ufe3f\u2299"},{"id":200113,"idx":1,"roleId":1,"myRoleId":1,"level":20,"leftRight":0,"NpcWords":"Want to summon a Tailed Beast in the fight? Defeat Jinchuriki and go to Tailed Beast Altar to have a look ( ^_^ )/~~"},{"id":200114,"idx":1,"roleId":1,"myRoleId":1,"level":6,"leftRight":0,"NpcWords":"Practicing Summon Skills in Summon School is dependent on your luck on slot machine~\\(\u2267\u25bd\u2266)/~lala, la"},{"id":200115,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Fulfilling Reward Quests may obtain lots of Gold. Don't forget me when you get rich~\\(\u2267\u25bd\u2266)/~"},{"id":200116,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Want to get more powerful ninja? Combine Ninja in the Laboratory"},{"id":200117,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Some skill will only appear in some Ninja, but you can transfer it to another people through Laboratory \u2570(\uffe3\u25bd\uffe3)\u256e"},{"id":200118,"idx":1,"roleId":1,"myRoleId":1,"level":24,"leftRight":0,"NpcWords":"Try to improve your arena ranking if you want to claim many advanced materials every day!"},{"id":200119,"idx":1,"roleId":1,"myRoleId":1,"level":24,"leftRight":0,"NpcWords":"yo~yo~yo~ don't forget to go to the arena and claim daily ranking reward (\u256f3\u2570)"},{"id":200120,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Do you know \"Sai\"? You can obtain it from VIP2 o (>, <) O You must take it!"},{"id":200121,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"The first top-up can obtain triple gold. Do make the most of it (\uff1e\ufe4f\uff1c)"},{"id":200122,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"It takes 30 minutes to obtain 5 points PH. If you don't want to wait, remember that Ramen House will distribute PH at 12:00 and 6pm!"},{"id":200123,"idx":1,"roleId":1,"myRoleId":1,"level":1,"leftRight":0,"NpcWords":"Login for 7 days can obtain \"Sasuke\"...... This guy is very powerfulO(\u2229_\u2229)O"},{"id":200124,"idx":1,"roleId":1,"myRoleId":1,"level":20,"leftRight":0,"NpcWords":"Have you heard of Class-S Traitor Pain? He's said to be a VIP6 dedicated Ninja (*^__^*)"},{"id":200125,"idx":1,"roleId":1,"myRoleId":1,"level":5,"leftRight":0,"NpcWords":"Want to let me teach you Class-S Ninjutsu? Are you kidding\u2026 You haven't yet graduated from Ninjutsu School \u2026 (\u256f\ufe4f\u2570)"},{"id":200126,"idx":1,"roleId":1,"myRoleId":1,"level":3,"leftRight":0,"NpcWords":"It's said that Class-S Ninjas are more likely to be caught at 8pm \u2026 but in no way it's credible...(+\ufe4f+)"},{"id":200127,"idx":1,"roleId":1,"myRoleId":1,"level":50,"leftRight":0,"NpcWords":"You can talk to me now. This means you've had a high level. So I don't need to tell your anything...\uffe3\u3078\uffe3"},{"id":200128,"idx":1,"roleId":1,"myRoleId":1,"level":10,"leftRight":0,"NpcWords":"I want Itachi Uchiha! Who can take me to refresh Shadow Ninja House? (\u256f3\u2570)"},{"id":200129,"idx":1,"roleId":1,"myRoleId":1,"level":10,"leftRight":0,"NpcWords":"Can't resist your opponent from Shadow Ninja House? Should your teammates are strong\u2026you should be too weak\u2026just refresh your team"},{"id":201011,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Hah, I'll paint beard on the Hokage's statue!"},{"id":201012,"idx":1,"roleId":30,"leftRight":1,"NpcWords":"The graduation trial will be held tomorrow, but you're still walking around. Immediately review your morph skills!"},{"id":201012,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"What a wordy Iruka! Just like an old guy. I'll use Sexy Jutsu to deal with you!"},{"id":201013,"idx":1,"roleId":30,"leftRight":1,"NpcWords":"Never create such a strange Ninjutsu to cause my nose to bleed in the future! Go and sweep it or you won't be allowed to go back home!"},{"id":201021,"idx":1,"roleId":2,"leftRight":1,"NpcWords":"Why are you so downhearted, Naruto? Talk to me and see if I can help you."},{"id":201022,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Why? Why only I failed the trial again? Teacher Iruka just takes it seriously and always makes troubles for me\u2026"},{"id":201022,"idx":2,"roleId":2,"leftRight":1,"NpcWords":"Let me tell you a secret, Naruto. If you want to graduate, just go and get Book of Seal. It's hidden in the room of 3rd Hokage."},{"id":201022,"idx":3,"roleId":100,"leftRight":1,"NpcWords":"Naruto? Why did you come to my room secretly late at night?"},{"id":201023,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Bad, Book of Seal was taken away by Naruto. It's something dangerous sealed by 1st Hokage. Immediately find Naruto!"},{"id":201023,"idx":2,"roleId":30,"leftRight":1,"NpcWords":"Yes, Lord Hokage \u2026 but how could Naruto steal before Lord Hokage's eyes\u2026so\u2026"},{"id":201023,"idx":3,"roleId":100,"leftRight":0,"NpcWords":"\u2026yes, it's Sexy Jutsu. An old man will suffer from shock if he's bleeding too much\u2026you understand it\u2026"},{"id":201031,"idx":1,"roleId":30,"leftRight":0,"NpcWords":"Why did you steal Book of Seal, Naruto? That scroll is very dangerous."},{"id":201032,"idx":1,"roleId":2,"leftRight":1,"NpcWords":"Give that scroll to me, Naruto. It's useless for you to hold it. Give it to me and I'll tell the truth about you."},{"id":201032,"idx":2,"roleId":30,"leftRight":0,"NpcWords":"It's you, Mizuki \u2026 you even used Naruto to get the scroll."},{"id":201032,"idx":3,"roleId":2,"leftRight":1,"NpcWords":"Go away, Iruka. Naruto is that Demon Fox sealed 12 years ago. He destroyed the village and nobody would accept him. Give the scroll to me!"},{"id":201033,"idx":1,"roleId":30,"leftRight":0,"NpcWords":"Naruto is an excellent, diligent student recognized by me instead of a Demon Fox. He's a ninja from Hidden Leaf Village!"},{"id":201033,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"\u2026Iruka, teacher\u2026"},{"id":201041,"idx":1,"roleId":1,"leftRight":1,"NpcWords":"What? Naruto used his Sexy Jutsu to beat down my grandpa. Let him teach me his strong skill. "},{"id":201042,"idx":1,"roleId":1,"leftRight":1,"NpcWords":"Brother Naruto, please teach me Sexy Jutsu that can be used to defeat old Hokage!"},{"id":201042,"idx":2,"roleId":34,"leftRight":0,"NpcWords":"Young grandson master, go back with me. You'll also become foolish if you're with such an idiot."},{"id":201042,"idx":3,"roleId":1,"leftRight":1,"NpcWords":"Go away, you scrap teacher. Let's say. You should accept me if you can win me, brother Naruto!"},{"id":201051,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"You'll be teacher of Team 7 from now on, Kakashi, especially Naruto and Sasuke, as you know..."},{"id":201052,"idx":1,"roleId":83,"leftRight":1,"NpcWords":"You three will constitute one team from now on. I'm your teacher Kakashi Hatake. Actually I dislike you at first sight."},{"id":201052,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Naruto is just making troubles. I just want to be with Sasuke. I'll definitely take his first kill if possible. Come on, Sakura!"},{"id":201052,"idx":3,"roleId":27,"leftRight":1,"NpcWords":"Why am I in the same team with the last one\u2026"},{"id":201052,"idx":4,"roleId":17,"leftRight":0,"NpcWords":"Hey, what are you talking? Of course I don't want to be with you. Want to have a fight?"},{"id":201052,"idx":5,"roleId":27,"leftRight":1,"NpcWords":"Hum, with you, the last one? It'll take 5 seconds only to deal with you!"},{"id":201053,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Sasuke is really awesome! Great! What's your favorite food, Sasuke? What type of girls do you like?"},{"id":201053,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Ur, I like Sakura, but she just cares about that damned Sasuke. It's really annoying ..."},{"id":201061,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"This test is about field survival. The guy who takes the bell can have a bento, otherwise go back to Ninja school!"},{"id":201062,"idx":1,"roleId":83,"leftRight":1,"NpcWords":"You just barge about, consider others as obstacles or think about love. You don't understand teamwork and aren't qualified to be a Ninja!"},{"id":201062,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Ur\u2026"},{"id":201062,"idx":3,"roleId":27,"leftRight":0,"NpcWords":"Hum\u2026"},{"id":201062,"idx":4,"roleId":18,"leftRight":0,"NpcWords":"Ah\u2026"},{"id":201062,"idx":5,"roleId":83,"leftRight":1,"NpcWords":"Well, if you three cooperate with each other to seize the bell from me, you may have a meal otherwise you'll have nothing to eat. You have one day!"},{"id":201063,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"(Laughing) You guys are all qualified. Remember teamwork. Those who don't value partners are just garbage!"},{"id":202011,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Damn it! Old grandpa always assigns some boring quests such as catching cats and taking care of children to our team. We're no longer children."},{"id":202012,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Team Kakashi, I'll give you a Class-C quest to you this time. Go protect this bridge expert Mr. Tazuna and escort him back to Waves Kingdom."},{"id":202012,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Great! I've never left the village before. Hah, Team 7, move!"},{"id":202012,"idx":3,"roleId":35,"leftRight":1,"NpcWords":"Hey, do you really want to give these kids a Class-C quest? Ur, I doubt that. Let's test their capabilities!"},{"id":202013,"idx":1,"roleId":35,"leftRight":0,"NpcWords":"Despite a little weak strength, you managed to complete it. Take care and come back early, everyone."},{"id":202081,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"There seems to be strong Chakra here. An enemy or a friend\u2026"},{"id":202082,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Hello, Ninjas from Fire Kingdom, are you also looking for Legendary Ninja Sword in Waves Kingdom? Hum, that's my prey!"},{"id":202082,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Hey, who are you? How can you whisper to yourself and attack me for no reason?"},{"id":202083,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Ur? It seems that he doesn't know anything. How can I suspect such a stupid guy? So disgraceful, bye!"},{"id":202083,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"That guy is really nervous and jumpy. But it's correct for him to say Naruto is stupid\u2026"},{"id":202091,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"That guy appears to be a traitor mist ninja. Why did he go to Waves Kingdom and look for Ninja Sword? I have a foreboding\u2026"},{"id":202092,"idx":1,"roleId":3,"leftRight":1,"NpcWords":"Hey, stop. Were you with Hozuki Suigetsu just now? He's a traitor. Are you colluding with each other?"},{"id":202092,"idx":2,"roleId":4,"leftRight":1,"NpcWords":"Those guys from Fire Kingdom must have a conspiracy here. First catch them!"},{"id":202093,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Damn it! How could I run across such unreasonable guys? Never belittle our Hidden Leaf!"},{"id":202101,"idx":1,"roleId":60,"leftRight":1,"NpcWords":"Why not go capture Suigetsu? Why still here?"},{"id":202102,"idx":1,"roleId":4,"leftRight":1,"NpcWords":"Lord Yagura, these guys are Suigetsu's accomplices!"},{"id":202102,"idx":2,"roleId":60,"leftRight":1,"NpcWords":"Hum, you guys, tell me where Suigetsu is or you'll die painfully."},{"id":202103,"idx":1,"roleId":60,"leftRight":0,"NpcWords":"Ur? You've come to Waves Kingdom to implement your quest? Sorry, my men seemed to have made a mistake."},{"id":202103,"idx":2,"roleId":60,"leftRight":0,"NpcWords":"Let's go before that traitor has gone too far \u2026but I have to remind you guys from Hidden Leaf that you're within our mist's territory. "},{"id":202021,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"What strange guys! I've seen too many cranks all the way."},{"id":202022,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Waves Kingdom gathered so many strong characters, do take care \u2026 This feeling, bad, we're tracked\u2026"},{"id":202022,"idx":1,"roleId":3,"leftRight":1,"NpcWords":"Is this the old man Lord Zabuza ordered us to eliminate? So funny, did he find some kids as helpers?"},{"id":202111,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Whir, whir, Teacher Kakashi, why did these Ninjas attack us? Hey, look, that guy ahead. Isn't it Teacher Asuma?"},{"id":202112,"idx":1,"url":"asima","name":"asima2","leftRight":0,"NpcWords":"I finally got you. Lord Hokage received a message that some strong traitors haunted in Waves Kingdom recently. He's afraid of any change and asked me to help you."},{"id":202112,"idx":2,"roleId":83,"leftRight":1,"NpcWords":"Asuma always calls his father old guy. How could he call him Lord Hokage? Show your face, you counterfeit!"},{"id":202113,"idx":1,"roleId":27,"leftRight":1,"NpcWords":"He even disguised himself as Teacher Asuma to attack us. Why did these guys repeatedly \u2026"},{"id":202121,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"One enemy after another \u2026Mr. Tazuna must have hidden his quest. I'll have to go and talk to him."},{"id":202122,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Mr. Tazuna was chief engineer to build that bridge in Waves Kingdom. It relates the cargo transport from and out of the island."},{"id":202122,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Ship billionaire Gato wanted to monopolize the traffic route and control prices, so he hired a killer and intended to stop the bridge from being finished."},{"id":202122,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"It's so important. Of course we can't sit watching, right, Teacher Kakashi? Let me wipe out those killers!"},{"id":202123,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ur\u2026"},{"id":202123,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"Hello, you talked big, but you're scared trembling and injured yourself by mistake. What a real last one!"},{"id":202031,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"These guys are Mist Shadow Chunins you kids can't deal with. Should we let them go back to Hidden Leaf first?"},{"id":202032,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Ah, go back to Hidden Leaf? It doesn't matter to me. \nI'll see what Sasuke will select. "},{"id":202032,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"I won't go back! Should we first send this wounded coward back for treatment? Naruto is just a burden for us here..."},{"id":202032,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Don't look down upon me! I'll swear with this Kunai to protect the uncle. I won't flee or ask others to rescue me any more!"},{"id":202032,"idx":4,"roleId":4,"leftRight":1,"NpcWords":"Protection? Hah, you're talking big, kids. First see if you can protect yourselves!"},{"id":202041,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"You're real good-for-nothing and even can't deal with kids from Hidden Leaf. I have to stand out in person."},{"id":202042,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"(Suddenly appeared) It is no wonder that Demon Brothers can't deal with you. You're Copy Ninja Kakashi Hatake from Hidden Leaf."},{"id":202042,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"You're a fugitive Ninja, Demon of Misthide Zabuza Momochi. Take care, everyone. This guy's strength is completely different from previous one. "},{"id":202042,"idx":3,"roleId":83,"leftRight":0,"NpcWords":"This guy's Ninja Sword Decapitating Blade is really awesome. No wonder that previous fugitive Ninja wanted to come to Waves Kingdom and seize Ninja Sword."},{"id":202043,"idx":1,"roleId":42,"leftRight":1,"NpcWords":"Thank you so much! I'm from Hidden Mist Ninja chasers and try to kill Zabuza. Let me handle the remainders."},{"id":202043,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"It's weird\u2026I seem, seem to have overlooked something important ..."},{"id":202051,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Generally the chasers handle bodies at the site. If I guess right, those two guys should come from the same source. Zabuza is saved."},{"id":202052,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"You're in trouble now. It's hard for you to deal with them with the existing control over Chakra, so receive special trainings from now on!"},{"id":202052,"idx":2,"roleId":83,"leftRight":1,"NpcWords":"Ur, let me first try my scout ability by Transfiguration. Who should I transform myself into?"},{"id":202052,"idx":3,"roleId":21,"leftRight":1,"NpcWords":"Choji? No, no, too fat."},{"id":202052,"idx":4,"roleId":19,"leftRight":1,"NpcWords":"What about Ino? No, I can't simulate girls' tone. "},{"id":202052,"idx":5,"url":"chutian","name":"chutian1","leftRight":1,"NpcWords":"I decided. I'll just transform into Hinata."},{"id":202131,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"I'm exhausted due to daily trainings. Just have a sleep on the tree as Teacher Kakashi isn't here now\u2026ah, someone is already here?"},{"id":202132,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Hello, do you also like sleeping on the tree? It seems that we have similar hobbies."},{"id":202132,"idx":2,"roleId":63,"leftRight":1,"NpcWords":"Er?"},{"id":202132,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Oh, are you also a Ninja? It's really hard to control Chakra and I'm often laughed at by others. Hey, tell me if you have any tips?"},{"id":202132,"idx":4,"roleId":63,"leftRight":1,"NpcWords":"You little guy looks very familiar with me? Do you often chat up like that? Hah, it's funny. I'll teach you then. "},{"id":202133,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Wow, it's amazing. I finally made it. Thank you. Well, what's your name?"},{"id":202133,"idx":2,"roleId":63,"leftRight":1,"NpcWords":"Utakata \u2026 Well, see you, kid. I'll go and meet Lord Yagura."},{"id":202133,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"So you're here to track that fugitive ninja named Suigetsu with them. I know. They've gone to the southeast..."},{"id":202061,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"Well, Haku, my wound has almost recovered. Let's start our next hunting."},{"id":202061,"idx":2,"roleId":42,"leftRight":1,"NpcWords":"Yes, Lord Zabuza."},{"id":202062,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"These little guys seem to have grown strong. However, you won't defeat Haku with Kekkeigenkai even if you can win me."},{"id":202062,"idx":2,"roleId":42,"leftRight":1,"NpcWords":"I have no rancor against you and don't want to kill you, either, so please abandon your quest and leave Waves Kingdom."},{"id":202063,"idx":1,"roleId":42,"leftRight":1,"NpcWords":"Oh, please don't force me to take it seriously. If you continue opposing Lord Zabuza, I'll have to deal with you."},{"id":202141,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"Are you kind again, Haku? Don't show mercy to your opponent any more!"},{"id":202142,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"What's wrong with you? Clearly you don't agree to your own behaviors, why still follow what that guy without eyebrow said?"},{"id":202142,"idx":2,"roleId":42,"leftRight":1,"NpcWords":"Shut up. Stop insulting Lord Zabuza. His enemy will become mine and his order is everything for me!"},{"id":202142,"idx":3,"roleId":42,"leftRight":1,"NpcWords":"You just don't understand. Since Lord Zabuza picked me up and needed me, all my wish is to accompany and protect him!"},{"id":202143,"idx":1,"roleId":42,"leftRight":1,"NpcWords":"I lost it\u2026 Lord Zabuza doesn't need useless guys. I've lost the only reason to continue living \u2026please, please kill me."},{"id":202071,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"Our ninjas are used as tools, Haku. However, humans can't live without feelings and like tools."},{"id":202072,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"I always think I'm using you. But today I found I was wrong. We won't separate from each other that day I picked you up."},{"id":202072,"idx":1,"roleId":41,"leftRight":1,"NpcWords":"Well, Kakashi, let's end it. A Ninja must carry out the quest after he accepts it. "},{"id":202073,"idx":1,"url":"wuyinshouwei","name":"wuyinshouwei1","leftRight":1,"NpcWords":"Why did you lose so badly, Zabuza? Mr. Gato ordered us to kill you to save money and time."},{"id":202073,"idx":2,"roleId":41,"leftRight":0,"NpcWords":"Want to first use and then abandon us from the very start\u2026Employment is terminated. I have no reason to continue dealing with you, Kakashi."},{"id":202073,"idx":3,"roleId":41,"leftRight":0,"NpcWords":"Haku, sorry, thank you\u2026you are from Gato, go to hell with me!"},{"id":202073,"idx":4,"roleId":17,"leftRight":0,"NpcWords":"What irksome guys! We're also glad to lend a hand and drive Gato's men out of the country!"},{"id":202251,"idx":1,"roleId":60,"leftRight":1,"NpcWords":"Spit it. You need to endure and escape from this fog."},{"id":202252,"idx":1,"roleId":60,"leftRight":1,"NpcWords":"Moon in the water. We need to escape from this fog and endure it and some are busy....."},{"id":202252,"idx":2,"roleId":73,"leftRight":1,"NpcWords":"Yagura seems to find the whereabouts of Konoha ninja."},{"id":202252,"idx":3,"roleId":60,"leftRight":1,"NpcWords":"Why Konoha guys come here? Chojuro, check the situation."},{"id":202252,"idx":4,"roleId":73,"leftRight":1,"NpcWords":"It's Yagura!"},{"id":202253,"idx":1,"roleId":73,"leftRight":1,"NpcWords":"Yagura, the fire nation seemed only to perform an escort mission and we don't see anything suspicious."},{"id":202253,"idx":2,"roleId":60,"leftRight":1,"NpcWords":"Well, we will continue to do what we do. We need to increase the tense and relations between this five nation. Don't let your guard down because we still don't know the location the other village."},{"id":202151,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Came to the Wave Kingdom and we must prepare for the heavy rain......"},{"id":202152,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Came all the way to Wave Kingdom and got defeated by that broadsword, huh? Is that the ghost brothers of fog?"},{"id":202152,"idx":2,"roleId":49,"leftRight":1,"NpcWords":"I remember the ghost brothers are always don't cut human. Hee hee, we need to catch them."},{"id":202152,"idx":3,"roleId":49,"leftRight":1,"NpcWords":"Those guys have been looking for a few trouble Konoha Ninja......"},{"id":202153,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Hee hee, ghost brothers already died. I think I don't need to face them anymore."},{"id":203011,"idx":1,"roleId":34,"leftRight":0,"NpcWords":"Now it's time for Genin Mentors to go and meet Lord 3rd Hokage. Chunin Trial is about to start!"},{"id":203012,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Do you have any suitable initiate for Chunin Trial this year?"},{"id":203012,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Naruto Uzumaki, Sasuke Uchiha and Sakura Haruno in Team 7 should accept Chunin Trial in the name of Kakashi Hatake."},{"id":203012,"idx":3,"roleId":35,"leftRight":1,"NpcWords":"Perhaps Teacher Kakashi is too confident. I'm afraid they can't enter the gate of Floor 3 of Chunin examination room with their strength."},{"id":203151,"idx":1,"roleId":36,"leftRight":1,"NpcWords":"It's okay for Sasuke ranking 1st, but how can Naruto accept the trial? Is it serious?"},{"id":203152,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"I know about strength of these three guys as their mentor: Sakura's control, Sasuke's gift and Naruto's huge potential."},{"id":203152,"idx":2,"roleId":36,"leftRight":1,"NpcWords":"Oh, I'll see what changes have taken place to them after this period since Teacher Kakashi said like that."},{"id":203153,"idx":1,"roleId":36,"leftRight":0,"NpcWords":"I didn't expect they would make such a big progress..."},{"id":203153,"idx":2,"roleId":35,"leftRight":0,"NpcWords":"Right, we seem to have overlooked these little guys, especially Naruto."},{"id":203021,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Great, Konohamaru. Teacher Kakashi recommended me to attend the Chunin Trial. I'll become Hokage soon!"},{"id":203022,"idx":1,"roleId":1,"leftRight":0,"NpcWords":"You're really awesome and will become a Chunin soon, Brother Naruto. It's great, hah!"},{"id":203022,"idx":2,"roleId":32,"leftRight":1,"NpcWords":"Hello, kid, you're so noisy. You ran into me. I'll teach you a lesson."},{"id":203161,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Hum, what an old guy! How dare you still run wild in our Hidden Leaf Village?"},{"id":203162,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Is he the only descendant of Uchiha Clan? Oh, he looks strong,"},{"id":203162,"idx":2,"roleId":5,"leftRight":1,"NpcWords":"Well, that indifferent, cool little guy. Let's have a fight. "},{"id":203163,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Calm down, Kankuro. We're here to attend Chunin Trial. Do you want to fight in their village?"},{"id":203163,"idx":2,"roleId":40,"leftRight":1,"NpcWords":"\u2026stop\u2026otherwise you'll be killed\u2026"},{"id":203031,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Those ninjas from Hidden Sand Village look terrible. Oh, so many people have come to attend the selection."},{"id":203032,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"Hey, I'm Rock Lee from Hidden Leaf. Now I'll defeat Sasuke ranking 1st among initiates here. If I win him, Sakura will become my girlfriend!"},{"id":203032,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"What? I dislike your eyes, hairstyle and thick eyebrow! I'll never deal with some guys like you."},{"id":203032,"idx":3,"roleId":27,"leftRight":0,"NpcWords":"This guy really has good strength!"},{"id":203033,"idx":1,"roleId":84,"leftRight":1,"NpcWords":"Hi, Lee, stop! The trial is about to start, but what are you doing? Where is your Bloodboil Youth? Go and run 500 circles!"},{"id":203033,"idx":2,"roleId":26,"leftRight":1,"NpcWords":"Yes, teacher, I'll practice hard in the sunset."},{"id":203041,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Why? The atmosphere is so tense. Isn't there any friendly guy?"},{"id":203042,"idx":1,"roleId":52,"leftRight":1,"NpcWords":"Are you initiates to attend the trial? I'm Kabuto. It's the 7th time that I have attended the trial. Many elite Genins gather here this year."},{"id":203042,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"It's so exciting! I'm Naruto Uzumaki. I'll never be defeated by you guys, hah! (Shouting)"},{"id":203042,"idx":3,"roleId":52,"leftRight":1,"NpcWords":"This idiot instantly turned all Genins at the venue into enemies. Is he highly motivated or stupid\u2026"},{"id":203042,"idx":4,"roleId":11,"leftRight":1,"NpcWords":"What unruly kids! It seems that our Sound Ninjas are belittled. Teach them a lesson. Hah, the punishment may be a little cruel\u2026"},{"id":203171,"idx":1,"roleId":28,"leftRight":1,"NpcWords":"Hi, Naruto, don't make noise here. Don't stir up any turbulence for no reason, it's really troublesome\u2026"},{"id":203172,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"What? It's Shikamaru. You just have such a personality and are afraid of troubles. I just said something, but those Sound Ninjas \u2026"},{"id":203172,"idx":2,"roleId":28,"leftRight":1,"NpcWords":"What a stupid guy! He'll never listen to others. He's so wordy, just directly...Shadow Imitation!"},{"id":203173,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Oh, completely frozen, is this Shikamaru's technique?"},{"id":203173,"idx":2,"roleId":38,"leftRight":0,"NpcWords":"Ah, thank you for stopping this guy quickly to avoid a bigger turbulence, Shikamaru. Well, please go into it, Genins!"},{"id":203181,"idx":1,"roleId":15,"leftRight":1,"NpcWords":"There seems to be too many candidates this year..."},{"id":203182,"idx":1,"roleId":15,"leftRight":1,"NpcWords":"We have no choice but to test these Genins' Chakra and eliminate some unqualified guys in advance."},{"id":203183,"idx":1,"roleId":15,"leftRight":0,"NpcWords":"Er, qualified guys may enter Qualification Test Room here. Good luck to you."},{"id":203051,"idx":1,"roleId":33,"leftRight":1,"NpcWords":"So many people are present. Well, just eliminate 50% of participants in the first trial!"},{"id":203052,"idx":1,"roleId":33,"leftRight":1,"NpcWords":"Stop making noise! If anyone in your team is deprived of all scores in the first trial, other teammates will be disqualified. Take care!"},{"id":203052,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"I, I suddenly felt murderous look from both Sakura and Sasuke \u2026 what if I score 0..."},{"id":203052,"idx":3,"roleId":24,"leftRight":0,"NpcWords":"...Naruto \u2026 come on \u2026 (Muttering)"},{"id":203052,"idx":4,"roleId":33,"leftRight":1,"NpcWords":"Hum, first test courage and stress tolerance of these guys and see what choices they will make under pressure!"},{"id":203191,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Oh, oh, I encountered Chunin Trial when dealing with something in Hidden Leaf. It's bustling with noise!"},{"id":203192,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Hah, it's great to pass the first trial. Most importantly. I wasn't killed by Sakura due to my failure."},{"id":203192,"idx":2,"roleId":77,"leftRight":1,"NpcWords":"Oh, that little guy contains Power of the Tailed Beast. Is he also a Jinchuriki? Well, check it out, say hello and test his skills!"},{"id":203192,"idx":3,"url":"bawei","name":"bawei","leftRight":1,"NpcWords":"Hi, B, what are you doing? Don't make troubles. He's still a little guy."},{"id":203193,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Ur? Isn't Power of the Tailed Beast activated completely? Check it out! Just stun him with a single blow! Run, run, don't let anyone find it."},{"id":203193,"idx":2,"roleId":75,"leftRight":1,"NpcWords":"Lord Killer B, what, what did you do? You even stunned a Genin from Hidden Leaf. Stop running wild or Lord Raikage will punish you."},{"id":203061,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"It's strange. Why did I suddenly faint on the road yesterday? Was I too sleepy? Oh, I must be!"},{"id":203061,"idx":2,"roleId":39,"leftRight":1,"NpcWords":"What's going on, Ebisu? You even let so many people pass the trial. Never be so loose."},{"id":203062,"idx":1,"roleId":39,"leftRight":1,"NpcWords":"This is Forest of Death, the venue of the 2nd trial. But prior to this, you must sign on the informed consent form because someone may die here."},{"id":203062,"idx":2,"roleId":39,"leftRight":1,"NpcWords":"The teams will contend for scrolls in this trial. Only the team that get heavens and earth scrolls can be qualified. 50% of teams will be eliminated. Come on!"},{"id":203062,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"I see. To contend for scrolls, of course we should select the weakest team, hah."},{"id":203062,"idx":4,"roleId":28,"leftRight":1,"NpcWords":"Hey, what are you doing?"},{"id":203063,"idx":1,"roleId":28,"leftRight":1,"NpcWords":"What a real idiot! You're the weakest guy."},{"id":203201,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"We don't know who takes scrolls or who keeps them among 3 persons. So everyone seems to be our enemy."},{"id":203202,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"Ur, it's you? Though I should say sorry to Sakura. I still want to see what scroll your team have obtained. Take care!"},{"id":203202,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"It's because of Naruto that we're deemed as the weakest team. Hum, we're targeted by other teams."},{"id":203203,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"Er? The same scrolls? So no need to fight, see you, Sakura!"},{"id":203071,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Whir, we've walked in the forest for long, consuming much Stamina."},{"id":203072,"idx":1,"url":"mingren","name":"mingren1","leftRight":1,"NpcWords":"Ah, I'm really a little nervous when thinking about the imminent fight. But I felt comfortable after I peed and came back\u2026"},{"id":203072,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"Oh, aren't you a right-hander, Naruto? How can you bind a dart case to your left foot? Show your face, Counterfeit!"},{"id":203073,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Where is Naruto? Your morph technique is too bad!"},{"id":203073,"idx":2,"roleId":13,"leftRight":1,"NpcWords":"I didn't expect I would be spotted by you\u2026"},{"id":203211,"idx":1,"roleId":13,"leftRight":1,"NpcWords":"Hum, give me your scrolls and your lives."},{"id":203212,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"It's a morph. Where is Naruto? Is he beaten down?"},{"id":203212,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"Go and find Naruto in the woods over there, Sakura. Let me handle this guy."},{"id":203212,"idx":3,"roleId":13,"leftRight":1,"NpcWords":"Oh, you're talking big. Do you want to be cool before a girl?"},{"id":203213,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"That guy escaped\u2026ur, we should have a secret signal over the next days. We won't trust our partners without a secret signal even if we meet each other."},{"id":203081,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Hello, stop, secret signal! Opportunity!"},{"id":203081,"idx":2,"url":"mingren","name":"mingren1","leftRight":1,"NpcWords":"I know it. When a riot happened to massive enemies. It's the best opportunity to sneak into them. A quiet place\u2026"},{"id":203082,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Counterfeit, I know you've overheard underground, so you could say that long secret signal. It's so complicated. How could Naruto remember it?"},{"id":203082,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Coo, coo, what a strong little guy! It seems that I can enjoy my fight."},{"id":203083,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Sasuke, I would like to present this Cursed Seal to you before saying farewell. You will need my power. Come to me after passing the Chunin Trial, coo\u2026"},{"id":203221,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Oh, it hurts. What's wrong with this Cursed Seal? I lost control over my body\u2026"},{"id":203222,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Both Naruto and Sasuke get hurt. What should I do if other teams come and rob the scrolls?"},{"id":203222,"idx":2,"roleId":12,"leftRight":1,"NpcWords":"Only a weak woman like you is left. Are you belittling us? I'll kill you and get scrolls."},{"id":203091,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Whir, I'll definitely protect both of them."},{"id":203092,"idx":1,"roleId":11,"leftRight":1,"NpcWords":"Yoroi, you're so slow and fail to deal with it until now."},{"id":203092,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"I know that the man behind you is Orochimaru. Both Sasuke and Naruto are severely injured by him. I'll try to protect them."},{"id":203101,"idx":1,"roleId":19,"leftRight":0,"NpcWords":"That's Sakura. She's in trouble? What should I do? Those Sound Ninjas look strong\u2026"},{"id":203102,"idx":1,"roleId":14,"leftRight":1,"NpcWords":"You little guys just can't wait to die before our Sound Ninjas. Well, I'll eliminate you at one time."},{"id":203102,"idx":2,"roleId":19,"leftRight":0,"NpcWords":"Sakura, you're beaten so heavily. I won't let you show off. I'll first beat down these guys and then win Sasuke's love."},{"id":203102,"idx":3,"roleId":28,"leftRight":0,"NpcWords":"Though it's troublesome, how could we flee as men since Ino stood out to help them?"},{"id":203102,"idx":4,"roleId":21,"leftRight":0,"NpcWords":"Shikamaru, you can't defeat these guys though you're an ace at chess. I still want to eat many finest dishes. I don't want to die early."},{"id":203103,"idx":1,"roleId":14,"leftRight":1,"NpcWords":"Cursed Seal? Orochimaru gave Sasuke a Cursed Seal, why? Hum, just retreat for now\u2026"},{"id":203111,"idx":1,"roleId":20,"leftRight":1,"NpcWords":"Look, Neji, a good opportunity. Those guys gather there. We'll definitely get the scrolls."},{"id":203112,"idx":1,"roleId":25,"leftRight":1,"NpcWords":"Hum, two weakest teams join hands?"},{"id":203112,"idx":2,"roleId":20,"leftRight":1,"NpcWords":"Even six persons can't resist us. Let's start. Hidden weapon dart!"},{"id":203113,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"Wait, Neji and Tenten, stop! Sakura and other team members get hurt. We can't take advantage of others' difficulties."},{"id":203113,"idx":2,"roleId":25,"leftRight":1,"NpcWords":"Lee, you're stupid and too sympathetic. Hum, let's go. You're so lucky!"},{"id":203231,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Naruto, you finally wake up. Does your wound matter?"},{"id":203232,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Sorry to let you worry about me, Sakura. I'm just useless and was easily beaten down. Time went by so fast."},{"id":203232,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"I'm not sure if there are still heavens scrolls. Just play a trick and make a fake one. Let me first open it\u2026"},{"id":203232,"idx":3,"roleId":64,"leftRight":1,"NpcWords":"Hey, what are you doing? Want to practice fraud?"},{"id":203233,"idx":1,"roleId":64,"leftRight":1,"NpcWords":"I must take it seriously as I'm appointed examiner. I'll kill you if you play tricks again, little guy!"},{"id":203233,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Sorry, I'm wrong and I dare not do it again. But who are you? Even an examiner can't beat me so heavily and almost to death!"},{"id":203241,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Fortunately you're stopped before opening the scroll, otherwise all of us will get trapped in it Ninjutsu. You're so stupid, Naruto!"},{"id":203242,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Well, well, I'm wrong. However, how many teams can get scrolls among the remainders? I'm so hungry\u2026"},{"id":203242,"idx":2,"roleId":22,"leftRight":1,"NpcWords":"Ur? It's Naruto in the last place! Great, let's deploy Akamaru and the scroll will be ours!"},{"id":203251,"idx":1,"roleId":22,"leftRight":1,"NpcWords":"I didn't expect you guy wouldn't give in, so I have to show my real strength! Shino, don't stare blankly, move!"},{"id":203252,"idx":1,"roleId":23,"leftRight":1,"NpcWords":"Come on, insects, select your targets!"},{"id":203252,"idx":2,"roleId":24,"leftRight":1,"NpcWords":"What, what should I do\u2026I can't harm Naruto\u2026but I'll be scolded by Kiba if I don't attack\u2026(Muttering)"},{"id":203253,"idx":1,"roleId":23,"leftRight":1,"NpcWords":"Kiba, stop fighting. Hinata ran away, flushed and excited \u2026should we chase?"},{"id":203253,"idx":2,"roleId":22,"leftRight":1,"NpcWords":"Hello, what's wrong? What a good opportunity? Come back, Hinata. Why run? Hello, wait for us!"},{"id":203261,"idx":1,"roleId":39,"leftRight":0,"NpcWords":"We just received a message that Orochimaru appeared at the trial venue. He imposed a Cursed Seal on that kid from Uchiha Clan. It's urgent!"},{"id":203261,"idx":2,"roleId":33,"leftRight":0,"NpcWords":"No time to waste. I'll immediately go and bring him back."},{"id":203262,"idx":1,"roleId":33,"leftRight":1,"NpcWords":"Sasuke, you must immediately withdraw from the competition and receive treatment. That Cursed Seal is likely to have severe impact on you."},{"id":203262,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"Are you kidding? You're asking me to withdraw from it now? I'll never go back with you!"},{"id":203263,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Teacher Ebisu, Ninjas have their own dignity. We can die but won't give up what we can't. I'll definitely complete the trial!"},{"id":203263,"idx":2,"roleId":33,"leftRight":1,"NpcWords":"\u2026well, I see. I'll explain it to the village."},{"id":203121,"idx":1,"roleId":52,"leftRight":0,"NpcWords":"Hi, nice to see you again. Our team have got the scrolls, what about you?"},{"id":203122,"idx":1,"roleId":52,"leftRight":0,"NpcWords":"People may gather near the tower at the end, thus we're most likely to be robbed and ambushed. Let's move together for the sake of safety!"},{"id":203122,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Great! This guy appears to be dependable. "},{"id":203122,"idx":3,"roleId":43,"leftRight":1,"NpcWords":"Hah, it's time to hunt. I'll use my Ninjutsu to drag down you damned guys!"},{"id":203123,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"We're lucky to get the heavens scroll held by this guy. We passed the trial!"},{"id":203131,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Ur? Those guys again, hum!"},{"id":203132,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Hey,you!! Our last fight hasn't finished yet. Come on!"},{"id":203133,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Kankuro, we've collected necessary scrolls, so we don't need to have a meaningless fight any more."},{"id":203133,"idx":2,"roleId":52,"leftRight":0,"NpcWords":"Right, this elder sister is correct. Given the next competition, it will be bad if both of us are weakened here."},{"id":203133,"idx":3,"roleId":52,"leftRight":0,"NpcWords":"Anyway, congratulations on your having collected scrolls. Make more preparations for next trial. See you then. "},{"id":203133,"idx":4,"roleId":27,"leftRight":0,"NpcWords":"\u2026I always feel this guy is a little strange\u2026"},{"id":203133,"idx":5,"roleId":52,"leftRight":1,"NpcWords":"Hah, Lord Orochimaru, messages have been collected. It's too easy for me as an agent Ninja."},{"id":203141,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"Kill\u2026kill\u2026"},{"id":203142,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"\u2026all, kill all\u2026I feel so excited\u2026"},{"id":203142,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"What's wrong with this guy? What's wrong with this terrible Chakra flow?"},{"id":203143,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Kankuro, you're stupid. Let's leave with Gaara quickly or we'll be killed if he gets too excited."},{"id":203143,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"What's wrong with that guy with panda eyes? His Chakra is so strong. I feel that Chakra is so familiar."},{"id":203271,"idx":1,"roleId":39,"leftRight":0,"NpcWords":"That man...... There is a problem......"},{"id":203272,"idx":1,"roleId":39,"leftRight":0,"NpcWords":"Stop, you guys want to leave Konoha right now? Who the hell are you?"},{"id":203272,"idx":2,"roleId":52,"leftRight":1,"NpcWords":"I was participate in this year Ninja trial. But don't have many strength to face so many excellent ninja and also I need to give up."},{"id":203272,"idx":3,"roleId":39,"leftRight":0,"NpcWords":"Don't think you can fool me. You have Orochimaru breath inside you and my body can feel it."},{"id":203272,"idx":4,"roleId":52,"leftRight":1,"NpcWords":"Hee hee, you found it. Indeed, this is Orochimaru breath. He must proud that he have very good subordinates."},{"id":203273,"idx":1,"roleId":39,"leftRight":0,"NpcWords":"This guy, his strength is very strong. What are you purpose coming to the Konoha?"},{"id":203281,"idx":1,"roleId":52,"leftRight":1,"NpcWords":"It is really a tough woman......"},{"id":203282,"idx":1,"roleId":52,"leftRight":1,"NpcWords":"It is really a trouble woman. Need to think of a way to quickly escape and didn't make any confusion again......"},{"id":203282,"idx":2,"roleId":47,"leftRight":1,"NpcWords":"Why are you still waiting in here. Orochimaru have been waiting impatiently."},{"id":203282,"idx":3,"roleId":39,"leftRight":0,"NpcWords":"And there are more tough guy......"},{"id":203282,"idx":4,"roleId":52,"leftRight":1,"NpcWords":"Kimimaro? How did you get here?"},{"id":203282,"idx":5,"roleId":47,"leftRight":1,"NpcWords":"Orochimaru let me take a look. Indeed, this bug delaying Konoha. Bloom, go the hell!"},{"id":203283,"idx":1,"roleId":39,"leftRight":0,"NpcWords":"Well, this guy, really is a ...... (fell)"},{"id":203283,"idx":2,"roleId":47,"leftRight":1,"NpcWords":"...... Come on, don't let Orochimaru wait more longer......"},{"id":204011,"idx":1,"roleId":33,"leftRight":0,"NpcWords":"So many people have passed the 2nd trial. Did you let them go, Anko Mitarashi?"},{"id":204012,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"So many initiates with potential. Next, please fight to death for the reputation of your village!"},{"id":204012,"idx":2,"roleId":35,"leftRight":0,"NpcWords":"The qualifying competition of 3rd trial is carried out one-on-one among individuals. Surrender immediately if anyone doesn't want to die. "},{"id":204012,"idx":3,"roleId":11,"leftRight":1,"NpcWords":"Am I supposed to be the first one. I'm so lucky. I'll break your eardrum and hear you beg me."},{"id":204161,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Hum, it's finally my turn. Let me show you techniques of my Puppet Crow."},{"id":204162,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"The very essence of Puppet Technique is to take someone by surprise. Guess how many fatal gears my Crow have?"},{"id":204021,"idx":1,"roleId":12,"leftRight":1,"NpcWords":"Never be so complacent after winning a single victory. Hum, come on, I'll be your next opponent!"},{"id":204022,"idx":1,"roleId":12,"leftRight":1,"NpcWords":"Are you keeping silent for affectations? You're just nothing. To deal with you, I just need to use one-handed wind tunnel."},{"id":204171,"idx":1,"roleId":17,"leftRight":1,"NpcWords":"Haha, it will be my turn soon. Just let that damned Sasuke experience my strength!"},{"id":204172,"idx":1,"roleId":17,"leftRight":1,"NpcWords":"Ah, it's my turn finally. I'm getting highly excited. But I tend to feel hungry when I get excited. I really want to eat ramen\u2026"},{"id":204031,"idx":1,"roleId":13,"leftRight":1,"NpcWords":"It's my turn now? Let me see your strength."},{"id":204032,"idx":1,"roleId":13,"leftRight":1,"NpcWords":"I won't show mercy even if my opponent is a little guy. With a flexible body operated by Chakra, I can attach to and break your bones."},{"id":204181,"idx":1,"roleId":23,"leftRight":1,"NpcWords":"Ur? Er, it's my turn\u2026"},{"id":204182,"idx":1,"roleId":23,"leftRight":1,"NpcWords":"First release female insects, then male insects may track and launch an attack by scent, let's start\u2026"},{"id":204041,"idx":1,"roleId":55,"leftRight":0,"NpcWords":"Ino, never be defeated by Sakura in either Ninjutsu or love!"},{"id":204041,"idx":2,"roleId":19,"leftRight":1,"NpcWords":"Teacher Asuma, you can rest assured that I'll never lose."},{"id":204042,"idx":1,"roleId":19,"leftRight":1,"NpcWords":"Look, this is my strength! I'll never be defeated by that emotional Sakura in either fight or love."},{"id":204191,"idx":1,"roleId":25,"leftRight":1,"NpcWords":"Ur? Are you my opponent? So disappointed. Only Sasuke and that Hidden Sand Ninja with panda eyes can arouse my desire to fight."},{"id":204192,"idx":1,"roleId":25,"leftRight":1,"NpcWords":"I'll let you see how I'm different from you as a genius. Let me guess how many minutes it will take to win you. "},{"id":204051,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Tenten's hidden weapon won't miss a shot. He will definitely win!"},{"id":204051,"idx":2,"roleId":25,"leftRight":0,"NpcWords":"Teacher Guy is too optimistic. If his opponent is a Ninja doing well in wind, it's hard to say\u2026"},{"id":204052,"idx":1,"roleId":20,"leftRight":1,"NpcWords":"My hidden weapon will never miss a shot. I'm wondering how many Ninja Tools you can withstand."},{"id":204201,"idx":1,"roleId":18,"leftRight":1,"NpcWords":"Ur? Time to appear? Where is Sasuke? I hope he can watch my competition."},{"id":204202,"idx":1,"roleId":18,"leftRight":1,"NpcWords":"Great! Come on! Sakura, I'll never let Sasuke see my disgrace!"},{"id":204202,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"No worry. Sasuke will see only your image as a woman even if he watches it\u2026"},{"id":204202,"idx":3,"roleId":18,"leftRight":1,"NpcWords":"What? Don't tell the truth, Teacher Kakashi! Do cheer me up by my side, teacher. I'm moving."},{"id":204061,"idx":1,"roleId":14,"leftRight":1,"NpcWords":"Why didn't this damned trial end? If it continues, Lord Orochimaru will get angry\u2026"},{"id":204062,"idx":1,"roleId":14,"leftRight":1,"NpcWords":"Hello, let's end it quickly. I have no time to play with you. You'll say farewell to this world soon."},{"id":204211,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"No hurry. Next competition will occur between you and me. Write down your last words quickly!"},{"id":204212,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Fanning it may generate wind and sand, then darken the heaven and earth and finally wipe out all present people. My Wind Fan will tear you into pieces."},{"id":204071,"idx":1,"roleId":22,"leftRight":1,"NpcWords":"\u2026who is my opponent? We had better give up if it's that terrible Hidden Sand Ninja with panda eyes, right?"},{"id":204072,"idx":1,"roleId":22,"leftRight":1,"NpcWords":"Hah, I'm so lucky. It isn't those terrible Hidden Sand Ninjas, Akamaru. Let's be at concert pitch."},{"id":204072,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Hi, Kiba, bringing a dog with you will hamper the competition!"},{"id":204072,"idx":3,"roleId":22,"leftRight":1,"NpcWords":"Shit! What's that weakest guy shouting? Akamaru is a Ninja Hound and allowed to attend the fight. Come and see our partner."},{"id":204221,"idx":1,"roleId":27,"leftRight":1,"NpcWords":"Damn it! That bitten Cursed Seal increasingly hurts. I'll lose control over Chakra\u2026"},{"id":204222,"idx":1,"roleId":27,"leftRight":1,"NpcWords":"I'll never be defeated by anyone until I kill that guy I must kill - Itachi!"},{"id":204081,"idx":1,"roleId":24,"leftRight":1,"NpcWords":"Oh\u2026it will be my turn soon..."},{"id":204082,"idx":1,"roleId":24,"leftRight":1,"NpcWords":"\u2026I must fight\u2026but, but\u2026"},{"id":204082,"idx":2,"roleId":25,"leftRight":0,"NpcWords":"Hinata, you're not qualified to be a Ninja. You're so kind, amicable and humble. Miss Zong from Main House, you'll be unable to change yourself."},{"id":204082,"idx":3,"roleId":24,"leftRight":1,"NpcWords":"Brother Neji\u2026no, no, I'll fight\u2026I don't want to give up like Naruto I have been watching\u2026"},{"id":204231,"idx":1,"roleId":28,"leftRight":1,"NpcWords":"Time to appear? It's really troublesome. I hope this boring trial will end soon\u2026"},{"id":204232,"idx":1,"roleId":28,"leftRight":1,"NpcWords":"Hello, I can directly admit failure if possible because I'm not interested in becoming a Chunin at all\u2026"},{"id":204091,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"Great! It's my turn finally. Today I'll demonstrate my youthful vigor before Sakura!"},{"id":204092,"idx":1,"roleId":26,"leftRight":1,"NpcWords":"I know you have strong strength. I can't defeat you with my current vitality skill, so..."},{"id":204092,"idx":2,"roleId":26,"leftRight":1,"NpcWords":"Teacher Guy, I must use my Lotus this time. I'll become a great Ninja even if I don't know about Ninjutsu and Illusion Skill!"},{"id":204093,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Enough, Lee. You still carried out your ninja spirit even if you lost your consciousness. You're a Hardworking Genius."},{"id":204241,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"The weak should die..."},{"id":204242,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"I don't understand why I protected, why I cared for and why I cared about\u2026oh, let's continue. I just know I need to kill more."},{"id":204243,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"Hum, next time you'll definitely die."},{"id":204243,"idx":2,"roleId":31,"leftRight":1,"NpcWords":"Great! Gaara didn't go crazy this time. I don't need to worry I'll be killed by Gaara."},{"id":204243,"idx":3,"roleId":32,"leftRight":1,"NpcWords":"Oh, I'm saved. What I fear most isn't the enemy, but Gaara who is out of control\u2026"},{"id":204101,"idx":1,"roleId":55,"leftRight":0,"NpcWords":"Hello, Choji, make greater efforts. Shikamaru has passed the competition. Come on!"},{"id":204102,"idx":1,"roleId":21,"leftRight":1,"NpcWords":"That Hidden Sand Ninja Monster was really terrible. I don't want to compete\u2026roast meat, I'll go and eat roast meat once the competition ends."},{"id":204102,"idx":2,"roleId":19,"leftRight":0,"NpcWords":"What? Never be a good-for-nothing. You're already too fat. No girl will like you if you continue eating like that."},{"id":204102,"idx":3,"roleId":21,"leftRight":1,"NpcWords":"What? I'm not fat but only a little buxom."},{"id":204103,"idx":1,"roleId":35,"leftRight":0,"NpcWords":"The competition ends! The formal selection will occur in one month. Please make good preparations, winners!"},{"id":204251,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"The formal selection for Chunin Trial will occur in a few days. Discuss it with Teacher Iruka while eating Ramen."},{"id":204252,"idx":1,"roleId":30,"leftRight":1,"NpcWords":"What? Want me to become your training opponent? Hello, wait, don't come towards me directly, Naruto!"},{"id":204253,"idx":1,"roleId":30,"leftRight":0,"NpcWords":"You just can't change your impatient shortcoming. Ebisu is very good at control over Chakra. I'll ask him to help you."},{"id":204111,"idx":1,"roleId":34,"leftRight":1,"NpcWords":"What? Let me specially train Naruto? Honestly, I don't want to deal with that Nine Tails, but\u2026"},{"id":204112,"idx":1,"roleId":34,"leftRight":1,"NpcWords":"Hello, I wouldn't be your special training teacher weren't it for Iruka. Follow me. Today's training will occur in Hot Spring Village."},{"id":204261,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"This lustful private teacher is always fierce to me, hum\u2026"},{"id":204262,"idx":1,"roleId":34,"leftRight":1,"NpcWords":"Hello, Nine Tails, I've told you not to use Harem Jutsu during the training."},{"id":204263,"idx":1,"roleId":34,"leftRight":1,"NpcWords":"Hi, how can you be involved in such shameless things like peeping at the female bathhouse? I won't let you go. "},{"id":204263,"idx":2,"roleId":91,"leftRight":1,"NpcWords":"Damn it! Don't make noise. I'll be definitely screwed if I'm spotted by those women."},{"id":204121,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ah, ah, lustful private teacher. Get up. How can you be easily stunned? Who will specially train me?"},{"id":204122,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"You stunned my private teacher, so you should instruct me. What a Pervy Sage!"},{"id":204122,"idx":2,"roleId":91,"leftRight":1,"NpcWords":"What a rude little guy! But I will teach you if you can maintain Sexy Jutsu as a beauty all the time."},{"id":204271,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"Hum, is he that little guy with Nine Tails Demon Fox sealed, stupider than imagined..."},{"id":204272,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"Hello, little guy, did you find you have two types of Chakra inside? To become strong, you must learn to use the other power."},{"id":204273,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"Oh, did you already use that power? You look stupid and sometimes may behave unexpectedly."},{"id":204131,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"Is it time to teach him Summon Skill\u2026"},{"id":204132,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"This is the covenant between our family and Summon Gama Kichi passing down over generations. I'll see if you can pass the stage."},{"id":204133,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Look, I succeeded, Pervy Sage. Who is this Gama Bunta?"},{"id":204133,"idx":2,"roleId":91,"leftRight":1,"NpcWords":"Hah, King Gama Bunta was summoned. He's the first one after 4th Hokage."},{"id":204133,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Well, let's wait and see what will happen at Chunin Selection Competition!"},{"id":204141,"idx":1,"roleId":59,"leftRight":1,"NpcWords":"Hi, isn't he that famous dirty old man Lord Jiraiya in Hidden Leaf? Let's go and say hello to him."},{"id":204141,"idx":2,"roleId":60,"leftRight":1,"NpcWords":"Er\u2026I didn't expect I would meet Lord Jiraiya here."},{"id":204142,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Hi, it's you. Are you carrying out your quests? Come and compete with my apprentice if you have time. He's learning new techniques."},{"id":204142,"idx":2,"roleId":59,"leftRight":1,"NpcWords":"Well, I'll be glad to do it if requested by Lord. Jiraiya. Hope this little guy won't be defeated so easily."},{"id":204143,"idx":1,"roleId":59,"leftRight":1,"NpcWords":"The power\u2026this little guy is just like us and also a Jinchuriki. We belittled him just now. "},{"id":204151,"idx":1,"roleId":60,"leftRight":1,"NpcWords":"No wonder that Lord Jiraiya accepted such a little guy as his apprentice, so he has power of Nine Tails inside."},{"id":204152,"idx":1,"roleId":60,"leftRight":1,"NpcWords":"Lord Jiraiya intended to let our Jinchuriki teach this little guy how to use power of Tailed Beasts? Well, look!"},{"id":204153,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Thanks for your instructions. Naruto, I guess you should have comprehended power well, right?"},{"id":204153,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Yes, Pervy Sage, I feel I can summon that power though I can't control it skillfully for now."},{"id":204281,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ah, I really want to have a look at Sasuke new jutsu. I might have been better than him, hee hee."},{"id":204282,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Kakashi, where is Sasuke?"},{"id":204282,"idx":2,"roleId":83,"leftRight":1,"NpcWords":"He is on the new Ninjutsu training, He should still be in that place......"},{"id":204282,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"What, I think only me that learn new jutsu...... Kakashi teacher, let's exchange blow with me. I want you to have a look at my new skills!"},{"id":204282,"idx":4,"roleId":83,"leftRight":1,"NpcWords":"Call Naruto even if you're right. This is really amazing power and more enhance version......"},{"id":204282,"idx":5,"roleId":91,"leftRight":0,"NpcWords":"Kakashi, Naruto if you underestimate it, this guy might lose his apprentice."},{"id":204282,"idx":6,"roleId":83,"leftRight":1,"NpcWords":"Jiraiya, how do you go back to the village? Don't said you are the one that taught Naruto? Okay, Naruto, then......"},{"id":204283,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"This, this is Jiraiya technique. Now Naruto can summon Gamabunta too?"},{"id":204283,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"This kid has unlimited potential. Sooner or later, he will become like 4th Hokage. After all, they are father and son......"},{"id":204291,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Haven't returned to the village and we should go to see the teacher."},{"id":204292,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Teacher, long time no see......"},{"id":204292,"idx":2,"roleId":100,"leftRight":1,"NpcWords":"Well, it's Jiraiya. It's already been long time since return to the village."},{"id":204292,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Grandpa. Come on and fight me. I must defeat you in order to become hokage!!!"},{"id":204293,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Oh oh oh oh oh, damn ~ ~ ~ ~ ~ ~ this is doesn't work."},{"id":204293,"idx":2,"roleId":100,"leftRight":0,"NpcWords":"Ha ha ha ha ha ha ha ha ha ha ha ha ha ha, Naruto. This kid seems interesting......."},{"id":204293,"idx":3,"roleId":100,"leftRight":0,"NpcWords":"Surprisingly, you turned out to be his master. The fire will always continues."},{"id":204293,"idx":4,"roleId":91,"leftRight":0,"NpcWords":"Yes, this kid later perhaps can become more than Hokage."},{"id":205011,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"I didn't expect that so many strong initiates would be shortlisted for the selection competition this year. Right? Lord Kazekage ..."},{"id":205011,"idx":2,"roleId":87,"leftRight":1,"NpcWords":"Lord Hokage, we can watch the Chunin Finals together this year. I'm also looking forward to appreciating performance of young Ninjas."},{"id":205012,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"The formal selection competition now starts. It's time for candidates to enter the arena. The first competition is Neji Hyuga versus Naruto Uzumaki!"},{"id":205012,"idx":2,"roleId":25,"leftRight":1,"NpcWords":"The weakest guys like you won't have an opportunity to defeat me as a genius. How can you understand my pain as Hyuga Branch House?"},{"id":205012,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Stop talking nonsense there. You aren't the only special guy in this world."},{"id":205012,"idx":4,"roleId":25,"leftRight":1,"NpcWords":"Hum, it seems that you haven't yet understood what difference exists between geniuses and some guys like you!"},{"id":205181,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"Great, Naruto won. Though this may disappoint Brother Neji \u2026 Next guy is Shino? (muttering)"},{"id":205182,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"Hi, Shino, come on. Among our team, only you are on the shortlist!"},{"id":205182,"idx":2,"roleId":23,"leftRight":1,"NpcWords":"Er? Er?"},{"id":205021,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"The 2nd competition is Temari from Hidden Sand Village versus Shikamaru Nara from Hidden Leaf!"},{"id":205022,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"I will attack. It's no use hiding. I'll use my strongest wind power to tear you into pieces."},{"id":205022,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"Why is my opponent a woman? Alas, it's really troublesome. I'm jealous of those clouds in the sky. I'm not motivated at all."},{"id":205022,"idx":3,"roleId":31,"leftRight":1,"NpcWords":"Hi, don't belittle me because I'm a woman. How can sluggish men like you resist me?"},{"id":205023,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"This fight doesn't matter. When Lord Kazekage gives a signal, it's time for our Hidden Sand Ninjas to move!"},{"id":205191,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Lord Kazekage also comes here. Hope everything will go well..."},{"id":205192,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Hum, never reveal all of Crow's gears in the fight. A real fight is about to start as scheduled."},{"id":205031,"idx":1,"roleId":87,"leftRight":1,"NpcWords":"\u2026hum, it's time to start\u2026"},{"id":205032,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Bad! Why did everyone fall into a lethargic sleep? What are the falling feathers\u2026"},{"id":205032,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"It's Illusion Skill. What happened\u2026"},{"id":205032,"idx":3,"roleId":87,"leftRight":1,"NpcWords":"Hum, this babyish game should end, Hokage's guys. Start fighting!"},{"id":205032,"idx":4,"roleId":43,"leftRight":1,"NpcWords":"A signal is sent! Start to attack, everyone."},{"id":205201,"idx":1,"roleId":57,"leftRight":1,"NpcWords":"It's a signal sent by Lord Kazekage. Start the General Offensive, Hidden Sand Ninjas."},{"id":205202,"idx":1,"roleId":57,"leftRight":1,"NpcWords":"Hum, leveraging the opportunity of Chunin Trial to capture the Hidden Leaf. What a good strategy!"},{"id":205041,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"What's going on, Lord Kazekage? Do you want to tear up the peace treaty?"},{"id":205042,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"I didn't expect that Hidden Sand Ninjas would collude with Sound Ninjas to betray the Hidden Leaf. Chunin Trial and the treaty are only your camouflage."},{"id":205042,"idx":2,"roleId":44,"leftRight":1,"NpcWords":"Hah, hah, we'll bury you all today, guys from the Hidden Leaf."},{"id":205043,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Lord Kazekage, if you start the war rashly, two parties will be weakened simultaneously. You village won't benefit from it at all!"},{"id":205043,"idx":2,"roleId":87,"leftRight":1,"NpcWords":"You become foolish as you're old, hah, the Hidden Leaf will end today, Teacher Sarutobi..."},{"id":205051,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Teacher Sarutobi? This voice is, Orochimaru\u2026\u2026"},{"id":205052,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"I see. Disguising yourself as 4th Kazekage to implement your conspiracy. It's your style, Orochimaru\u2026"},{"id":205052,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Hah, now hundreds of Hidden Sand Ninjas and Sound Ninjas are attacking Hidden Leaf. You'll die here today, teacher."},{"id":205211,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Come on, wind, wipe out everything in Hidden Leaf!"},{"id":205212,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Though I don't know why Lord Kazekage joined hands with Sound Ninjas, ninjas must obey orders!"},{"id":205221,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"All of Crow's gears enabled! I'll let you experience profound Puppet Technique!"},{"id":205222,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"The war started. Hello, what's wrong, Gaara? Are you okay?"},{"id":205222,"idx":2,"roleId":40,"leftRight":1,"NpcWords":"...Oooh ah\u2026"},{"id":205222,"idx":3,"roleId":32,"leftRight":1,"NpcWords":"It's bad! Hope Gaara won't be out of control at the moment. Temari, let's resist the enemies and stop them from irritating Gaara!"},{"id":205061,"idx":1,"roleId":57,"leftRight":1,"NpcWords":"Gaara, the war started. You must control your Chakra because you're our most important Combat power!"},{"id":205062,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"Oooh\u2026oooh ah\u2026"},{"id":205062,"idx":2,"roleId":57,"leftRight":1,"NpcWords":"Stupid, this guy is already out of control\u2026 Temari and Kankuro, leave here with Gaara for now. Let me fight."},{"id":205231,"idx":1,"roleId":57,"leftRight":1,"NpcWords":"Hum, Hidden Leaf is worthy of its reputation. Raided by both Hidden Sand Ninjas and Sound Ninjas, it didn't collapse. "},{"id":205232,"idx":1,"roleId":57,"leftRight":1,"NpcWords":"Gaara is one of our most important Combat power. Do trap those guys from Hidden Leaf here and stop them from irritating Gaara again!"},{"id":205232,"idx":2,"roleId":5,"leftRight":1,"NpcWords":"Yes, I'll protect Lord Gaara!"},{"id":205232,"idx":3,"roleId":6,"leftRight":1,"NpcWords":"Do trap Hidden Leaf to death here!"},{"id":205071,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"What's that terrible Chakra on that young Hidden Sand Ninja? Take care\u2026"},{"id":205072,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Sakura, go and break Naruto's Illusion Skill. You and Sasuke, chase Gaara. Do take care."},{"id":205072,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Yes! Oh, shit! There are too many Sound Ninjas and Hidden Sand Ninjas."},{"id":205072,"idx":3,"roleId":45,"leftRight":1,"NpcWords":"Hah, let's have fun together, guys from Hidden Leaf!"},{"id":205241,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Naruto is stupid and deeply caught in Illusion Skill! Break!"},{"id":205242,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ah? It's Sakura? What happened? Why did I fall asleep?"},{"id":205242,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Stupid! You're caught in Illusion Skill. Hidden Sand Ninjas have worked with Sound Ninjas to fight against us. Teacher Kakashi let us go and chase Gaara."},{"id":205242,"idx":3,"roleId":13,"leftRight":1,"NpcWords":"Stop, where are you going, boy? Today's Hidden Leaf is a grave. You'll be buried here!"},{"id":205081,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Naruto and Sakura, go and chase them. Those three Hidden Sand Ninjas are running away."},{"id":205082,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Where was that little guy with panda eyes?"},{"id":205082,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Sasuke and Naruto, some Sound Ninjas seem to be chasing us. We must find a way to break away from them."},{"id":205082,"idx":3,"roleId":46,"leftRight":1,"NpcWords":"Shit! The little guy ran so fast!"},{"id":205251,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Immediately break away from chasers. Shit! They just don't want to stop!"},{"id":205252,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"I don't understand why we should chase those Hidden Sand Ninjas because Hidden Leaf is in a crisis now\u2026"},{"id":205252,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Teacher Kakashi said that guy with panda eyes has terrible Chakra. Do eliminate him before he damages the Hidden Leaf."},{"id":205252,"idx":3,"roleId":5,"leftRight":1,"NpcWords":"I won't let you harm Lord Gaara. Stop!!!"},{"id":205091,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"Shit! Those guys from the Hidden Leaf keep chasing. Never irritate Gaara again in case he will be out of control."},{"id":205092,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"They even chased here. Temari, first leave with Gaara and I'll resist them for a while."},{"id":205092,"idx":2,"roleId":32,"leftRight":1,"NpcWords":"I guess you've never experienced real terribleness in the world and real Gaara. Move, my Puppet Crow!"},{"id":205261,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Never let them approach Gaara again\u2026"},{"id":205262,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"I'll eliminate you here at one time. Hello, Gaara, hold out and don't let that monster come out!"},{"id":205101,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"These three Hidden Leaf Ninjas are so irksome. Are you okay, Gaara? Never be out of control, hi, Gaara?"},{"id":205102,"idx":1,"roleId":27,"leftRight":0,"NpcWords":"Though I don't know about the intent of you Hidden Sand Ninjas, I want to stop you and see your real faces."},{"id":205102,"idx":2,"roleId":40,"leftRight":1,"NpcWords":"Whir\u2026you're my prey. Only by killing you can I feel I'm still alive."},{"id":205102,"idx":3,"roleId":40,"leftRight":1,"NpcWords":"It's so exciting!"},{"id":205271,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"I get hurt. It's unforgivable!"},{"id":205272,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"This guy transformed himself again. Is this the monster in his heart?"},{"id":205272,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"Who\u2026who is this guy? Facing him, I can't control my actions..."},{"id":205272,"idx":3,"url":"yiwei","name":"yiwei","leftRight":1,"NpcWords":"Goo goo quack\u2026"},{"id":205111,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Gosh, Gaara is out of control and One Tail Shukaku of Sand appeared. We'll all die here\u2026"},{"id":205112,"idx":1,"roleId":40,"leftRight":1,"NpcWords":"To thank you for letting me fully enjoy myself, I'll let you experience real power of Avatar of Sand Shukaku!"},{"id":205112,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Like you, there is also a monster in my body, so I understand about your feeling. Now let's end it finally."},{"id":205113,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"I really understand that lonely feeling, but I won't allow you to harm those who are important to me because they've saved me in loneliness."},{"id":205113,"idx":2,"roleId":40,"leftRight":1,"NpcWords":"\u2026you've become so strong because of love? Well, stop fighting..."},{"id":205281,"idx":1,"roleId":45,"leftRight":1,"NpcWords":"Hey, we're called Sound Five. We'll never disappoint Lord Orochimaru!"},{"id":205282,"idx":1,"roleId":45,"leftRight":1,"NpcWords":"Hum, Hidden Sand Ninjas are so stupid. Lord Orochimaru killed 4th Kazekage earlier, but they didn't know and still fight along with us."},{"id":205282,"idx":2,"roleId":44,"leftRight":1,"NpcWords":"Hi, stop talking. Don't reveal secrets before the war ends."},{"id":205121,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Orochimaru, what's your purpose? Purely ruin the Hidden Leaf to vent your anger?"},{"id":205122,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"It's my interest only\u2026my men have set the barrier. Nobody will disturb our fight, Teacher Sarutobi."},{"id":205122,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Come on! Corrupt Reincarnation! 2nd Hokage Tobirama, you should be familiar with this face, right, teacher?"},{"id":205122,"idx":3,"url":"feijian","name":"feijian1","leftRight":1,"NpcWords":"\u2026long time no see, Sarutobi\u2026I didn't expect I would meet you in the way of reincarnation."},{"id":205291,"idx":1,"url":"feijian","name":"feijian1","leftRight":1,"NpcWords":"Is this, current Hidden Leaf Village? What happened? It's experiencing a war?"},{"id":205292,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Lord 2nd Hokage, yes, it's current Hidden Leaf Village. As a fire guardian, I have to fight against and offend you."},{"id":205292,"idx":2,"url":"feijian","name":"feijian1","leftRight":1,"NpcWords":"Corrupt Reincarnation is originally a Kinjutsu developed by me. I didn't expect it would be imposed on me by subsequent ninjas\u2026"},{"id":205131,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"The pursuit for Ninjutsu is unlimited. Look, Kinjutsu improved by me has exceeded you, teacher!"},{"id":205132,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Corrupt Reincarnation, next one! 1st Hokage Hashirama!"},{"id":205132,"idx":2,"url":"zhujian","name":"zhujian1","leftRight":1,"NpcWords":"\u2026I have no choice but to fight due to this Kinjutsu, no matter who you are."},{"id":205301,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":1,"NpcWords":"Is this current Hidden Leaf Village? Ah, I miss it so much. Where is my granddaughter Tsuna..."},{"id":205302,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":1,"NpcWords":"Hi, are you current Hokage? Already the 3rd one. It's great! Immediately beat me down!"},{"id":205302,"idx":2,"roleId":100,"leftRight":0,"NpcWords":"This is legendary God of Ninja\u2026I feel he has an unexpected personality\u2026"},{"id":205302,"idx":3,"roleId":100,"leftRight":0,"NpcWords":"Sorry, Lord Hashirama, please forgive me!"},{"id":205141,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"I'm a real genius, completely different from those normal Ninjas. However, you just didn't recognize me\u2026"},{"id":205142,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Next, your favorite apprentice, Teacher Sarutobi. To let him become Hokage, you even wanted to push aside a genius like me."},{"id":205142,"idx":2,"url":"shuimen","name":"shuimen1","leftRight":1,"NpcWords":"Teacher Sarutobi? Oh\u2026my body is completely out of control\u2026"},{"id":205311,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Oh, it's so funny, Teacher Sarutobi. You're attacked by your respected teacher and favorite apprentice. Do you feel good?"},{"id":205312,"idx":1,"url":"shuimen","name":"shuimen1","leftRight":1,"NpcWords":"Are you Orochimaru? Yes, so you're using Corrupt Reincarnation to retaliate upon the Hidden Leaf. Sorry, Teacher Sarutobi, beat me quickly!"},{"id":205312,"idx":2,"roleId":100,"leftRight":0,"NpcWords":"Orochimaru, it's because I saw through you that I chose Minato as 4th Hokage. But now, you still obsess about it."},{"id":205312,"idx":3,"roleId":89,"leftRight":1,"NpcWords":"Hum, it's no use talking, Teacher Sarutobi. Seeking ultimate Ninjutsus is Ninjas' goal. Only a genius like me can do it."},{"id":205151,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Hidden Leaf once brought many pleasures to me and so many experimental materials, hah\u2026"},{"id":205152,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Do you know, teacher, I've completed an immortal Kinjutsu. Next, I should obtain a good body."},{"id":205152,"idx":2,"roleId":100,"leftRight":0,"NpcWords":"So you intend to seize Sasuke's body\u2026I regret not killing you in the past. Today I'll use Reaper Death Seal to solve it."},{"id":205153,"idx":1,"roleId":100,"leftRight":0,"NpcWords":"Reaper Death Seal can only seal his hands\u2026Ninjas from the Hidden Leaf, please carry forward Fire's Will and fight to protect our village!"},{"id":205153,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Damned old guy even seized my hands and Kinjutsu! I have to leave. "},{"id":205161,"idx":1,"roleId":62,"leftRight":1,"NpcWords":"It's still late\u2026"},{"id":205161,"idx":2,"roleId":61,"leftRight":1,"NpcWords":"I didn't expect that the Hidden Leaf would be destroyed so badly. Orochimaru committed it."},{"id":205162,"idx":1,"roleId":35,"leftRight":0,"NpcWords":"These two guys are Sound Ninjas or Hidden Sand Ninjas? I won't let you run away."},{"id":205162,"idx":2,"roleId":62,"leftRight":1,"NpcWords":"hi, you misunderstood us. We're not enemies."},{"id":205162,"idx":3,"roleId":36,"leftRight":0,"NpcWords":"Don't pretend not to be that. The Hidden Leaf is just destroyed by those guys like Hidden Sand Ninjas claiming they weren't enemies."},{"id":205171,"idx":1,"roleId":61,"leftRight":1,"NpcWords":"Hey, calm down. I can explain it\u2026"},{"id":205172,"idx":1,"roleId":61,"leftRight":1,"NpcWords":"I'm here to eliminate the misunderstanding between Sand and Hidden Leaf."},{"id":205172,"idx":2,"roleId":37,"leftRight":0,"NpcWords":"What misunderstanding? Destroying our village is a misunderstanding!"},{"id":205172,"idx":3,"roleId":38,"leftRight":0,"NpcWords":"I'll first kill you!"},{"id":205173,"idx":1,"roleId":61,"leftRight":0,"NpcWords":"Hello, I guess you should understand what I said, right? I'm one of Lord Jiraiya's friends and was commissioned by him to investigate about Sound Ninjas and Kazekage."},{"id":205173,"idx":2,"roleId":62,"leftRight":0,"NpcWords":"We've found 4th Kazekage's corpse. All this was Orochimaru's conspiracy. He wanted to provoke the war between Sand and Hidden Leaf to benefit himself."},{"id":205173,"idx":3,"roleId":57,"leftRight":0,"NpcWords":"Damn it! Our Sand were thoroughly fooled by Orochimaru\u2026sorry, we owe Hidden Leaf too much\u2026"},{"id":205321,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Other villages also come to offer their condolences......"},{"id":205322,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Kakashi, the third generation died. The people from other village have come to offer their condolences."},{"id":205322,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Well, we need to be more careful. Now Konoha is in very weak situation. There is no guarantee if somebody will take this opportunity."},{"id":205322,"idx":3,"roleId":74,"leftRight":1,"NpcWords":"Konoha at the fault. They didn't executed Orochimaru and that is the cause of this situation."},{"id":205322,"idx":4,"roleId":74,"leftRight":1,"NpcWords":"The fourth generation was assassinated. Be sure not spread it to other villages. We should make compensation!"},{"id":205322,"idx":5,"roleId":54,"leftRight":0,"NpcWords":"What! Now the third generation has passed away. Don't said such a thing!"},{"id":205331,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Don't make this situation more worse."},{"id":205332,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Well, as you can see, Konoha now in difficult situation. If we blamed each other again, this situation will not improved."},{"id":205332,"idx":1,"roleId":75,"leftRight":1,"NpcWords":"This trouble\u2026 We must end it up."},{"id":205332,"idx":2,"roleId":54,"leftRight":0,"NpcWords":"With this kind of attitude, you offer your condolences? I see there is no excuse for gather more intelligence!"},{"id":205332,"idx":3,"roleId":75,"leftRight":1,"NpcWords":"Spying? Come on, don't underestimate me as Raikage. We don't care with your argument."},{"id":205333,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Stop arguing! Don't fight each other. Or you want to give this opportunity to Orochimaru?"},{"id":205333,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Jiraiya......"},{"id":205333,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"The third generation has died. If we attack each other, your village will end and Konoha wil be the next! This is what you want?"},{"id":205333,"idx":4,"roleId":74,"leftRight":1,"NpcWords":"Oh......"},{"id":205333,"idx":5,"roleId":75,"leftRight":1,"NpcWords":"Oh......"},{"id":206011,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"3rd Hokage's death led to unprecedentedly depressed defense and combat power in the village. It needs a new Hokage to lead everyone to overcome difficulties."},{"id":206012,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Lord Jiraiya, now the village is very weak. As one of Great Three Ninjas, only you can act as New Hokage."},{"id":206012,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"Compared to a sluggish guy like me, perhaps Tsunade Princess, who is also among Great Three Ninjas, capable of treating diseases and likes gambling is more suitable for it. "},{"id":206012,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"I'll go find her, but I must bring Naruto with me because some secret guys have tailed him. I have to take care."},{"id":206012,"idx":4,"url":"shanchengqingye","name":"shanchengqingye1","leftRight":1,"NpcWords":"Is that little guy Nine Tails Jinchuriki? Hah, a good opportunity. We'll take power of Tailed Beast!"},{"id":206013,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Hey, you pretended to be a Ninja from Hidden Leaf to capture Naruto. I'll never let you get him."},{"id":206013,"idx":2,"url":"shanchengqingye","name":"shanchengqingye1","leftRight":1,"NpcWords":"...Jiraiya is protecting this little guy as one of Great Three Ninjas. It's hard to achieve our goal. Just retreat first\u2026"},{"id":206021,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Hello, Pervy Sage, where do you want to bring me to? Teach me New Techniques quickly."},{"id":206022,"idx":1,"roleId":71,"leftRight":1,"NpcWords":"Itachi, that little guy with Nine Tails was found. Maybe it will be more convenient if I use my Samehada to chop his hands and feet."},{"id":206022,"idx":2,"roleId":82,"leftRight":1,"NpcWords":"Don't get involved in extra work. Our task is only to bring him back to Akatsuki. Moreover, Jiraiya isn't so easy to deal with."},{"id":206031,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Beauty, a beauty is waving towards me. What a rare opportunity! Go away, Naruto. It's time for adults now."},{"id":206032,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Want to use a honey-trap to lure me? Hum, though my nose bled\u2026Why did your organization want to get Nine Tails inside Naruto?"},{"id":206032,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"I won't give Naruto to you. Since you're Class-S Wanted, I'll take this opportunity to handle you."},{"id":206033,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"Retreat for now. Jiraiya is worthy of his reputation. I used both Tsukuyomi and Amaterasu\u2026"},{"id":206041,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"That organization already started their operation? Even Itachi disappearing long ago appeared. It seems that we're in a big trouble."},{"id":206042,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Naruto, those guys want to get Nine Tails in your body. I'll spend all my time in making you strong on our way of looking for Tsunade."},{"id":206042,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Great! Pervy Sage, let's immediately start our trainings. "},{"id":206042,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"This technique is left by 4th Hokage and realized by making Chakra rotate fast. Look!"},{"id":206043,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Well done! We'll implement trainings for stage 3 later. Now let's go and meet Tsunade."},{"id":206051,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"I haven't seen Tsunade Princess who likes gambling so much but always fails for years."},{"id":206052,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Pervy Sage, is that old woman also one of Great Three Ninjas like you? So she should be more than 50 years old."},{"id":206052,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"I heard she hated to see her appearance when she's old, so she used a Ninjutsu to maintain her 20-year old appearance. I once courted her but was rejected."},{"id":206052,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"Ur, there is a beauty with long hair, ample bosom and long legs. I like it. Thus let me pretend to lose my purse and peep at her briefs\u2026"},{"id":206052,"idx":4,"roleId":54,"leftRight":1,"NpcWords":"Who is it? What a lustful, shameless guy! I'll kill you."},{"id":206053,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ah, it's Teacher Yuuhi Kurenai. Why are you here?"},{"id":206053,"idx":2,"roleId":54,"leftRight":0,"NpcWords":"It's Lord Jiraiya and Naruto. I'm looking for you. I just received a message that Manda and Sound Ninja appeared here. I'm afraid that Orochimaru will also be here."},{"id":206053,"idx":3,"roleId":54,"leftRight":0,"NpcWords":"Though I don't know about their intent, you should take care. On the other hand, Lord Jiraiya is so indiscreet."},{"id":206053,"idx":4,"roleId":91,"leftRight":0,"NpcWords":"Sorry, sorry\u2026but you shouldn't hit me so heavily\u2026it really hurts..."},{"id":206053,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Tsunade, long time no see\u2026"},{"id":206061,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Orochimaru\u2026his hands are disabled by a strong seal technique\u2026"},{"id":206062,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Orochimaru, I heard you killed 3rd Hokage Teacher Sarutobi. Why are you looking for me here?"},{"id":206062,"idx":2,"roleId":52,"leftRight":1,"NpcWords":"Lord Tsunade, we want to ask you to cure Lord Orochimaru's hands. "},{"id":206062,"idx":3,"roleId":29,"leftRight":0,"NpcWords":"Are you kidding? You raided the Hidden Leaf and killed Lord Hokage. I'll kill you if you continue staying here."},{"id":206063,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"I'm here to make a trade with you, Tsunade. If you can cure my hands, I'll use my Kinjutsu to revive your younger brother and man. Think about it carefully."},{"id":206071,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"Is that Jiraiya? It's really easy to meet old friends today\u2026"},{"id":206072,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"I finally found you, Tsunade. Did you see Orochimaru? What happened? I'll get straight to the point. Our village asked you to act as 5th Hokage."},{"id":206072,"idx":2,"roleId":90,"leftRight":1,"NpcWords":"Are you kidding? Only an idiot will act as Hokage. I don't want to sacrifice myself so easily. Teacher Sarutobi flaunted his superiority, so he died."},{"id":206072,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"You're laughing at Hokage, my grandpa. I don't care if you're a woman or one of Great Three Ninjas, I'll beat you up."},{"id":206073,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"(Thinking) \u2026What a special little guy! I can't help considering him to be Nawaki...Nawaki, my younger brother..."},{"id":206081,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"I haven't seen Lord Tsunade is so hesitant for long. Did she want to make a trade with Orochimaru?"},{"id":206082,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Lord Tsunade, do you really want to make a trade with Orochimaru on the specified date? I'll stop you even if I lose my life."},{"id":206082,"idx":2,"roleId":90,"leftRight":1,"NpcWords":"Shizune, do you know who you're talking to!"},{"id":206083,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Here you come, Tsunade. Tell me your answer. I'll be able to revive your man and younger brother."},{"id":206091,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Orochimaru, I admit that I once hesitated when you offered to revive my younger brother and my man\u2026"},{"id":206092,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Though I really want to see them and I may lose my judgment when thinking about their smiles, that little guy named Naruto\u2026"},{"id":206092,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"He reminded me of their dream. I'll make their dream come true on their behalf. I'll kill you, you scum!"},{"id":206101,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"You can't resist me, Tsunade. I know you're afraid of blood."},{"id":206102,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Are you okay, Lord Tsunade?"},{"id":206102,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Whir, whir, whir\u2026my body, is still trembling\u2026"},{"id":206102,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"Fortunately I came at the right time, Tsunade!...... Orochimaru, let our Great Three Ninjas end it today!"},{"id":206102,"idx":4,"roleId":89,"leftRight":1,"NpcWords":"Jiraiya, you're still meddling everywhere after years."},{"id":206103,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Even if you don't cure me, I'll find other ways. I'll definitely destroy the Hidden Leaf Village in the future. See you!"},{"id":206111,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Hello everyone, I'll act as 5th Hokage from now on. It's time for our village to commence reconstruction."},{"id":206112,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"You finally wake up, Sasuke. Naruto came back with Grandma Tsunade. She became 5th Hokage and cured you\u2026"},{"id":206112,"idx":2,"roleId":27,"leftRight":1,"NpcWords":"\u2026everyone may mention Naruto, Naruto \u2026 Naruto, how have you grown\u2026now let's have a fight!"},{"id":206113,"idx":1,"roleId":27,"leftRight":1,"NpcWords":"Shit! How can you be so strong, Naruto\u2026 now I can't kill that man - Itachi at all."},{"id":206121,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Sasuke \u2026 what's wrong with you? You aren't what you used to be..."},{"id":206122,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Sasuke, you're thinking too much about retaliating upon Itachi. You'll obsess about it. Pure revenge will lead to a tragic ending."},{"id":206122,"idx":2,"roleId":27,"leftRight":0,"NpcWords":"What are you talking, Itachi? My elder brother killed my parents and the entire Uchiha Clan. Thus I survived and am obliged to revenge them."},{"id":206122,"idx":3,"roleId":45,"leftRight":1,"NpcWords":"Ur, a good stare. Sasuke with anger in eyes can be taken back. Let me see why Orochimaru valued you."},{"id":206123,"idx":1,"roleId":45,"leftRight":1,"NpcWords":"How can you be so complacent in such a small fight? You're too weak. To get strong, go with us and Lord Orochimaru will give you power."},{"id":206131,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Ur, it's so late. Why did Sasuke leave village? His wound hasn't yet recovered\u2026"},{"id":206131,"idx":2,"roleId":27,"leftRight":1,"NpcWords":"Sakura, don't follow me\u2026thank you, bye\u2026"},{"id":206132,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"A message received shows that Sasuke has left the village for Orochimaru. Shikamaru, immediately form a team and go get back Sasuke!"},{"id":206132,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"It's troublesome, but Sasuke is one of us. I'll go and get him back\u2026the guy ahead has strong strength. Take care!"},{"id":206132,"idx":3,"roleId":46,"leftRight":1,"NpcWords":"A few bugs will be caught\u2026want to send these little guys as victims? You may first leave with Sasuke. I'll handle them."},{"id":206141,"idx":1,"roleId":46,"leftRight":1,"NpcWords":"Ur, you came out of my Earthen Prison unexpectedly. Hum, I'm careless. A stupid team leader will only let their men suffer more."},{"id":206142,"idx":1,"roleId":21,"leftRight":0,"NpcWords":"Go and chase Sasuke, everyone. Let me handle this guy. I'll never allow you to laugh at my best friend!"},{"id":206142,"idx":2,"roleId":46,"leftRight":1,"NpcWords":"Food is food. What can you damned fatso do?"},{"id":206151,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"Watch the ambush here, everyone. Watch those spider silks."},{"id":206152,"idx":1,"roleId":43,"leftRight":1,"NpcWords":"Obviously it's a mistake to let the weakest guy among us stay there. Lord Orochimaru will get angry about such a long delay."},{"id":206152,"idx":2,"roleId":25,"leftRight":0,"NpcWords":"Mix Chakra into spider silks made with a special experience? It seems that only my Soft Fist can deal with this guy. You may first leave."},{"id":206152,"idx":3,"roleId":43,"leftRight":1,"NpcWords":"Stay here alone? I'll let you pay a high price for your arrogance!"},{"id":206161,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"What's wrong with this guy? Why does he have two heads, a clone, reproduction or something else?"},{"id":206162,"idx":1,"url":"zuojinyoujin","name":"zuojinyoujin1","leftRight":1,"NpcWords":"Hah, our brothers coexist. My elder brother can come out of any part of our body to help me\u2026ur, waste, and also a dog."},{"id":206162,"idx":2,"url":"zuojinyoujin","name":"zuojinyoujin2","leftRight":1,"NpcWords":"Sakon, no time to waste. Immediately release your Cursed Seal and enable mode 2 to eliminate him."},{"id":206162,"idx":3,"roleId":22,"leftRight":0,"NpcWords":"Akamaru, come one, it's our turn now!"},{"id":206162,"idx":4,"url":"zuojinyoujin","name":"zuojinyoujin1","leftRight":1,"NpcWords":"No hurry, brother. It's more funny to kill your prey after playing with it sufficiently."},{"id":206171,"idx":1,"roleId":44,"leftRight":1,"NpcWords":"These bugs just don't want to stop and even chase here. What are those three guys doing?"},{"id":206172,"idx":1,"roleId":44,"leftRight":1,"NpcWords":"People from your village are so funny. Do you want to sacrifice the entire team for a single captive? Let me blow Melody of Death for you."},{"id":206172,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"Is this guy using a flute to control these monsters? Though I don't understand its notes, I can judge from his finger movements\u2026"},{"id":206172,"idx":3,"roleId":44,"leftRight":1,"NpcWords":"Hum, this guy seems to be planning something. However, nobody will break my Melody of Death!"},{"id":206173,"idx":1,"roleId":44,"leftRight":1,"NpcWords":"Ki...Kimimaro, why are you here\u2026"},{"id":206181,"idx":1,"roleId":47,"leftRight":1,"NpcWords":"Tayuya, you stupid guys have delayed revival of Lord Orochimaru. I'll kill you after wiping them out."},{"id":206182,"idx":1,"roleId":47,"leftRight":1,"NpcWords":"I'm here to get back Lord Orochimaru's Container. I was born to serve Lord Orochimaru, so I don't care about anything else. "},{"id":206182,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"I'll never give Sasuke to you!"},{"id":206183,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"This guy\u2026so strong. He seems not to fight with us seriously. "},{"id":206191,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"This guy named Kimimaro is really strong. We'll be unable to chase Sasuke if we're stalled by him."},{"id":206192,"idx":1,"roleId":26,"leftRight":0,"NpcWords":"Might Guy from the Hidden Leaf revived! Naruto, go and chase Sasuke. Let me handle this guy playing bones."},{"id":206192,"idx":2,"roleId":40,"leftRight":0,"NpcWords":"Hi, your current body isn't suitable for a fight. Just let me do it because our Hidden Sand Ninja Village have owed you too much."},{"id":206192,"idx":3,"roleId":47,"leftRight":1,"NpcWords":"I'll eliminate anyone who dare stop Lord Orochimaru. I live to help Lord Orochimaru realize his ambitions..."},{"id":206193,"idx":1,"roleId":47,"leftRight":1,"NpcWords":"\u2026I'm not alone. I'll stay in the heart of Lord Orochimaru forever\u2026"},{"id":206201,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"I finally chased you, Sasuke! What on earth are you doing? Immediately go back to Hidden Leaf Village with me!"},{"id":206202,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Wake up quickly, Sasuke. It's Orochimaru who killed Grandpa Hokage and raided the village. How could you go to him?"},{"id":206202,"idx":2,"roleId":27,"leftRight":1,"NpcWords":"Go back. I don't want to be with you any more. I have my own pursuit. I need power. Nobody could stop me."},{"id":206211,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"As a guy without a family, how could you understand my pain of losing my family?"},{"id":206212,"idx":1,"roleId":53,"leftRight":1,"NpcWords":"Naruto, my purpose is to revenge them. Anyone who dare stop me will be killed, including you. "},{"id":206212,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Sasuke, do you really want to kill me? Aren't we friends? Damn it! I'll never allow you to go to Orochimaru even if I break your hands and feet!"},{"id":206213,"idx":1,"roleId":53,"leftRight":1,"NpcWords":"\u2026I'll definitely obtain power on my own...Naruto, bye\u2026"},{"id":206221,"idx":1,"roleId":63,"leftRight":1,"NpcWords":"Whir\u2026whir\u2026whir\u2026"},{"id":206222,"idx":1,"roleId":63,"leftRight":1,"NpcWords":"Whir\u2026ur, someone is coming this way? How can someone bother my sleep even in such a remote place..."},{"id":206222,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Sasuke\u2026why did you leave the Hidden Leaf and go to Orochimaru\u2026"},{"id":206222,"idx":3,"roleId":63,"leftRight":1,"NpcWords":"Ur, this face, it's that little guy. I heard that a little guy named Uchiha betrayed the Hidden Leaf. He seems to be one of this guy's friends."},{"id":206222,"idx":4,"roleId":63,"leftRight":1,"NpcWords":"Cheer up, little guy! To get back your friend from Orochimaru, you have to be very strong. Let me instruct you."},{"id":206231,"idx":1,"roleId":64,"leftRight":1,"NpcWords":"Where did Six Tails go? Shit! He always runs away to sleep each time we carry out a task."},{"id":206232,"idx":1,"roleId":64,"leftRight":1,"NpcWords":"What's that? Six Tails is combating that guy! Enemy? Well, let's end the fight quickly."},{"id":206232,"idx":2,"roleId":63,"leftRight":0,"NpcWords":"Hey, don't disturb us, Seven Tails. You misunderstood him. This little guy isn't \u2026"},{"id":206232,"idx":3,"roleId":64,"leftRight":1,"NpcWords":"Hum, stop talking nonsense. Go to hell! I'll take it seriously even if the enemy is a kid."},{"id":206233,"idx":1,"roleId":64,"leftRight":0,"NpcWords":"What, what, you're helping train this kid\u2026why not tell me early? I thought he was an enemy and misunderstood him..."},{"id":206233,"idx":2,"roleId":63,"leftRight":0,"NpcWords":"You just started to attack him before I could tell you everything. Can't you change your impulsive temper?"},{"id":206233,"idx":3,"roleId":64,"leftRight":0,"NpcWords":"Stop talking and immediately go fulfill our task. I'll tie you up next time you run away."},{"id":206233,"idx":4,"roleId":63,"leftRight":0,"NpcWords":"Okay, okay, I have no choice\u2026bye, kid of Nine Tails!"},{"id":206241,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"This kid Naruto, Sasuke already leaving and it can be serious affected."},{"id":206242,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"Hey, Naruto who sit there and put on a long face. It's not like you."},{"id":206242,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Granny Tsunade...... I can't really do anything for my friend......"},{"id":206242,"idx":3,"roleId":90,"leftRight":1,"NpcWords":"Damn!!! I can't allow it!!! I will cheer you!!! (Heavy blow)"},{"id":206243,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Ah, it's hurt. Granny Tsunade ~ ~ ~"},{"id":206243,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Naruto, you have the power to awaken the hearts of others. So, if you have to give up, who will bring back Sasuke?"},{"id":206243,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Mother......"},{"id":206251,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"That is...... Tsunade and Naruto?"},{"id":206252,"idx":1,"roleId":91,"leftRight":1,"NpcWords":"Naruto, Tsunade said there is nothing wrong, so you can't die now."},{"id":206252,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Jiraiya......"},{"id":206252,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Jiraiya......"},{"id":206252,"idx":4,"roleId":91,"leftRight":1,"NpcWords":"If you think it was because of your lack of strength and let Sasuke off! Come here!"},{"id":206253,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"If your mind is strong enough, then your jutsu power will improve!"},{"id":206253,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"Compared with your jutsu and more important is your heart. Naruto, only you that will be able to bring back your friend!"},{"id":206253,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Yeah, I know. I will bring back Sasuke!!!"},{"id":207011,"idx":1,"roleId":57,"leftRight":0,"NpcWords":"Lord Kazekage Gaara, a message from Jiraiya shows that dangerous organization Akatsuki appeared near Sand Kingdom recently. They seemed to be planning something."},{"id":207012,"idx":1,"roleId":97,"leftRight":0,"NpcWords":"Hidden Sand Village should be put on the alert, deploying Anbu guards at important locations around the village."},{"id":207012,"idx":2,"roleId":6,"leftRight":1,"NpcWords":"Lord Sasori, the village's external defense has been removed by me as ordered by you."},{"id":207012,"idx":3,"roleId":67,"leftRight":1,"NpcWords":"Er, you're a good spy. Just capture the Hidden Sand Village at one time!"},{"id":207012,"idx":4,"roleId":6,"leftRight":1,"NpcWords":"Yes!"},{"id":207021,"idx":1,"roleId":57,"leftRight":0,"NpcWords":"Some unknown Ninjas broke into the Hidden Sand Village. Enable Level 1 alertness!"},{"id":207022,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"Hi, Sasori, just stand by. How is the strength of One Tail Jinchuriki? Let me show my skills. "},{"id":207022,"idx":2,"roleId":67,"leftRight":1,"NpcWords":"Deidara, don't let me wait too long..."},{"id":207023,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"Hah, defensive weakness occurred when they tried to protect the village. One Tail Jinchuriki Gaara was taken back successfully!"},{"id":207031,"idx":1,"roleId":57,"leftRight":0,"NpcWords":"Lord Gaara was trapped by the enemies to protect our village. Chase with me!"},{"id":207032,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"Stop, give Gaara back to us, you guys!"},{"id":207032,"idx":2,"roleId":67,"leftRight":1,"NpcWords":"You may first leave, Deidara. I don't like waiting for others or asking others to wait for me. So, I'll eliminate you quickly."},{"id":207033,"idx":1,"roleId":67,"leftRight":1,"NpcWords":"Your attack won't work to me because I'm Sasori of the Red Sand who used to make these weapon puppets in the Hidden Sand Ninja Village."},{"id":207041,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"An emergency communication from Hidden Sand Village? This\u2026this\u2026something serious happened. Immediately go and report to Lord Tsunade!"},{"id":207042,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"It's bad, Lord 5th Hokage! We just received an emergency communication from Hidden Sand Village that Kazekage Gaara was taken by the Akatsuki organization."},{"id":207042,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Kakashi, Naruto and Sakura, immediately go to the Hidden Sand Ninja Village, investigate what happened and then support them!"},{"id":207042,"idx":3,"roleId":6,"leftRight":1,"NpcWords":"Those guys from the Hidden Leaf are meddling in our affairs? Lord Sasori ordered to stop anyone from entering the Sand. Well, I'll eliminate you right here."},{"id":207051,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"We finally arrived at Sand Kingdom. The village seems to be severely destroyed. Our enemies must be tough. "},{"id":207052,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"We're ordered by Lord Tsunade to support Sand Kingdom\u2026"},{"id":207052,"idx":2,"roleId":58,"leftRight":1,"NpcWords":"You damned Hidden Leaf Fang. Look at my move, pay your life for my son!"},{"id":207053,"idx":1,"roleId":58,"leftRight":1,"NpcWords":"Ur, this guy is called Kakashi? Not Hidden Leaf Fang? They have a similar appearance\u2026Does my eyesight fail due to my age?"},{"id":207053,"idx":2,"roleId":58,"leftRight":0,"NpcWords":"It's said that Sasori of the Red Sand appeared, right? I can't sit and watch it any more. I'll also beat my grandson who fell into a wrong path."},{"id":207061,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Kazekage was already captured. We have yet to understand their real purpose and must investigate about it in many aspects."},{"id":207062,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Immediately send 2nd batch of reinforcement. Go and support the Sand Kingdom, Guy, Lee, Neji and Tenten!"},{"id":207062,"idx":2,"roleId":79,"leftRight":1,"NpcWords":"Some enemies are approaching here. Never allow them to disturb the extraction of Tailed Beast."},{"id":207062,"idx":3,"roleId":71,"leftRight":1,"NpcWords":"Let me do it. I have personal feelings against them, haha\u2026"},{"id":207063,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Is this a clone? What Strange Technique did they use?"},{"id":207071,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Lord Tsunade sent a message that he already knew about their rough location. Let's go and chase them now. Please go with us, Granny Chiyo."},{"id":207072,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"It's always you who meet something bad, Gaara. But you can rest assured that I'll take you back this time. "},{"id":207072,"idx":2,"url":"you","name":"you2","leftRight":1,"NpcWords":"Naruto, I'm here to receive your Power of the Nine Tails\u2026"},{"id":207073,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Ur, a clone? No, it should be an advanced technique. Inject Chakra into a human sacrifice to control his actions?"},{"id":207081,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Seen from Chakra, Gaara should be inside this huge rock. However, on the rock is Seal Barrier 5 Times."},{"id":207082,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"To break Seal Barrier 5 Times, you must find seals in other four places. Unsealing them simultaneously can open it. "},{"id":207082,"idx":2,"roleId":84,"leftRight":0,"NpcWords":"Is Gaara in this huge rock...Kakashi, your team should stay here. We'll go and unseal it."},{"id":207082,"idx":3,"roleId":44,"leftRight":1,"NpcWords":"Hum, how can we allow you easily approach the barrier? You'll die here!"},{"id":207083,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"It's bad. These dangerous guys have set a trap!"},{"id":207091,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Once we break the seal, it will trigger the clone technique to clone us, what a dangerous plan..."},{"id":207092,"idx":1,"url":"tiantian","name":"tiantian1","leftRight":1,"NpcWords":"\u2026"},{"id":207092,"idx":2,"roleId":20,"leftRight":0,"NpcWords":"Ur? It really looks like me. This Strange Technique is triggered by unsealing it. We even have the same moves..."},{"id":207101,"idx":1,"roleId":26,"leftRight":0,"NpcWords":"Ah, this clone technique was triggered as we uncovered the seal here. Teacher Guy, a young man should defeat himself, right?"},{"id":207102,"idx":1,"roleId":26,"leftRight":0,"NpcWords":"Ur? Dashing heavy eyebrow and energetic tights, a real clone for me!"},{"id":207102,"idx":2,"url":"xiaoli","name":"xiaoli1","leftRight":1,"NpcWords":"\u2026(The clone can say nothing internally)"},{"id":207111,"idx":1,"roleId":25,"leftRight":0,"NpcWords":"Can this clone copy Chakra and moves?"},{"id":207112,"idx":1,"url":"ningci","name":"ningci2","leftRight":1,"NpcWords":"\u2026"},{"id":207112,"idx":2,"roleId":25,"leftRight":0,"NpcWords":"The same appearance, power and even techniques. It's hard to deal with it. "},{"id":207121,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Hum, a clone product will never resist youthful vigor!"},{"id":207122,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Hum, how can a Counterfeit match the original one? If you hit me, I'll do 10,000 push-ups!"},{"id":207122,"idx":2,"url":"kai","name":"kai1","leftRight":1,"NpcWords":"\u2026(The clone is in a sweat)"},{"id":207131,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Well done, Guy! The seal was removed successfully!"},{"id":207132,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"The seal was removed. Naruto, break the rock and go into it. Watch the trap, everyone."},{"id":207133,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"It's Gaara who lay there\u2026is it sill too late\u2026"},{"id":207133,"idx":2,"roleId":68,"leftRight":1,"NpcWords":"You're too slow and have kept me waiting for too long. I've extract power of this Jinchuriki. Which one of you will become my next Nine Tails Jinchuriki?"},{"id":207141,"idx":1,"roleId":58,"leftRight":0,"NpcWords":"It's you as expected, Sasori of the Red Sand. My grandson became a Traitor\u2026"},{"id":207142,"idx":1,"roleId":67,"leftRight":1,"NpcWords":"Hello, don't meddle in my affairs. You're an old woman living in seclusion. Do you also want to die? I'll turn you two into my collection!"},{"id":207142,"idx":2,"roleId":58,"leftRight":0,"NpcWords":"You're a puppet. Are you 3rd Kazekage? Did you kill him? I didn't expect my grandson would betray the village\u2026"},{"id":207142,"idx":3,"roleId":18,"leftRight":0,"NpcWords":"Granny Chiyo, please use me as a puppet. This guy was of the same organization as Orochimaru. I'll let him tell everything."},{"id":207143,"idx":1,"roleId":67,"leftRight":1,"NpcWords":"As you beat me down, I'll tell you a message in return: go to the Heaven and Earth Bridge of Grass Ninja Village 10 days later, you may see a spy that i assigned close to Orochimaru."},{"id":207151,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"I'll beat you. Give Gaara back to me!"},{"id":207152,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"Hah, the first one getting angry and shouting must be that little guy with Nine Tails. What they said is correct!"},{"id":207152,"idx":2,"roleId":68,"leftRight":1,"NpcWords":"Hah, that One Tail Jinchuriki is incurable. Kid, let me show you Art is Explosion!"},{"id":207153,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Ur? Did the enemy flee with a replacement clay? However, Gaara\u2026"},{"id":207153,"idx":2,"roleId":58,"leftRight":0,"NpcWords":"Whir, I'll transfer my life energy to and revive Gaara. Our older generation have made too many mistakes in mutual killing."},{"id":207161,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Did Sasori say he would meet his spy at the Heaven and Earth Bridge before dying? Perhaps it's a trap\u2026"},{"id":207162,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"I'm not sure if information on the Heaven and Earth Bridge is reliable. Perhaps it's a trap. However, I still need to assign a team to go and investigate it."},{"id":207162,"idx":2,"roleId":76,"leftRight":1,"NpcWords":"To prevent Nine Tails from being caught by the enemy, I must assign members of Anbu Root into Kakashi team. He should have visited Naruto."},{"id":207162,"idx":3,"roleId":48,"leftRight":1,"NpcWords":"Naruto Uzumaki, Nine Tails Jinchuriki who looks like an idiot with very weak strength\u2026"},{"id":207163,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Who are you? You even raided others by contemptible means. Hello, stop\uff01"},{"id":207163,"idx":2,"roleId":48,"leftRight":1,"NpcWords":"Hum, so weak, bye-bye, idiot, we'll meet each other soon."},{"id":207171,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"Being Root of the Hidden Leaf, we must protect Nine Tails from being caught by the enemies. Sai, you must succeed."},{"id":207172,"idx":1,"roleId":16,"leftRight":1,"NpcWords":"Hum, so absent-minded, Sai? It seems that you've forgotten rules as a member of Root. Let me remind you of it."},{"id":207172,"idx":2,"roleId":15,"leftRight":1,"NpcWords":"For the Root, there are only tasks. Once you fail, you'll have to die to keep secrets. You had better remember it."},{"id":207173,"idx":1,"roleId":16,"leftRight":1,"NpcWords":"Here is something Lord Danzo gave you, take it. Never forget your secret task. Bear in mind that there are only tasks instead of feelings for the Root."},{"id":207173,"idx":2,"roleId":48,"leftRight":1,"NpcWords":"Yes\u2026"},{"id":207181,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Ur? Lord Hokage asked me to take care of members of Kakashi team? Yes\u2026I'll be careful about Sai."},{"id":207182,"idx":1,"roleId":56,"leftRight":1,"NpcWords":"I'm Danzo. Lord Tsunade assigned me to take over Kakashi and act as your interim team leader. Introduce yourselves to each other."},{"id":207182,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Ur? Why this guy? He once raided me. I hate him. Sasuke is much better than him."},{"id":207182,"idx":3,"roleId":48,"leftRight":1,"NpcWords":"Please don't compare me with that guy who turned against the village and sought power from Orochimaru because he's too weak."},{"id":207182,"idx":4,"roleId":18,"leftRight":0,"NpcWords":"How dare you speak ill of Sasuke?"},{"id":207182,"idx":5,"roleId":56,"leftRight":1,"NpcWords":"Stop! Those who dare quarrel will be thrown into the cage!"},{"id":207191,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"You must cooperate with each other when carrying out a task no matter how you dislike each other. No personal feelings should be blended."},{"id":207192,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"It's the time. The best way is to disguise myself as Sasori and meet that spy for information. You should just hide here."},{"id":207192,"idx":2,"roleId":52,"leftRight":1,"NpcWords":"Hi, Lord Sasori, long time no see. I secretly came here. Let's get straight to the point."},{"id":207192,"idx":3,"url":"xie","name":"xie2","leftRight":0,"NpcWords":"Give me your information on your base and Sasuke Uchiha."},{"id":207192,"idx":4,"roleId":52,"leftRight":1,"NpcWords":"Information? Hah, you're trapped. Actually I pretended to be controlled by you and then became your spy. I'm loyal to Lord Orochimaru only."},{"id":207193,"idx":1,"roleId":52,"leftRight":1,"NpcWords":"Hah, you can't move now because I poisoned you. Today you'll die here."},{"id":207193,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Well done, Kabuto \u2026"},{"id":207201,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"It's bad. We're set up. Orochimaru is also here. Take care!"},{"id":207202,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"I originally wanted to kill Sasori here, but he is already dead. Come out, little mice from the Hidden Leaf. I'll play with you here for a while."},{"id":207202,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Orochimaru!"},{"id":207203,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"This kid is so funny and has aroused power of Nine Tails with 3 Chakra tails growing out of his body\u2026"},{"id":207211,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"It's bad. Power of Nine Tails will be out of control soon and must be restrained with Wood Release Ninjutsu immediately!"},{"id":207212,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Hah, still not enough. Let me see your capabilities. I'm wondering which one is stronger between you and current Sasuke."},{"id":207212,"idx":2,"roleId":56,"leftRight":0,"NpcWords":"It's bad. The 4th tail grows. As Lord Jiraiya said, Naruto is completely out of control."},{"id":207213,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Whir, it's finally controlled. Power of Nine Tails is awesome\u2026Where is Sai?"},{"id":207213,"idx":2,"roleId":48,"leftRight":1,"NpcWords":"Orochimaru, here is something Lord Danzo gave you. Let's make a deal..."},{"id":207221,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Sai has gone. What order did he receive from Danzo? It makes you upset."},{"id":207222,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"We finally found Orochimaru's base with Sai inside it. We should sneak into it silently. Never alert them."},{"id":207222,"idx":2,"roleId":48,"leftRight":1,"NpcWords":"Being discovered by you means that my task has failed\u2026why are you so persistent about Sasuke, Naruto and Sakura?"},{"id":207222,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Because Sasuke is just like my brother. He is who I really care."},{"id":207223,"idx":1,"roleId":48,"leftRight":0,"NpcWords":"\u2026brother, who you really care\u2026"},{"id":207231,"idx":1,"roleId":48,"leftRight":0,"NpcWords":"I finally found you, Sasuke."},{"id":207232,"idx":1,"roleId":53,"leftRight":1,"NpcWords":"Who is it?"},{"id":207232,"idx":2,"roleId":48,"leftRight":0,"NpcWords":"Sasuke, ordered by Lord Danzo, my original secret task was to pretend to work with Orochimaru and take an opportunity to assassinate you, but..."},{"id":207232,"idx":3,"roleId":48,"leftRight":0,"NpcWords":"But when I met Naruto, I couldn't help disobeying the order to protect who he cares about. So I'll bring you back to the village."},{"id":207233,"idx":1,"roleId":53,"leftRight":1,"NpcWords":"To kill Itachi, I can give my body to Orochimaru. So please go away and don't try in vain."},{"id":207233,"idx":2,"roleId":48,"leftRight":0,"NpcWords":"Sorry, Naruto, I failed to get Sasuke back because he's already filled with revenge anger\u2026"},{"id":207241,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Sasuke \u2026"},{"id":207242,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Oh, oh, shit! Isn't that the kid with Nine Tails ahead? He looks so weak that you want to combat him when seeing him."},{"id":207242,"idx":2,"roleId":7,"leftRight":1,"NpcWords":"What are you doing, Lord Killer Bee? We're here to carry out a task at the Hidden Leaf Village. Hope you won't make troubles any more. "},{"id":207242,"idx":3,"roleId":8,"leftRight":1,"NpcWords":"No, you stunned that kid last time. Do you want to do it once again? Why did you hate him so much?"},{"id":207242,"idx":4,"roleId":77,"leftRight":1,"NpcWords":"Have a try, have a try, yo yo, check it out! See if the kid's strength has changed!"},{"id":207243,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"What an uncle singing rap songs! Who are you?"},{"id":207243,"idx":2,"roleId":77,"leftRight":1,"NpcWords":"Very very good! The kid's strength is improved significantly. I recognized it, yo yo, check it out!"},{"id":207251,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Hey, who are you? Why did you come to the Hidden Leaf?"},{"id":207252,"idx":1,"roleId":8,"leftRight":1,"NpcWords":"Lord Killer Bee, let's go. We still have something important to do, Orochimaru's movement\u2026"},{"id":207252,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Wait, Orochimaru? Tell me any information regarding Orochimaru quickly!"},{"id":207252,"idx":3,"roleId":7,"leftRight":1,"NpcWords":"Hum, why should I tell you as a Genin? It's because of a traitor like Sasuke Uchiha in your village that the situation became complicated..."},{"id":207252,"idx":4,"roleId":17,"leftRight":1,"NpcWords":"Nonsense, Sasuke isn't a Traitor. Take back what you said or I'll never forgive you."},{"id":207253,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Stop, Naruto. What are you doing? Be polite because they are Ninjas delivering information from Hidden Cloud Village."},{"id":207253,"idx":2,"roleId":17,"leftRight":0,"NpcWords":"Whir\u2026whir...Sasuke will definitely come back."},{"id":207253,"idx":3,"roleId":83,"leftRight":0,"NpcWords":"Sorry, this guy may get too excited when it comes to Sasuke. Lord Hokage is waiting for you. Please go this way."},{"id":207261,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"Sai, you still not complete the task......"},{"id":207262,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"Sai, how come you disobey my orders. You can't have feelings......."},{"id":207262,"idx":2,"roleId":2,"leftRight":1,"NpcWords":"Danzo, this guy has been unreliable. Transaction with Orochimaru over there, let me do it."},{"id":207262,"idx":3,"roleId":56,"leftRight":0,"NpcWords":"Kakashi told me to pay attention to Danzo move. That guy......"},{"id":207262,"idx":4,"roleId":2,"leftRight":1,"NpcWords":"Huh? Who? Who's there? Come out!"},{"id":207271,"idx":1,"roleId":2,"leftRight":1,"NpcWords":"Danzo, have a damn rat eavesdropping."},{"id":207272,"idx":1,"roleId":2,"leftRight":1,"NpcWords":"Eavesdropping rat?"},{"id":207272,"idx":2,"roleId":56,"leftRight":0,"NpcWords":"Not good, still cannot be found!"},{"id":207272,"idx":3,"roleId":76,"leftRight":1,"NpcWords":"Ridiculous, thought to be hidden from the old man's eyes!"},{"id":207273,"idx":1,"roleId":2,"leftRight":1,"NpcWords":"Danzo, that guy running really fast. Do you want me to silence it?"},{"id":207273,"idx":2,"roleId":76,"leftRight":1,"NpcWords":"No, look at this jutsu. The power is great and I don't exactly what it is. We also can not easily laid hands on him."},{"id":207273,"idx":3,"roleId":76,"leftRight":1,"NpcWords":"As long as there is no evidence, Konoha High-Level can't take me. My goal is only the Hokage seat!"},{"id":208011,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Senior Kakashi failed to bring back Sasuke, having severe impact on Naruto."},{"id":208012,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"\u2026"},{"id":208012,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Sasuke has become so strong, so I have to become stronger to defeat and bring him back. As a result, just practice with Shadow Clone."},{"id":208021,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Naruto, your Chakra attribute is wind. To control it well, go to learn from Asuma with similar attributes."},{"id":208022,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Asuma, what is the use of wind attribute?"},{"id":208022,"idx":2,"roleId":55,"leftRight":1,"NpcWords":"Wind is an attribute with strongest attack in close and mid-ranged combat. It can become knife-like blades. Look, I'll demonstrate it."},{"id":208031,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Lord Hokage, a message received recently shows that members of the Akatsuki organization are moving towards Fire Kingdom. One of Guard the 12 Ninjas Lord Chiriku was already killed."},{"id":208032,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"The enemies who could kill Chiriku must have strong strength\u2026Immediately send 20 scout teams to thoroughly search for them on the border of Fire Kingdom."},{"id":208032,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Ah, the fishes rose to the bait. Should we first break them up or go and tell predecessors Hidan and Kakuzu?"},{"id":208041,"idx":1,"roleId":55,"leftRight":0,"NpcWords":"Chiriku is my good friend and also one of Guard the 12 Ninjas. I'll definitely revenge you."},{"id":208042,"idx":1,"roleId":65,"leftRight":1,"NpcWords":"Kakuzu, take money and leave quickly. It's dirty and smelly. We're arresting Jinchuriki, but you still want to earn extra income."},{"id":208042,"idx":2,"roleId":66,"leftRight":1,"NpcWords":"Hah, the underground organization offers a reward for the capture of these meddling ninjas from the kingdoms. Guard the 12 Ninjas are worth much."},{"id":208042,"idx":3,"roleId":55,"leftRight":0,"NpcWords":"You killed Chiriku?"},{"id":208043,"idx":1,"roleId":65,"leftRight":1,"NpcWords":"Ah, it really hurts. Hah, don't think you can kill me. You guys are blaspheming the gods."},{"id":208051,"idx":1,"roleId":55,"leftRight":0,"NpcWords":"Are these guys humans? Why are they still alive after being beheaded?"},{"id":208052,"idx":1,"roleId":66,"leftRight":1,"NpcWords":"Hidan, as I told you earlier, your ceremony or prayer is too cumbersome plus your garrulous personality. Let me get rid of him quickly!"},{"id":208053,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Teacher Asuma!"},{"id":208053,"idx":2,"roleId":66,"leftRight":1,"NpcWords":"Damn it! They're supported by reinforcement and fled. That guy named Asuma is also one of Guard the 12 Ninjas. I originally wanted to exchange his corpse for money."},{"id":208061,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Asuma, you once told me you would sacrifice yourself to protect the village. Now I'm also ready!"},{"id":208062,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Our Team 10 will definitely revenge Teacher Asuma. Choji and Ino, are you ready?"},{"id":208062,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Are you kidding? The enemies are so strong that you'll die in vain. "},{"id":208062,"idx":3,"roleId":83,"leftRight":0,"NpcWords":"Let me accompany them. I'll stop them in a crisis if necessary."},{"id":208062,"idx":4,"roleId":65,"leftRight":1,"NpcWords":"Hi, Kakuzu, Tobi said some more guys from the Hidden Leaf came here."},{"id":208062,"idx":5,"roleId":66,"leftRight":1,"NpcWords":"Hum, I hope they will cost much. I don't want to spend time killing persons without a bounty."},{"id":208071,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Kakashi and others are still in danger. To kill strong enemies like Chiriku and Asuma, we have to send our reinforcement quickly."},{"id":208072,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Yamato, do complete Naruto's trainings within 3 days. If he can't complete them within the time limit, I'll assign others to reinforce Team 10."},{"id":208072,"idx":2,"roleId":56,"leftRight":0,"NpcWords":"Yes, Lord Tsunade."},{"id":208073,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"So, so strong. Though only 50% of this technique was completed, Naruto isn't who he used to be."},{"id":208081,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Are those two guys the so-called Akatsuki? They murdered Teacher Asuma. We have insufficient combat ability, so we mustn't act rashly."},{"id":208082,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"It's hard to deal with these two guys working together. Do you have any good idea, Shikamaru?"},{"id":208082,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"Yes, Kakashi and others may deal with this guy with 5 hearts. I'll go and lead that guy with an Undying Shell to the trap."},{"id":208082,"idx":3,"roleId":65,"leftRight":1,"NpcWords":"Where are you going? You're a little mice playing shadow tricks. I'll sacrifice your head to the fiend."},{"id":208083,"idx":1,"roleId":65,"leftRight":1,"NpcWords":"This is Explosive Amulet Binding Array. You just wanted to lead me to this trap. How dare you set me up?"},{"id":208083,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"You're the only one I must kill\u2026Teacher Asuma, you can rest assured that I'll guard your children as you guarded me."},{"id":208091,"idx":1,"roleId":66,"leftRight":1,"NpcWords":"Hidan is too slow. What is he doing? Was he killed by that kid?"},{"id":208092,"idx":1,"roleId":66,"leftRight":1,"NpcWords":"Hum, do you want to defeat us separately? Though it's an informed choice, you still have to die here."},{"id":208093,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Using Chidori broke only two of his 5 hearts. There are still 3 hearts left\u2026But I have insufficient Chakra..."},{"id":208101,"idx":1,"roleId":66,"leftRight":1,"NpcWords":"Clone Ninja Kakashi! Your legend will be ended here. Compensate me for my loss with your heart."},{"id":208102,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Teacher Kakashi, I'm here to support you. Just have a break and look at my training result: Rasenshuriken!"},{"id":208102,"idx":2,"roleId":66,"leftRight":1,"NpcWords":"Oh, that move is dangerous, kid of Nine Tails. Do evade that wind-like Chakra ball."},{"id":208103,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"What an amazing attack! Even Sharingan couldn't see through it. Naruto's Chakra has exceeded me\u2026"},{"id":208111,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Whir, whir, Cursed Seal has been controlled completely\u2026I finally got power. Itachi, I'll immediately go and get rid of you!"},{"id":208112,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Orochimaru, did your trainings generate only hundreds of useless guys? Don't waste my time!"},{"id":208112,"idx":2,"roleId":16,"leftRight":1,"NpcWords":"Useless guys? Never run wild before me, you bastard from Uchiha Clan! You'll be chopped up soon!"},{"id":208113,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"This power is great! I'll obtain your body soon, Sasuke."},{"id":208121,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Orochimaru, you already have nothing to teach me. You're so weak. How can you obtain my body? Are you kidding?"},{"id":208122,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"As you told me before, the weak are useless. So go to hell, the weak guy!"},{"id":208122,"idx":2,"roleId":89,"leftRight":1,"NpcWords":"Don't run wild, Sasuke. I won't die. I have waited for Sharingan for long. It will be mine soon."},{"id":208131,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Orochimaru, is this your power? Your wish won't be realized."},{"id":208132,"idx":1,"roleId":89,"leftRight":1,"NpcWords":"Hah, you're already in my body. Come on, let's start the Reincarnation Skill."},{"id":208132,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"All of your techniques won't work before my Sharingan. You wanted to get my body after failing to get Itachi's, you're mistaken. Go to hell!"},{"id":208133,"idx":1,"roleId":52,"leftRight":1,"NpcWords":"Is Lord Orochimaru got killed\u2026no, his capability was swallowed by Sasuke..."},{"id":208141,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"To find Itachi, I still need some helpers, e.g. Suigetsu, Karin, Jugo \u2026"},{"id":208142,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"Cluck, cluck, thanks for releasing me, Sasuke. So you've killed Orochimaru, right?"},{"id":208142,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"Follow me. I need a helper!"},{"id":208142,"idx":3,"roleId":49,"leftRight":1,"NpcWords":"Hah, so complacent! However, let's first clarify our relationship. Never think you can lord it over me."},{"id":208143,"idx":1,"roleId":49,"leftRight":1,"NpcWords":"I'm just kidding. I recognize you are strong, so I'll follow you. Who else do you want to include?"},{"id":208151,"idx":1,"roleId":49,"leftRight":0,"NpcWords":"Hi, Sasuke, can you exclude Karin? I dislike her though her heal capability is good\u2026"},{"id":208152,"idx":1,"roleId":50,"leftRight":1,"NpcWords":"So that rumor is true. Orochimaru was beaten down by you?"},{"id":208152,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"Follow me, Karin, I need your capability."},{"id":208152,"idx":3,"roleId":50,"leftRight":1,"NpcWords":"Ah? You need my capability? Why should I follow you because I'm one of Orochimaru's subordinates? Come and beat me. "},{"id":208153,"idx":1,"roleId":50,"leftRight":1,"NpcWords":"Ah, the more heavily you beat me, the more I'll love you. I'll follow you if you need me instead of my capability."},{"id":208161,"idx":1,"roleId":50,"leftRight":0,"NpcWords":"Suigetsu is hindering us from staying together, right, Sasuke? \u2026Ur, what? You want to go to that terrible northern base?"},{"id":208162,"idx":1,"roleId":50,"leftRight":0,"NpcWords":"Northern Base accepts some monsters that can't control their killing desire. Are you sure of it?"},{"id":208162,"idx":2,"roleId":49,"leftRight":0,"NpcWords":"Yes, because Sasuke wants to include Jugo. It's said that Orochimaru used his body fluid to develop that technique named Cursed Seal."},{"id":208162,"idx":3,"roleId":53,"leftRight":0,"NpcWords":"Hum, did these guys rise up at Orochimaru's death? Try to find Jugo quickly, Karin and Suigetsu."},{"id":208162,"idx":4,"roleId":3,"leftRight":1,"NpcWords":"Hello, are you newcomers here? Come one and play with us."},{"id":208171,"idx":1,"roleId":51,"leftRight":1,"NpcWords":"\u2026is Orochimaru dead? Should I come out? No, it's so funny to stay here and kill anyone, cluck, cluck."},{"id":208172,"idx":1,"roleId":51,"leftRight":1,"NpcWords":"Next, if a man opens the door and comes in. I'll kill him, cluck, cluck."},{"id":208172,"idx":2,"roleId":51,"leftRight":1,"NpcWords":"Cluck, cluck, great, it's a man. I won a bet, so I can kill him without mercy."},{"id":208173,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"I'm not here to combat you. Let's talk, I'm Sasuke Uchiha."},{"id":208173,"idx":2,"roleId":51,"leftRight":0,"NpcWords":"Sasuke? Are you that guy Kimimaro would sacrifice himself to get back? Well, I'll follow you."},{"id":208181,"idx":1,"roleId":50,"leftRight":0,"NpcWords":"Sasuke, why did you form this Team \"Snake\"?"},{"id":208181,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"My only purpose is to kill Itachi Uchiha and those who dare stop us, including Akatsuki."},{"id":208182,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"Both Nine Tails and Sasuke are to be killed, but which one should come first? Well, I made a decision to first kill that damned Sharingan! Let's go, Tobi!"},{"id":208182,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Ah, are you Sasuke Uchiha? You really look like Itachi!"},{"id":208183,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Ah, rush to hack me with such ferocious expressions before I finish talking. Please handle this, predecessor Deidara."},{"id":208191,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Are these two guys the so-called Akatsuki..."},{"id":208192,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"So you're the so-called Akatsuki. Tell me all information on Itachi now!"},{"id":208192,"idx":2,"roleId":68,"leftRight":1,"NpcWords":"I couldn't believe this kid killed Orochimaru. Hah, he is just an arrogant bastard with a good bloodline."},{"id":208193,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"You little bastard, my C2 clay bomb failed to kill him and I was also in a difficult situation\u2026unforgivable\u2026"},{"id":208201,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Now, tell me where Itachi is!!!"},{"id":208202,"idx":1,"roleId":68,"leftRight":1,"NpcWords":"His eyes make me remember Itachi and that Dojutsu making me suffer from failures. Shit! Only my technique is the strongest and most artistic existence!"},{"id":208202,"idx":2,"roleId":68,"leftRight":1,"NpcWords":"Hum, I'll use my strongest C4 technique to get rid of you. Only my explosion is the ultimate art!"},{"id":208203,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"Fortunately I ran into the Manda's body and transfer to other space at time of his self-explosion, otherwise I'll die\u2026"},{"id":208211,"idx":1,"roleId":53,"leftRight":0,"NpcWords":"According to information collected by Jugo, we'll investigate Akatsuki's strongholds one by one and find Itachi."},{"id":208212,"idx":1,"roleId":71,"leftRight":1,"NpcWords":"Wait, only Sasuke is allowed to pass here as ordered by Itachi. He's waiting for you at Uchiha's meeting house."},{"id":208212,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"I also want to fight a duel with him. Wait here and don't disturb my revenge."},{"id":208212,"idx":3,"roleId":49,"leftRight":0,"NpcWords":"Predecessor Kisame, can't you remember me? I'm younger brother of Hozuki Mangetsu. I like your blade, so can you give me?"},{"id":208212,"idx":4,"roleId":71,"leftRight":1,"NpcWords":"Hah, my memory happens not to be good. My blade also likes you. It tells me it really wants to absorb your Chakra."},{"id":208221,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"Is it Sasuke\u2026"},{"id":208222,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"Sasuke, you finally came. However, your normal Sharingan can't defeat my Mangekyo Sharingan."},{"id":208222,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"Itachi, the reason why I still live is to kill you. You once killed all my clan, leaving me alone thus you'll have to die for your crime!"},{"id":208223,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"Watching the fight secretly is correct. Itachi is stronger than him. But something seems to be wrong with him."},{"id":208231,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"You became strong. But can you escape my Illusion Skill? Uchiha Clan's Sharingan is always the root cause for sibling rivalry."},{"id":208232,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"Keke\u2026"},{"id":208232,"idx":2,"roleId":53,"leftRight":0,"NpcWords":"Hum, your body seems to carry a huge load due to use of those techniques. I'll end all this now, Itachi."},{"id":208233,"idx":1,"roleId":82,"leftRight":1,"NpcWords":"Sasuke, forgive me, it's the last time\u2026"},{"id":208233,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"\u2026"},{"id":208233,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Sasuke won, but Itachi looked strange which was caused by previous disease instead of any technique."},{"id":208241,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Er, get prepared to take back Sasuke..."},{"id":208242,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Who\u2026who are you? Why did you bring me here?"},{"id":208242,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"I was once a helper when Itachi killed Uchiha Clan. Let me tell you the truth of protecting your elder brother at all costs."},{"id":208242,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"Protection? I was almost killed by him a few times. What are you talking? Shut up!"},{"id":208243,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Kid, Itachi gave all his Dojutsu power to you. His combating you is also to let you get Mangekyo Sharingan. In fact, he was seriously ill earlier."},{"id":208243,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Killing the entire clan was a secret task he received from senior management of the Hidden Leaf. He had to kill betraying clansmen for the village's peace."},{"id":208243,"idx":3,"roleId":81,"leftRight":1,"NpcWords":"But he couldn't kill you. He shouldered all crimes to enable senior management of the Hidden Leaf to protect you."},{"id":208243,"idx":4,"roleId":105,"leftRight":0,"NpcWords":"...Itachi, what pains did you experience? All this was caused by the Hidden Leaf. I'll definitely destroy it."},{"id":208251,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"According to information collected, Akatsuki's leader should stay in Amekagure, an isolated village in ongoing civil war."},{"id":208252,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"I really miss it. Our Great Three Ninjas once combated Hanzo of the Salamander there. So many years have passed\u2026I want to go and investigate it."},{"id":208252,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"It's dangerous. You can't resist Akatsuki on your own. Do run away in emergency. Do come back alive, Jiraiya."},{"id":208252,"idx":3,"roleId":91,"leftRight":0,"NpcWords":"Some great changes seem to have taken place in Amekagure. It has a strong sense of pressure\u2026"},{"id":208252,"idx":4,"roleId":4,"leftRight":1,"NpcWords":"Hello, who is it? How dare you break into Lord Pain's territory?"},{"id":208253,"idx":1,"roleId":4,"leftRight":1,"NpcWords":"Our leader Lord Pain is a godlike existence. He once ended Amekagure's civil war on his own. I'm just an underling and can't tell you more information."},{"id":208261,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Ended the civil war on his own? Hanzo of the Salamander in Amekagure was defeated by Pain? Akatsuki's leader is really awesome\u2026"},{"id":208262,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"It seems that I've slipped into it too easily\u2026"},{"id":208262,"idx":2,"roleId":70,"leftRight":1,"NpcWords":"It's Teacher Jiraiya. I really miss him. Let me go and meet him."},{"id":208263,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"You are\u2026Konan. So, is your leader Pain Nagato? Yahiko?"},{"id":208271,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"I didn't expect that Akatsuki's dominator would be one of my previous students. What did you experience?"},{"id":208272,"idx":1,"roleId":79,"leftRight":1,"NpcWords":"Long time no see, Teacher Jiraiya. You're still a human after so many years, but I have evolved to a god. "},{"id":208272,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"The Rinnegan, reportedly the strongest Dojutsu owned by Sage of the Six Paths only; It's Nagato, but his appearance has changed greatly. "},{"id":208273,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Why do a few guys summoned all have Rinnegan? Moreover, they have an amazing collaboration. Do they share the vision?"},{"id":208281,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"Followed by 3 persons, 6 persons, 6 Rinnegans; one of them appears to be Yahiko. What's wrong?"},{"id":208282,"idx":1,"roleId":79,"leftRight":1,"NpcWords":"I want to leverage power of Tailed Beast to create the strongest Kinjutsu, ending the war with terrifying power."},{"id":208282,"idx":2,"roleId":91,"leftRight":0,"NpcWords":"I understand it. Yahiko is dead and what's moving now is his corpse. You're the man behind it, right, Nagato?"},{"id":208283,"idx":1,"roleId":91,"leftRight":0,"NpcWords":"I'll send Pain's secret before dying\u2026you'll have to handle the remainders, Naruto, real Child of the Prophecy\u2026"},{"id":208283,"idx":2,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"I'll definitely bring this password to the Hidden Leaf, Jiraiya."},{"id":208291,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Jiraiya is dead\u2026One Tail was taken away\u2026how should we defeat power of Akatsuki\u2026"},{"id":208292,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Lord Tsunade, many people came to the village to mourn Lord Jiraiya\u2026"},{"id":208292,"idx":2,"roleId":59,"leftRight":1,"NpcWords":"Lord Jiraiya, we'll definitely revenge you. Let's go and find Akatsuki, everyone!"},{"id":208292,"idx":3,"roleId":90,"leftRight":0,"NpcWords":"No, calm down please. If you go there now, you will fall into Akatsuki's trap. We must prevent them from capturing more Tailed Beasts!"},{"id":208292,"idx":4,"roleId":60,"leftRight":1,"NpcWords":"Hello, Hokage, are you ordering us? We're not ninjas of the Hidden Leaf, so never want to control our actions!"},{"id":208301,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"What should we do? If it continues like that\u2026Lord Tsunade, are you okay?"},{"id":208302,"idx":1,"roleId":61,"leftRight":1,"NpcWords":"Hum, Hokage, Jiraiya died for the Hidden Leaf. Don't you want to revenge him as leader?"},{"id":208302,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Of course I want, but we can't act rashly and blindly. If we fall into their trap and lose power of Tailed Beast, we'll suffer a great loss."},{"id":208302,"idx":3,"roleId":62,"leftRight":1,"NpcWords":"So you're doubting our strength as Jinchuriki, Hokage? Do you want to experience it?"},{"id":208303,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"What did you consider Jiraiya's death to be? He died because he wanted to eliminate Akatsuki, our common enemy!"},{"id":208303,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"Do you want to act on impulse and let him die in vain? If you lose a Tailed Beast once again because you're eager to revenge him, do you think Jiraiya will be happy?"},{"id":208303,"idx":3,"roleId":97,"leftRight":0,"NpcWords":"What Hokage said is correct. Let's go and calm down for now. Only by finding a good opportunity can we thoroughly eliminate Akatsuki."},{"id":208311,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Jiraiya...... Dead?"},{"id":208312,"idx":1,"roleId":17,"leftRight":0,"NpcWords":"Akatsuki, I would not let them go. I want to revenge!"},{"id":208312,"idx":2,"roleId":83,"leftRight":1,"NpcWords":"Calm down, Naruto. Now, you can't win anyway."},{"id":208312,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Let me go, Kakashi sensei, don't stop me! I'm going to revenge!"},{"id":208312,"idx":4,"roleId":83,"leftRight":1,"NpcWords":"No, i won't let you die in vain!"},{"id":208321,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Naruto, he is blind by hatred. His body chakras dramatically changes."},{"id":208322,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"Naruto!"},{"id":208322,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Tsunade, Naruto has been blinded by hatred. His Nine Tailed chakra is leaking!"},{"id":208322,"idx":3,"roleId":90,"leftRight":1,"NpcWords":"Naruto! Calm down! Do you want Jiraiya die in vain!"},{"id":208323,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Naruto, as you already now. Jiraiya trusting the future to you."},{"id":208323,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"So, now you have to repressed anger. If you fall into this trap, Jiraiya will be......"},{"id":208323,"idx":3,"roleId":17,"leftRight":0,"NpcWords":"Oh oh......Jiraiya......"},{"id":209011,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Naruto, I guess you may have known about Jiraiya\u2026He has commissioned you to handle the future affairs..."},{"id":209012,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"I always hope that Pervy Sage can watch me until I become Hokage. Shit! I'll definitely revenge him."},{"id":209012,"idx":2,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"It's impossible for you to defeat Pain now. I'm Jiraiya's master. As he asked me to take care of you, follow me to receive trainings in Mystic Wood Peak."},{"id":209012,"idx":3,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"Naruto, you have massive Chakra, so you can realize pair exercises of Shadow Clone. As a result, training results of each clone will go back to your body."},{"id":209012,"idx":4,"roleId":17,"leftRight":1,"NpcWords":"It's great. So 100 clones will be 100 times as efficient as my own body. Time to start, Grandpa Toad!"},{"id":209021,"idx":1,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"What I want to teach you now is a sage jutsu instead of Ninjutsu. It uses natural power. Take care or you'll become a toad."},{"id":209022,"idx":1,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"This kid has made a rapid progress and can absorb natural power now. Sage Mode is also about to form."},{"id":209022,"idx":2,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"Next, use the sage jutsu to visualize Jiraiya's residue Chakra to test Naruto's training results."},{"id":209022,"idx":3,"url":"zilaiye","name":"zilaiye1","leftRight":1,"NpcWords":"Naruto \u2026"},{"id":209022,"idx":4,"roleId":80,"leftRight":0,"NpcWords":"Wait for me, Pervy Sage, I'll definitely exceed you. I'll definitely show you the future you commissioned me to realize!"},{"id":209031,"idx":1,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"Jiraiya, Naruto can keep his human form while maintaining the Sage Mode. He has exceeded you."},{"id":209032,"idx":1,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"Next step, also the most important step, enable Sage Mode without building upon power of Toad Oil. Come on, Naruto, do pair exercises of Shadow Clone!"},{"id":209033,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"It's great, Grandpa Toad! I finally succeeded. Wow, this feeling is terrific."},{"id":209033,"idx":2,"url":"shenzuo","name":"shenzuo","leftRight":0,"NpcWords":"Jiraiya, your judgment was correct. Naruto is Child of the Prophecy \u2026"},{"id":209041,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"The extraction of Tailed Beast goes smoothly. Two Tailed Beasts are left\u2026Our Eye of the Moon Plan will be realized soon."},{"id":209042,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Only Eight Tails and Nine Tails have yet to be taken back among Tailed Beasts. Go and take back Eight Tails, Sasuke. Go and attack the Hidden Leaf, Pain and Konan."},{"id":209042,"idx":2,"roleId":70,"leftRight":1,"NpcWords":"Guys in the Hidden Leaf, where is Naruto Uzumaki with Nine Tails?"},{"id":209051,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Is this\u2026what's wrong with the turbulence outside? Did the enemies launch an attack?"},{"id":209052,"idx":1,"roleId":79,"leftRight":1,"NpcWords":"Come on, Six Paths of Pain, attack! The weak barrier of the Hidden Leaf won't work before me!"},{"id":209052,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Oh, these guys are so strong. How could Lord Jiraiya deal with so many guys at that time?"},{"id":209061,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Akatsuki's men are attacking! Get prepared to fight, ninjas of the Hidden Leaf, so does the Medical Team. This is the war to protect the village and Naruto!"},{"id":209062,"idx":1,"roleId":70,"leftRight":1,"NpcWords":"Hum, your techniques won't work before godlike Pain. Hand over Nine Tails now!"},{"id":209062,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"I didn't expect that we would suffer such heavy casualties. Communication Frog, immediately go to Mystic Wood Peak and inform Naruto, asking him to come back and protect the village."},{"id":209063,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"I finally broke away from Tsunade thanks to this turbulence. Move, Root! The era of my acting as Hokage is upcoming."},{"id":209071,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"The Hidden Leaf is right ahead. How can Chakra be so disordered\u2026I hope that everyone will be okay. Wait for me."},{"id":209072,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Is \u2026 is this Hidden Leaf Village? It's destroyed completely. Is that guy Pain?"},{"id":209072,"idx":2,"roleId":79,"leftRight":1,"NpcWords":"Nine Tails\u2026 you finally appeared. Jiraiya once taught me, so we're Senior and Junior under one school."},{"id":209072,"idx":3,"roleId":80,"leftRight":0,"NpcWords":"You're, unforgivable!"},{"id":209081,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Analyzing information collected, Pain is a controlled corpse whose body should be located at a highland near the Hidden Leaf. Go and find him."},{"id":209082,"idx":1,"roleId":79,"leftRight":1,"NpcWords":"The small countries surviving the war of five kingdoms have suffered a lot. Can you tell me how to eliminate hatred as a result of death?"},{"id":209082,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"I don't know, but your thoughts won't welcome a peaceful situation. People can understand each other!"},{"id":209083,"idx":1,"roleId":70,"leftRight":1,"NpcWords":"Nagato, don't pretend to be strong. You've used too much Chakra in the fight of controlling Six Paths of Pain\u2026"},{"id":209083,"idx":2,"roleId":79,"leftRight":1,"NpcWords":"So close\u2026all this will be ended soon\u2026"},{"id":209091,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Share the vision? No wonder these guys can cooperate with each other seamlessly, really strong, whir, whir\u2026"},{"id":209092,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"You will never harm Naruto any more!"},{"id":209092,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"Run, Hinata! It's dangerous. Leave here. You can't resist him."},{"id":209092,"idx":3,"roleId":24,"leftRight":0,"NpcWords":"I could do nothing but cry in the past. It's Naruto's smile that saved me. I want to protect and be with you because I like Naruto most!"},{"id":209092,"idx":4,"roleId":79,"leftRight":1,"NpcWords":"What can you do? I'll let you know that all your efforts are only a prelude to your despair."},{"id":209093,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":1,"NpcWords":"Wow, come on, Naruto. Deepen your anger and break my seal and then I'll lend you a little power\u2026"},{"id":209101,"idx":1,"roleId":79,"leftRight":1,"NpcWords":"Did you hate me because I killed this girl? If that's the case, do you think people can understand each other? That's only Jiraiya's illusion."},{"id":209102,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":1,"NpcWords":"What's wrong? He used my power but could still maintain his self and thoroughly suppress my consciousness and anger, Naruto \u2026"},{"id":209102,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"What a vicious guy!"},{"id":209102,"idx":3,"roleId":79,"leftRight":1,"NpcWords":"This guy released power of Nine Tails with Eight Tails growing due to this girl. The power is really awesome."},{"id":209103,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Pervy Sage once said that the era of mutually understanding each other will finally arrive. As a result, I won't kill you even if I hate you deeply."},{"id":209103,"idx":2,"roleId":79,"leftRight":1,"NpcWords":"You're really an amazing guy. You'll have your own path which is totally different from others. I'll try to trust you. Just use this to compensate you\u2026"},{"id":209103,"idx":3,"roleId":70,"leftRight":1,"NpcWords":"Nagato, you even wanted to sacrifice yourself and used the Reincarnation Skill to revive all people for Naruto."},{"id":209103,"idx":4,"roleId":70,"leftRight":1,"NpcWords":"Naruto, I'll also trust you as Nagato chooses it. I hope you can follow your common dream."},{"id":209111,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"Did you hear it? Lord Tsunade was removed from office when we were busy reconstructing our village. Danzo became New Hokage."},{"id":209112,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Naruto, Danzo just affirmed that Sasuke was a ninja fleeing from the Hidden Leaf and signed an execution order!"},{"id":209112,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"This guy even assigned someone to go and hunt Sasuke. I'll never allow him to do that."},{"id":209112,"idx":3,"roleId":8,"leftRight":1,"NpcWords":"We also want to learn more information about Sasuke. You appear to be his friend. Tell us information about him."},{"id":209121,"idx":1,"roleId":7,"leftRight":1,"NpcWords":"Don't you know it? Now Sasuke is a member of Akatsuki organization. He raided the Hidden Cloud Village and took away Lord Killer Bee with Eight Tails."},{"id":209122,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"I don't believe that Sasuke is a member of Akatsuki organization or something else. I want to meet Danzo and ask him to take back his execution order for Sasuke."},{"id":209122,"idx":2,"roleId":16,"leftRight":1,"NpcWords":"Lord Danzo is busy with affairs in the village and won't meet you. Leave here immediately."},{"id":209131,"idx":1,"roleId":8,"leftRight":1,"NpcWords":"Hidden Leaf Village is destroyed so badly\u2026This is a letter personally written by Lord Raikage. Please pass it to him. Five Kages Talks is to be held soon."},{"id":209132,"idx":1,"roleId":7,"leftRight":1,"NpcWords":"Immediately tell me information about Sasuke. He captured my master. Can you understand me?"},{"id":209132,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"Sorry, Sasuke is my friend and I can't sell him. Just beat me until you calm down and then I'll help you save your master."},{"id":209133,"idx":1,"roleId":8,"leftRight":1,"NpcWords":"This guy is beaten so heavily but still refuses to say information about Sasuke\u2026is he a dependable person\u2026"},{"id":209141,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Sasuke, what happened to you\u2026why did you suddenly go and raid the Hidden Cloud Village\u2026"},{"id":209142,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"I want to talk to Raikage of Hidden Cloud Village and hope they can forgive Sasuke\u2026"},{"id":209142,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"However, you're being monitored by Danzo's men. To go out of the village, you have to first eliminate those tracking guys."},{"id":209142,"idx":3,"roleId":15,"leftRight":1,"NpcWords":"Stop, Lord Danzo gave an order. To avoid being hurt, you had better stay here quietly, Naruto."},{"id":209151,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Let's go, Teacher Kakashi and Teacher Yamato. We must find Raikage prior to the Five Kages Meeting."},{"id":209152,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Long time no see, Naruto. Are you still persistently seeking Sasuke?"},{"id":209152,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Do you want to take this opportunity to seize Nine Tails? Yamato and I won't let you succeed. Are you Madara Uchiha?"},{"id":209153,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"I'm here to tell you some information about Sasuke. He wanted to destroy the Hidden Leaf and revenge his elder brother Itachi."},{"id":209153,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"You are deceiving me, I won't believe you...Sasuke, what happened to you \u2026"},{"id":209161,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Lord Raikage, Sasuke is my friend. Please forgive what he did in the Hidden Cloud Village. Please!"},{"id":209161,"idx":2,"roleId":94,"leftRight":1,"NpcWords":"That guy took away my younger brother. I'll never let it go at that. Moreover, you shouldn't kneel down and beg others as a ninja."},{"id":209162,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"So old, why still want to attend the talks?"},{"id":209162,"idx":2,"roleId":97,"leftRight":0,"NpcWords":"The kingdoms have been suspecting each other and could only fight separately when Tailed Beasts are seized, finally leading to current situation."},{"id":209162,"idx":3,"roleId":92,"leftRight":0,"NpcWords":"Even if Tailed Beasts are seized, does it mean that Zetsu is extremely terrible? Can Akatsuki control Tailed Beasts?"},{"id":209162,"idx":4,"roleId":76,"leftRight":1,"NpcWords":"Perhaps Akatsuki's leader is Madara Uchiha. If that's the case, we should form Allied Ninja Force as soon as possible with the Hidden Leaf having Nine Tails being the commander."},{"id":209162,"idx":5,"roleId":94,"leftRight":1,"NpcWords":"Stop talking nonsense, you guys! Shut up. I can't help getting angry at your words."},{"id":209171,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Why should I believe in other kingdoms? What are the Allied Ninja Force? It's none of my business. Especially that damned kid from Uchiha Clan. I'll definitely teach him a lesson."},{"id":209172,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"Hah, you're still having a meeting. Sasuke has come here. Just find where he is!"},{"id":209172,"idx":2,"roleId":94,"leftRight":1,"NpcWords":"Where is Sasuke? Tell me or I'll kill you immediately."},{"id":209181,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Damned kid from Uchiha Clan, you even dare appear here!"},{"id":209182,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Damned kid, I finally got you. Enjoy furious curses!"},{"id":209182,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"It's Raikage and Jonin of Hidden Cloud Village."},{"id":209182,"idx":3,"roleId":75,"leftRight":1,"NpcWords":"Did this kid capture Lord Killer Bee? Let me handle it, Lord Raikage."},{"id":209191,"idx":1,"roleId":75,"leftRight":1,"NpcWords":"This kid has such strong strength. Is that Mangekyo Sharingan?"},{"id":209192,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Stop running wild, damned little guy!"},{"id":209192,"idx":2,"roleId":51,"leftRight":0,"NpcWords":"Are you okay, Sasuke?"},{"id":209192,"idx":3,"roleId":49,"leftRight":0,"NpcWords":"This guy has an amazing speed and awesome physical strength...Sasuke, we're helping you. Don't look so indifferent."},{"id":209192,"idx":4,"roleId":94,"leftRight":1,"NpcWords":"How dare you harm my younger brother and disregard me as Raikage? Go to hell, damned little guy!"},{"id":209193,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Stop\u2026"},{"id":209201,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Sasuke's expressions are almost freezing...Naruto, you seem not to convey your mood to him\u2026"},{"id":209202,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Living by revenge can't address any problem. I've experienced this point. It's not too late for you."},{"id":209202,"idx":2,"roleId":32,"leftRight":1,"NpcWords":"Gaara, this guy is different from you. He turned to Akatsuki and became a wanted criminal. All people raided won't let it go at that."},{"id":209211,"idx":1,"roleId":32,"leftRight":1,"NpcWords":"What are you doing, Gaara? You hesitate because he's one of Naruto's friends, right? But he's a wanted criminal now."},{"id":209212,"idx":1,"roleId":31,"leftRight":1,"NpcWords":"Let me help you. This guy has been internationally wanted. Gaara, now you're Kazekage and can't consider personal feelings."},{"id":209221,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Sasuke, you are really like me and also walk in the dark. So please pay attention to any light if possible."},{"id":209222,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Please don't have your eyes covered with hatred. There are still friends like Naruto by your side. They trust you and never abandon you."},{"id":209222,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"Hum, I closed my eyes earlier and I just want to exist in the dark."},{"id":209222,"idx":3,"roleId":97,"leftRight":1,"NpcWords":"\u2026I see..."},{"id":209231,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"I must find Danzo as soon as possible. My Chakra can't resist so many opponents here\u2026"},{"id":209232,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Did you find Danzo, Karin? Let's go there."},{"id":209232,"idx":2,"roleId":50,"leftRight":0,"NpcWords":"Yes, I got him\u2026why does Sasuke get increasingly cold? Both Suigetsu and Jugo are seriously injured, don't you care about them, Sasuke \u2026"},{"id":209232,"idx":3,"roleId":92,"leftRight":1,"NpcWords":"Akatsuki, you used 4th Mizukage as a toy and insulted the Hidden Mist. Do you think you can leave so easily, boy?"},{"id":209241,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Get out of the way, irrelevant guys. My target is Danzo!"},{"id":209242,"idx":1,"roleId":73,"leftRight":1,"NpcWords":"You're Akatsuki, so you're the enemy of Hidden Mist. I'll definitely protect our gentle, beautiful Lord Mizukage."},{"id":209242,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"It's bad. Too much Chakra was used in previous fight. Moreover, Susanoo started to have adverse effects on me."},{"id":209251,"idx":1,"roleId":73,"leftRight":1,"NpcWords":"It's bad! I didn't watch it...Ao, immediately get close to Lord Mizukage!"},{"id":209252,"idx":1,"roleId":74,"leftRight":1,"NpcWords":"Do you want to offend Lord Mizukage, kid?"},{"id":209252,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"Hum, your semi-Byakugan was also obtained from Hyuga Clan, right? Let me show you the difference between real Sharingan and your fake Byakugan."},{"id":209261,"idx":1,"roleId":74,"leftRight":1,"NpcWords":"Take care, Lord Mizukage! He is using Mangekyo Sharingan!"},{"id":209262,"idx":1,"roleId":92,"leftRight":1,"NpcWords":"It's a pity to kill such a handsome boy like you, but you're a member of Akatsuki."},{"id":209262,"idx":2,"roleId":50,"leftRight":0,"NpcWords":"Shit! Where did this woman come from? She's already an aunt but still wanted to ogle Sasuke?"},{"id":209271,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"Sasuke, you'll be killed by the Kages if you use Chakra like that. Our leader let me help you recover."},{"id":209272,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"What's so sticky? Is this Zetsu's capability? Chakra is recovering\u2026"},{"id":209272,"idx":2,"roleId":93,"leftRight":1,"NpcWords":"I have no choice but to join the fight. Though we have no animosity against each other, the Ninja World wants you to die, so\u2026"},{"id":209273,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Ah, you can't get rid of Sharingan with such strong capability, otherwise you'll disturb my plan of reviving Ten Tails."},{"id":209273,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Hand over Eight Tails and Nine Tails or wait for the 4th Great Ninja War."},{"id":209281,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Is this space? Did that masked man bring me to his alien space? What's going on outside?"},{"id":209282,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"My Chakra has been restored. Release me from this alien space and I'll go find Danzo."},{"id":209282,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"No hurry, I'll let you go now. I've prepared a small gift for you outside\u2026"},{"id":209282,"idx":3,"roleId":76,"leftRight":1,"NpcWords":"\u2026 Is it Sasuke ..."},{"id":209282,"idx":4,"roleId":105,"leftRight":0,"NpcWords":"I have only one thing to ask you. Senior management of the Hidden Leaf including you once ordered to eliminate our Uchiha Clan. Is it true or not?"},{"id":209291,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"Uchiha Clan is a cursed clan. Your existence will harm the village. So we'll definitely eliminate you at all costs."},{"id":209292,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Danzo has seized so many Sharingans, plus his cells of 1st Hokage transplanted by Orochimaru perhaps his target is also Nine Tails."},{"id":209292,"idx":2,"roleId":76,"leftRight":1,"NpcWords":"You can't kill me. My technique can instantly transform all damage on me into dreamland. I can manipulate Dream and Reality freely."},{"id":209301,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"For the sake of the village? Is that the reason for killing our clan? Itachi also suffered a lot. I'll never forgive you."},{"id":209302,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Despite the large number of Sharingans you have, you can't match our Uchiha Clan at all in its application."},{"id":209302,"idx":2,"roleId":76,"leftRight":1,"NpcWords":"No, I'll never die here. I'll kill you and become Hokage for the Hidden Leaf and the Ninja World!"},{"id":209303,"idx":1,"roleId":76,"leftRight":1,"NpcWords":"Sarutobi, you're the Hidden Leaf bathing in the sun, but I'm dark Root. Finally I failed to become Hokage and overtake you\u2026"},{"id":209311,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Hum, he is the first one. I'll go and eliminate a few old guys among senior management of the Hidden Leaf."},{"id":209312,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"You're worthy of your reputation and even killed Danzo, Sasuke. However, you've used too much Sharingan power. I'm afraid you can't withstand it any more. "},{"id":209312,"idx":2,"roleId":18,"leftRight":1,"NpcWords":"Sasuke, it's me. I want to break away from the Hidden Leaf and join you. I'll do whatever you let me do."},{"id":209312,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"Sakura, do you want to join me or kill me?"},{"id":209312,"idx":4,"roleId":18,"leftRight":1,"NpcWords":"\u2026 spotted...Sasuke, I don't want to see you go further in the dark. Let's end it now!"},{"id":209313,"idx":1,"roleId":18,"leftRight":1,"NpcWords":"Clearly I was determined to kill Sasuke, but I just couldn't do that...Sasuke, why couldn't we go back to previous Team 7\u2026"},{"id":209321,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Sakura, if you dare get in my way. I'll immediately kill you."},{"id":209322,"idx":1,"roleId":83,"leftRight":1,"NpcWords":"Stop, Sasuke. Do you really want to kill Sakura? You really changed and degenerated, right? Hold your hand!"},{"id":209322,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"All your well-being is based on sacrifices of Uchiha Clan. Give back Itachi, my parents, my clansmen and I'll hold my hand."},{"id":209331,"idx":1,"roleId":80,"leftRight":1,"NpcWords":"Stop, Sasuke and Teacher Kakashi!"},{"id":209332,"idx":1,"roleId":80,"leftRight":1,"NpcWords":"Don't attack, Teacher Kakashi. Only I can understand Sasuke's feelings and what he did."},{"id":209332,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"You have neither parents nor brothers. How can you understand my feelings? Shut up! You're just an outsider! I'll ruin the Hidden Leaf!"},{"id":209332,"idx":3,"roleId":80,"leftRight":1,"NpcWords":"I won't allow you to do that. I'll definitely bring you back to the Hidden Leaf."},{"id":209333,"idx":1,"roleId":80,"leftRight":1,"NpcWords":"You should understand that we'll die together if we combat each other. If you have hatred, I'll die with you and your hatred."},{"id":209333,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"What do you want? Why are you so persistent about me?"},{"id":209333,"idx":3,"roleId":80,"leftRight":1,"NpcWords":"Because we're friends! So I'll take you back wherever you are. Wait and see!"},{"id":209341,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Oh, yo, check it out! I've arrived at Hidden Leaf Village again, may I have fun?"},{"id":209342,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Yo, kid, long time no see, check it out! I see your weak face again!"},{"id":209342,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"This strange uncle wearing sunglasses and singing rap songs again! Do you want to suddenly attack me again?"},{"id":209342,"idx":3,"roleId":97,"leftRight":1,"NpcWords":"We're here to discuss the establishment of Allied Ninja Force with Hokage. You look more energetic than before."},{"id":209342,"idx":4,"roleId":80,"leftRight":0,"NpcWords":"Er, I've figured it out. Now that I can't take back Sasuke by waiting. I'll get him back by force and then ask everyone to forgive him!"},{"id":209342,"idx":5,"roleId":64,"leftRight":1,"NpcWords":"Hah, this is your personality. Come on, let me see how your strength is now!"},{"id":209351,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Is this Naruto's current power?"},{"id":209352,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"You're worthy of your reputation and get so strong in a few days, Naruto\u2026However, as Kazekage, I won't be defeated by you."},{"id":209353,"idx":1,"roleId":97,"leftRight":0,"NpcWords":"That's all for today...Naruto, you can rest assured that I'll help you take back Sasuke."},{"id":209353,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"Hah, thank you, Gaara. It's a deal!"},{"id":209361,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Ah, Tsunade, you already wake up?"},{"id":209362,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Tsunade, five nation have decided to set up the Ninja coalition. We will continuing the search for eight tail and nine tail......"},{"id":209362,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"We can't give it now. We will hold up and responsible for what happen in here. We will keep him for practice until this over."},{"id":209362,"idx":3,"roleId":56,"leftRight":1,"NpcWords":"Yes, Tsunade. We will try to hide it from naruto."},{"id":209362,"idx":4,"roleId":80,"leftRight":0,"NpcWords":"Hey, Guy sensei, we really go to the island for practice? "},{"id":209362,"idx":5,"roleId":84,"leftRight":1,"NpcWords":"Of course, we are practice how to defeat the enemy. Naruto, you and me together in this taste of youthful!"},{"id":209363,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"I'm sorry Naruto, had to deceive you. I need you to stay here. Absolutely can not let you fall into the enemy hand."},{"id":209371,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"How is everyone situation?"},{"id":209372,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Hey, Guy sensei, now what happen? I want to go out and have a look."},{"id":209372,"idx":2,"roleId":56,"leftRight":1,"NpcWords":"No, Naruto, Tsunade give command to you practice in here."},{"id":209372,"idx":3,"roleId":56,"leftRight":1,"NpcWords":"Come on, you have better control of tailed beast power. I will be your opponent!!!"},{"id":209373,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"How do you feel? This is strange......"},{"id":209373,"idx":2,"roleId":56,"leftRight":0,"NpcWords":"Well, even if Naruto is dull. Sooner or later he will find out the truth......"},{"id":210011,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Fortunately five kingdoms have decided to establish the Allied Ninja Force. Lord Tsunade has waken up and resumed his duties, but\u2026"},{"id":210012,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"The Kages in five kingdoms decided to hide Eight Tails and Nine Tails to prevent Akatsuki from finding them. Ask Naruto to come here. But we don't know when he will discover this."},{"id":210012,"idx":2,"roleId":80,"leftRight":0,"NpcWords":"Hi, Teacher Yamato, why did you ask me to enter this True Waterfall? Ur? Is this \u2026 me?"},{"id":210012,"idx":3,"url":"xianrenmingren","name":"xianrenmingren1","leftRight":1,"NpcWords":"Those guys in the village once made you so painful, but now pretend to be your good partners. They're real bad people!"},{"id":210012,"idx":4,"roleId":80,"leftRight":0,"NpcWords":"What an irksome guy! Shut up! Never insult my partners no matter who you are."},{"id":210012,"idx":5,"url":"xianrenmingren","name":"xianrenmingren1","leftRight":1,"NpcWords":"Hah, want to have a fight? I'm you, so you can't defeat me. "},{"id":210013,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"I see. True Waterfall can show my internal hatred and wickedness. I've beaten him down, so can I control Nine Tails now?"},{"id":210021,"idx":1,"roleId":80,"leftRight":0,"NpcWords":"Ur, Sasuke appeared in True Waterfall this time, why?"},{"id":210022,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":1,"NpcWords":"Hah, Naruto, I want to arouse your internal hatred. I'll escape sooner or later as long as you have hatred."},{"id":210022,"idx":2,"url":"wanhuatongzuozhu","name":"wanhuatongzuozhu1","leftRight":1,"NpcWords":"Your so-called friendship doesn't exist at all. I don't want to see those guys who have no parents but claim to understand me."},{"id":210022,"idx":3,"roleId":80,"leftRight":0,"NpcWords":"No, the partners in the village trust me and I also trust you. Our friendship won't be written off even if you cover your eyes. I won't get confused any more."},{"id":210022,"idx":4,"url":"wanhuatongzuozhu","name":"wanhuatongzuozhu1","leftRight":1,"NpcWords":"Well, I'll smash your friendship, your eyes and your partners in the village."},{"id":210031,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Mr. Killer Bee, that kid is Naruto, Nine Tails Jinchuriki. He has passed the True Waterfall. Can you please start your trainings?"},{"id":210032,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Well done, kid! Yo, yo, let's commence trainings to control Tailed Beasts from now on, yeah."},{"id":210032,"idx":2,"url":"bawei","name":"bawei","leftRight":1,"NpcWords":"Bee, is this kid Nine Tails Jinchuriki? Is it too early to teach him power of Tailed Beast now?"},{"id":210032,"idx":3,"roleId":80,"leftRight":0,"NpcWords":"Well, yo, uncle Octopus Rap."},{"id":210041,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"The first step is to overthrow hatred. Kid, yo, yo, it's important to separate power of Tailed Beast! You're an idiot! Shit!"},{"id":210042,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"You must hold a tug-of-war with Tailed Beast to obtain its Chakra. Take care or you will lose your self. "},{"id":210042,"idx":2,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Bee, never let Nine Tails get angry. He is also a headache for me."},{"id":210042,"idx":3,"url":"jiuweimingren","name":"jiuweimingren1","leftRight":1,"NpcWords":"Coo, Naruto, want to seize my Chakra? You're too arrogant, kid. On the contrary, I'll absorb your Chakra and take control over your body."},{"id":210043,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Dad and mom, I can control power of Nine Tails thanks to spiritual power left by you inside my body. I'll never let you down."},{"id":210043,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":1,"NpcWords":"Damned Naruto, damned Eight Tails dare help him. Let's wait and see\u2026"},{"id":210043,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"Don't be angry, Nine Tails. Just lend me a little power. Actually I hope that I can also eliminate your hatred one day. "},{"id":210051,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I can feel something that I usually can't in Nine Tails mode. Is this feeling malice?"},{"id":210052,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Uncle Octopus, the saber on your back is filled with malice. My Chakra can feel that something is hidden in it."},{"id":210052,"idx":2,"roleId":71,"leftRight":1,"NpcWords":"Did the task of mixing with Greatsword-Samehada to slip into it fail? I didn't expect that this kid would have such a capability."},{"id":210061,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"Ah, who is this guy looking like a shark or puffer fish? Yo yo, check it out!"},{"id":210062,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Naruto, catch this guy alive. He knows lots of information about Akatsuki. Try to get them."},{"id":210062,"idx":2,"roleId":71,"leftRight":1,"NpcWords":"Want to learn something from me? I'm terrifying Hidden Mist Monster. Don't look down upon me!"},{"id":210063,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"This guy finally summoned a shark to kill him so as not to disclose information to us. So there is also someone in Akatsuki that considers his partners."},{"id":210071,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Come on, Naruto. Trainings of Tailed Beast Evolution are waiting for you. Yo, yo! Now you won't be out of control, idiot!"},{"id":210072,"idx":1,"roleId":77,"leftRight":1,"NpcWords":"Yo, yo, Tailed Beast Ball is to deliver power. Try it, idiot!"},{"id":210073,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Uncle Octopus Rap, Tailed Beast Ball is just like Rasengan. Basically I've mastered its use."},{"id":210073,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Whir, Brother Raikage ordered to try to let Nine Tails stay here. I don't know when Naruto will discover it, shit\u2026"},{"id":210081,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Well done, Kisame! I finally found you, Eight Tails and Nine Tails. Kabuto, you may take actions now\u2026"},{"id":210082,"idx":1,"roleId":94,"leftRight":0,"NpcWords":"As Kisame slipped into it, Akatsuki already knew the location of Eight Tails and Nine Tails. Immediately send someone to go support them and never let them come out."},{"id":210082,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"It's faster to approach them in the sky. Clearly I have the most suitable technique though my old waist often aches..."},{"id":210082,"idx":3,"roleId":78,"leftRight":1,"NpcWords":"Hah, Eight Tails and Nine Tails are on that huge turtle island. Well, use 2nd Manda to force them to come out."},{"id":210091,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"That guy...Yamato, a ninja with Hashirama cells, stays with Nine Tails. I can achieve two objectives simultaneously. "},{"id":210092,"idx":1,"roleId":56,"leftRight":0,"NpcWords":"Is that face Kabuto or Orochimaru? Does this guy work with Akatsuki?"},{"id":210092,"idx":2,"roleId":78,"leftRight":1,"NpcWords":"I've transplanted cells of Lord Orochimaru to my body. Now I've been revived. Hand over your Tailed Beast now."},{"id":210101,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"But you're also my target. You have cells of 1st Hokage Hashirama and is a funny study object, hah."},{"id":210102,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Reinforcement? It doesn't matter. My Corrupt Reincarnation Skill is better than Lord Orochimaru. Come out, Deidara!"},{"id":210102,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"Isn't that Deidara? Clearly he died. Can that skill control the dead?"},{"id":210102,"idx":3,"url":"didala","name":"didala1","leftRight":1,"NpcWords":"It's Onoki. Now you'll have the opportunity to see my stronger explosion art."},{"id":210111,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"They ran away? Also captured that ninja from the Hidden Leaf named Yamato? Is their target him instead of Eight Tails and Nine Tails from the start?"},{"id":210112,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"With cells of 1st Hokage from Yamato, we may further enhance Zetsu's 100,000 reproduction troops. Move!"},{"id":210112,"idx":2,"roleId":78,"leftRight":1,"NpcWords":"Then we can revive those deceased combat power - those famous ninjas. Hah, get prepared to start the war."},{"id":210112,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Power is surging. Is this power of 1st Hokage cells? Cluck, cluck, start to attack! "},{"id":210121,"idx":1,"roleId":94,"leftRight":0,"NpcWords":"The enemies moved. Ninjas of our five kingdoms jointly established the Allied Ninja Force. I act as commander of Command Post and Kazekage Gaara acts as commander of Combat Troops."},{"id":210122,"idx":1,"roleId":97,"leftRight":0,"NpcWords":"Hello, everyone! Now we share the Allied Ninja Force. Please forget about previous hatred and jointly resist our common enemies for this world."},{"id":210122,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"This wonderful speech motivated everyone. Kid Gaara became increasingly imposing as commander of combat troops."},{"id":210122,"idx":3,"roleId":48,"leftRight":0,"NpcWords":"The enemies were found ahead of the Surprise Attack troops. Some scouts from the Hidden Leaf were manipulated by their techniques."},{"id":210122,"idx":4,"url":"bingzuleitong","name":"bingzuleitong1","leftRight":1,"NpcWords":"Oh\u2026please stay away from me, everyone. I'm controlled\u2026"},{"id":210131,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"It's Puppet Technique! I know you're there, Sasori, come out"},{"id":210132,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"I didn't expect that Surprise Attack troops of two parties would meet each other. It seemed that we had the same idea."},{"id":210132,"idx":2,"url":"xie","name":"xie1","leftRight":1,"NpcWords":"I didn't expect that now Akatsuki would depend on power of Corrupt Reincarnation. You really degenerated. "},{"id":210141,"idx":1,"roleId":7,"leftRight":0,"NpcWords":"Ur, Air Raid! The bomb attack is fierce. Take care!"},{"id":210142,"idx":1,"url":"didala","name":"didala1","leftRight":1,"NpcWords":"Don't complain so much, Brother Sasori. Come on, art is to blast away everything."},{"id":210142,"idx":2,"roleId":8,"leftRight":0,"NpcWords":"There is no time to feel sad for deceased partners. Is this the war\u2026."},{"id":210151,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"Granny Chiyo gave her puppet to me. I'll let you see power of Puppeteer soul."},{"id":210152,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"Sasori, you are strong because you injected a puppet into your soul, but you shouldn't become a puppet manipulated without a soul."},{"id":210153,"idx":2,"url":"xie","name":"xie1","leftRight":1,"NpcWords":"Well, let me see what your so-called soul is."},{"id":210153,"idx":1,"url":"xie","name":"xie1","leftRight":1,"NpcWords":"A soul containing its creator? Indeed, that's my desired art...Kankuro, please take care of puppets of my parents."},{"id":210161,"idx":1,"roleId":25,"leftRight":0,"NpcWords":"The enemies increase. Where did they come from? Check it with Byakugan\u2026"},{"id":210162,"idx":1,"roleId":25,"leftRight":0,"NpcWords":"Massive Chakra is moving underground, tremendous amount of Chakra."},{"id":210162,"idx":2,"roleId":7,"leftRight":0,"NpcWords":"The guy that can reproduce and looks like an aloes? Well, force them out!"},{"id":210162,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Quack, what Allied Ninja Force? You'll fall into despair soon. Then you'll collapse and Kill Each Other!"},{"id":210171,"idx":1,"roleId":48,"leftRight":0,"NpcWords":"Why did air get cold? Another foreboding? New enemies?"},{"id":210172,"idx":1,"roleId":48,"leftRight":0,"NpcWords":"Is this\u2026ice and snow? Some more Ninjas with Kekkeigenkai?"},{"id":210172,"idx":2,"url":"bai","name":"bai1","leftRight":1,"NpcWords":"Sorry, I have no old grudge against you. I can't help doing it."},{"id":210181,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Are they Zabuza and Haku?"},{"id":210182,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"It's the present world where you shouldn't arrive. You're souls reincarnated from corpses."},{"id":210182,"idx":2,"url":"zaibuzhan","name":"zaibuzhan1","leftRight":1,"NpcWords":"Long time no see, Kakashi. Where is that highly energetic kid\u2026bad, I start to lose consciousness\u2026"},{"id":210191,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Is, is this\u2026these guys summoned last Hidden Mist Assassination Team."},{"id":210192,"idx":1,"roleId":19,"leftRight":0,"NpcWords":"Shit! It's the strongest among previous Assassination Teams. They've chosen the right team!"},{"id":210193,"idx":2,"roleId":3,"leftRight":1,"NpcWords":"Kill\u2026kill\u2026kill\u2026"},{"id":210201,"idx":1,"roleId":48,"leftRight":0,"NpcWords":"Take care. The guys generated through Corrupt Reincarnation are undead and can only be sealed. Get prepared to move, Seal Team!"},{"id":210202,"idx":1,"roleId":26,"leftRight":0,"NpcWords":"These guys are strong and have killed many of our partners, Teacher Guy."},{"id":210202,"idx":2,"roleId":84,"leftRight":0,"NpcWords":"Calm down, combat means sacrifice. Hurry and confusion may only increase casualties. We must let our partners die meaningfully."},{"id":210202,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Hah, what value? Only corpses piled up. You'll go and accompany them soon."},{"id":210211,"idx":1,"url":"bai","name":"bai1","leftRight":1,"NpcWords":"I once wanted to become Brother Zabuza's tool and protect him at all costs. Now it's impossible for my body to become his tool."},{"id":210212,"idx":1,"url":"bai","name":"bai1","leftRight":1,"NpcWords":"Ah, sorry, kill me quickly as I can't control my body. Kill me worse than a tool!"},{"id":210213,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Zabuza has never considered you as a tool, Haku\u2026"},{"id":210213,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Naruto let Zabuza view his innermost heart before you died. He cried very sadly\u2026"},{"id":210213,"idx":3,"url":"bai","name":"bai1","leftRight":1,"NpcWords":"Great, thank you, Brother Zabuza\u2026"},{"id":210213,"idx":4,"url":"zaibuzhan","name":"zaibuzhan1","leftRight":1,"NpcWords":"Kakashi, you just can't close your mouth\u2026"},{"id":210221,"idx":1,"url":"bai","name":"bai1","leftRight":1,"NpcWords":"I was reincarnated and knew about many things. I'm really content. "},{"id":210222,"idx":1,"url":"zaibuzhan","name":"zaibuzhan1","leftRight":1,"NpcWords":"Kakashi, don't hold your hand and try to stop me\u2026as a man, I'm already dead\u2026"},{"id":210223,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Haku and Zabuza, your death and tear are just Proof of Bond\u2026"},{"id":210231,"idx":1,"roleId":75,"leftRight":0,"NpcWords":"So many enemies! I don't want to fight, but it's an inevitable battle, right?"},{"id":210232,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"It's bad! No. 1 Troops led by Darui will combat hundreds of enemies containing many experts from Corrupt Reincarnation."},{"id":210232,"idx":2,"roleId":75,"leftRight":0,"NpcWords":"Though I'm not motivated, I'll use my Black Lightning to testify why I was assigned to guard Coastal Defense Line."},{"id":210232,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Hum, you're doomed to failure no matter how you struggle. You'll die!"},{"id":210241,"idx":1,"roleId":75,"leftRight":0,"NpcWords":"Are those two guys reincarnated...Kinkaku and Ginkaku?"},{"id":210242,"idx":1,"url":"jinjiao","name":"jinjiao1","leftRight":1,"NpcWords":"I'm pissed off! How could I be summoned by this Ninjutsu developed by 2nd Hokage? Which guy cast this technique, Ginkaku?"},{"id":210242,"idx":2,"url":"yinjiao","name":"yinjiao1","leftRight":1,"NpcWords":"We have no choice and time has passed...Kinkaku, current successors must know little about us, right?"},{"id":210242,"idx":3,"roleId":75,"leftRight":0,"NpcWords":"Sorry to make legendary Gold and Silver Brothers in Hidden Cloud Village go through all this."},{"id":210251,"idx":1,"roleId":94,"leftRight":0,"NpcWords":"Both Gold and Silver Brothers were even summoned. They were extremely evil guys in the history and even set up 2nd Raikage and 2nd Hokage."},{"id":210252,"idx":1,"url":"jinjiao","name":"jinjiao1","leftRight":1,"NpcWords":"It's enough. Now I'll let you experience Ninja Tools of Sage of the Six Paths. Hah, take care because your Kizuna has become a hostage."},{"id":210261,"idx":1,"roleId":75,"leftRight":0,"NpcWords":"Take care, everyone. Don't talk from now on or you'll be absorbed into that gourd."},{"id":210262,"idx":1,"url":"yinjiao","name":"yinjiao1","leftRight":1,"NpcWords":"You little underlings are just substitutes for Ninja Tools. Don't run wild before me!"},{"id":210262,"idx":2,"roleId":75,"leftRight":0,"NpcWords":"I'm not a substitute. I'm Boss Raikage's right hand!"},{"id":210271,"idx":1,"roleId":75,"leftRight":0,"NpcWords":"Great, Ginkaku was obtained. These two guys are too light. It's impossible for us to win without Ninja Tools of Lord Raikage."},{"id":210272,"idx":1,"url":"jinjiao","name":"jinjiao1","leftRight":1,"NpcWords":"You bastard! How dare you use our Ninja Tools to absorb Ginkaku?"},{"id":210272,"idx":2,"roleId":19,"leftRight":0,"NpcWords":"This guy transformed himself into a Tailed Beast. So as the story said, is Chakra of Tailed Beast sealed inside because he was eaten by Nine Tails?"},{"id":210281,"idx":1,"roleId":19,"leftRight":0,"NpcWords":"Should we combat this monster? It's impossible for us to win\u2026"},{"id":210282,"idx":1,"roleId":21,"leftRight":0,"NpcWords":"Shikamaru, how can we deal with such legendary monsters?"},{"id":210282,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"The combination of Boar-Deer-Butterfly is unrivalled in the Ninja World. You have to exceed them to become a new legend. Be confident. I have an operational plan now."},{"id":210282,"idx":3,"url":"jinjiao","name":"jinjiao1","leftRight":1,"NpcWords":"Disappear before my eyes, you scums! I'll chew you and revenge Ginkaku!"},{"id":210283,"idx":1,"url":"jinjiao","name":"jinjiao1","leftRight":1,"NpcWords":"How can legendary two rays of light in Hidden Cloud Village be defeated by these unknown guys..."},{"id":210291,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Is that guy Teacher Asuma in the distance?"},{"id":210292,"idx":1,"url":"asima","name":"asima1","leftRight":1,"NpcWords":"You've grown, Shikamaru, Choji and Ino."},{"id":210292,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"Thanks a lot, teacher. We've realized the current situation and hope you can also get prepared."},{"id":210301,"idx":1,"roleId":19,"leftRight":0,"NpcWords":"Teacher! Should we feel happy or helpless\u2026Should we combat our teacher?"},{"id":210302,"idx":1,"roleId":21,"leftRight":0,"NpcWords":"I couldn't do it. I couldn't beat down my teacher on the ground. "},{"id":210302,"idx":2,"url":"asima","name":"asima1","leftRight":1,"NpcWords":"Don't look depressed. Now I'm against you and already dead. Don't hold your hand and come to beat the fatso!"},{"id":210303,"idx":1,"url":"asima","name":"asima1","leftRight":1,"NpcWords":"I don't have anything to tell you. You're already perfect Boar-Deer-Butterfly\u2026"},{"id":210311,"idx":1,"url":"banzang","name":"banzang1","leftRight":0,"NpcWords":"Ninjas of five kingdoms are all here after I wake up\u2026"},{"id":210312,"idx":1,"url":"banzang","name":"banzang1","leftRight":1,"NpcWords":"Either Akatsuki or ninjas of five kingdoms are all my enemies. However, I just can't control this damned Ninjutsu."},{"id":210321,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Is that, Hanzo of the Salamander of Amekagure? He was once a man ranking among top in the Ninja World."},{"id":210322,"idx":1,"url":"banzang","name":"banzang1","leftRight":1,"NpcWords":"Any ninja may try to protect their own interests. A peaceful Ninja World doesn't exist at all."},{"id":210322,"idx":2,"roleId":90,"leftRight":0,"NpcWords":"You once sought peace but betrayed your belief to survive. The finishing line for humans is the time of betraying belief instead of death. Didn't you say that?"},{"id":210323,"idx":1,"url":"banzang","name":"banzang1","leftRight":1,"NpcWords":"Seal me\u2026I'll give my previous peace belief to you\u2026"},{"id":210331,"idx":1,"url":"jiaodu","name":"jiaodu1","leftRight":1,"NpcWords":"I just couldn't gain peace after death. Come back again?"},{"id":210332,"idx":1,"url":"didala","name":"didala1","leftRight":1,"NpcWords":"Is it reinforcement? Immediately get me out of this damned gear puppet. I still want to blast away more."},{"id":210332,"idx":2,"url":"jiaodu","name":"jiaodu1","leftRight":1,"NpcWords":"You are trapped in such a difficult situation, Deidara. Many of our pawns are eliminated by these Allied Ninja Force."},{"id":210341,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"Everyone is fighting hard, so should I. Ah, Brother Neji, danger!"},{"id":210342,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"Are you okay, Brother Neji? Now no Branch House are protecting Main House. We're in the same boat. "},{"id":210342,"idx":2,"roleId":25,"leftRight":0,"NpcWords":"Miss Hinata \u2026"},{"id":210342,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"Oh, want to demonstrate your blood-relation affection now? It's funny. Just consider them as your last words."},{"id":210351,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I can feel abnormal movement of massive Chakra here. Something wrong must have happened outside. "},{"id":210352,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"Ah, how can such a huge movement escape Naruto's sensing even if he's foolish."},{"id":210352,"idx":2,"roleId":39,"leftRight":1,"NpcWords":"No, Naruto, it's just a huge beast outside. We're here to help you investigate the quest. Let's continue."},{"id":210352,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"Why so many people? No, you're not telling the truth. Something must have happened outside!"},{"id":210361,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Don't stop me. I'm going out."},{"id":210362,"idx":1,"roleId":56,"leftRight":1,"NpcWords":"Stop him. Never let Naruto go out."},{"id":210362,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"Teacher Yamato, what happened outside? Why not let us know about it?"},{"id":210371,"idx":1,"roleId":30,"leftRight":1,"NpcWords":"No need to conceal it any more. Madara provoked the war. However, the Allied Ninja Force ordered you and Eight Tails to stay here. So I won't let you leave."},{"id":210372,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I've become strong, Teacher Iruka. Just let me end the war."},{"id":210372,"idx":2,"roleId":30,"leftRight":1,"NpcWords":"Naruto, I understand you but my task is to keep you as a ninja. Can you understand me?"},{"id":210373,"idx":1,"roleId":30,"leftRight":1,"NpcWords":"Naruto, I know I can't stop you, but do come back alive because you're just like my younger brother\u2026"},{"id":210381,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Iruka, you can rest assured that I'll end the war. Wait for me, everyone!"},{"id":210382,"idx":1,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Hello, you really want to follow Naruto? Why not listen to me? You'll be beaten up by Raikage."},{"id":210382,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Learning in a real fight may absorb it faster, you stupid guy! The barrier is right ahead. Let me help break it. Oh yeah!"},{"id":210382,"idx":3,"roleId":33,"leftRight":1,"NpcWords":"Do stop Naruto, Barrier Team! Damn it! Why did Eight Tails also come out?"},{"id":210391,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Both Eight Tails and Nine Tails appeared? So it's time to get our loot. Come on, Outer Path Avatar!"},{"id":210392,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"What is this? Such a huge one! What's wrong with you, Akamaru? Did you feel terrible Chakra?"},{"id":210392,"idx":2,"roleId":21,"leftRight":0,"NpcWords":"What's this monster, Dad? We can't stop him even if we transform ourselves into giants together!"},{"id":210392,"idx":3,"roleId":81,"leftRight":1,"NpcWords":"This is power of Outer Path Avatar. Tremble, bugs! You'll immediately enter eternal Tsukuyomi."},{"id":210401,"idx":1,"roleId":23,"leftRight":0,"NpcWords":"What terrible Chakra! The bugs become so nervous that they'll be out of control."},{"id":210402,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Is this something to absorb power of Jinchuriki? First use Kinkaku and Ginkaku with power of Nine Tails and then seize an opportunity to absorb it. What a good plan!"},{"id":210402,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"It's a pity that you've become my enemy because you're so clever. However, even the best brain won't work before strong power of Avatar."},{"id":210403,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Retreat after obtaining Chakra of Gold and Silver Brothers. No failure is allowed in this fight. Be cautious\u2026"},{"id":210403,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Hum, the Allied Ninja Force; Next, you'll have to kill each other."},{"id":210411,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Hah, next, it's time to reincarnate those Jinchuriki that killed by us\u2026"},{"id":210412,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Er, we should slip into the base camp of Allied Ninja Force before implementing next plan. Those deceased Jinchuriki are the most suitable candidates."},{"id":210412,"idx":2,"url":"erweirenzhuli","name":"erweirenzhuli1","leftRight":1,"NpcWords":"Ur, I was reincarnated by these damned guys after death. Shit! My body is completely out of control\u2026"},{"id":210421,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Hah, you have to comply after being controlled by this technique. It's impossible to commit suicide."},{"id":210422,"idx":1,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Can't this technique be broken until I'm killed and sealed by others?"},{"id":210422,"idx":2,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Is that the base camp of Allied Ninja Force? Ninjas from the kingdoms have joined hands? I didn't expect they would forget about hatred and cooperate..."},{"id":210422,"idx":3,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Ur, it's bad! My brain is gradually out of control\u2026"},{"id":210423,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Information collected. Next, we can take back Jinchuriki."},{"id":210423,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Good\u2026"},{"id":210431,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Some guys came out of reincarnation. This will be more fun."},{"id":210432,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Huh, this reincarnation guys. This would be more interesting."},{"id":210432,"idx":2,"url":"didala","name":"didala1","leftRight":1,"NpcWords":"Damn, It's not easy being reincarnated. I must make a beautiful explosion even it's only for fun."},{"id":210432,"idx":3,"url":"jiaodu","name":"jiaodu1","leftRight":1,"NpcWords":"Deidara, even you are already dead. Your bad taste didn't change."},{"id":210432,"idx":4,"url":"didala","name":"didala1","leftRight":1,"NpcWords":"What do you understand, you don't have any aesthetic for art. Let's go, we need to play for fun!"},{"id":210432,"idx":5,"roleId":9,"leftRight":0,"NpcWords":"The attack. This is a sneak attack, please alert everyone!"},{"id":210441,"idx":1,"roleId":9,"leftRight":0,"NpcWords":"We must ready to face enemy!"},{"id":210442,"idx":1,"roleId":9,"leftRight":0,"NpcWords":"These guys has been reincarnated using Edo Tensei and they start killing anyone."},{"id":210442,"idx":2,"roleId":10,"leftRight":0,"NpcWords":"You must be careful, these guys are a former member of \"Akatsuki\""},{"id":210442,"idx":3,"url":"jiaodu","name":"jiaodu1","leftRight":1,"NpcWords":"Ah, it's rubbish heart, I'm not interested. Disappeared!"},{"id":210443,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Well, the enemy are undead monsters and always give surprise in the night, like this...... Immediately report to the headquarters and hope they have a good countermeasure."},{"id":211011,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Zetsu, it's time to start next move. Take action and the allied force will fall into chaos soon..."},{"id":211012,"idx":1,"roleId":29,"leftRight":0,"NpcWords":"Lord Mizukage, three Medic Genins are assassinated. The enemy spies seem to have slipped into it."},{"id":211012,"idx":2,"roleId":92,"leftRight":0,"NpcWords":"Medic Ninjas are an important part of the troops. The enemies used a strong technique and wanted us to Kill Each Other?"},{"id":211012,"idx":3,"roleId":3,"leftRight":1,"NpcWords":"Hum, this technique can't be seen through at all. Just look for it in chaos. You'll immediately lose combat ability."},{"id":211021,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"\u2026My technique isn't a morph skill, you'll never identify it. Kill Each Other, ninjas!"},{"id":211022,"idx":1,"url":"ningci","name":"ningci1","leftRight":1,"NpcWords":"Where is team leader Shizune, Sakura? Now many enemy spied have slipped into it. For Medic Ninjas like you, do take care."},{"id":211022,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"She's treating Tonton, predecessor. It twisted its ankles seriously."},{"id":211022,"idx":3,"url":"ningci","name":"ningci1","leftRight":1,"NpcWords":"Er, but that's better than injuring its hands. Can it return to the battlefield?"},{"id":211023,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"You're a fake. Tonton is a pig. How can it have hands?"},{"id":211031,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Even Chakra is the same. It's impossible to identify how many enemies slipped into it?"},{"id":211032,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"The enemies are parasitic clones using doppelganger skill and can even simulate Chakra. We should immediately report to the headquarters."},{"id":211032,"idx":2,"roleId":92,"leftRight":0,"NpcWords":"Communication teams are assassinated, but we can't find our enemies. Our casualties will increase if we can't find them out\u2026"},{"id":211032,"idx":3,"roleId":4,"leftRight":1,"NpcWords":"Hum, you'll collapse soon, the allied force..."},{"id":211041,"idx":1,"url":"zhinai","name":"zhinai1","leftRight":1,"NpcWords":"Hah, which will be my next target? Well, that guy with a dog."},{"id":211042,"idx":1,"roleId":22,"leftRight":0,"NpcWords":"Shit! We can't identify shapeshifts among those guys in white. Secret signals aren't reliable, either. What should we do\u2026"},{"id":211042,"idx":2,"url":"zhinai","name":"zhinai1","leftRight":1,"NpcWords":"\u2026Whir, a dog's nose won't work for this technique. Just go to hell in chaos."},{"id":211051,"idx":1,"url":"luwan","name":"luwan1","leftRight":1,"NpcWords":"Ur, isn't this the fatty pig keeping eating? This guy will never suspect his good friend."},{"id":211052,"idx":1,"roleId":21,"leftRight":0,"NpcWords":"What should we do, Shikamaru? People started to suspect and kill each other\u2026"},{"id":211052,"idx":2,"url":"luwan","name":"luwan1","leftRight":1,"NpcWords":"Haha\u2026"},{"id":211053,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"What should we do? Allied Ninja Force have fallen into chaos and shapeshift enemies can be everywhere. Where is Lord Tsunade?"},{"id":211053,"idx":2,"roleId":29,"leftRight":0,"NpcWords":"Lord Tsunade has gone to stop Eight Tails and Nine Tails with Lord Raikage."},{"id":211061,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"It's reported that Naruto and Killer Bee have broken the barrier. What should we do, Raikage?"},{"id":211062,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Tsunade, never allow my younger brother and Naruto to advance any more. Let's go and stop them. Fundamentally, it's a fight to protect Jinchuriki."},{"id":211062,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Oh, don't be angry, buddy! Can you please get out of the way for us?"},{"id":211071,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"I understand Naruto, but we can't allow the enemies to continue seizing Tailed Beasts. Do stop these two guys."},{"id":211072,"idx":1,"roleId":90,"leftRight":1,"NpcWords":"Go back, Naruto! Stopping you is the decision of the entire Allied Ninja Force."},{"id":211072,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"I can't witness everyone fight for me in vain. It will be meaningless if only I can survive in the end, Grandma!"},{"id":211081,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Tsunade, don't hold you hand. You should understand that we have to stop them for the entire Ninja World!"},{"id":211082,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Well, I'll have to break it through if you insist on stopping me. Sorry, Uncle Raikage!"},{"id":211082,"idx":2,"roleId":94,"leftRight":1,"NpcWords":"You'll die here if you insist, kid! As commander of the Allied Ninja Force, my only duty is to win the war."},{"id":211082,"idx":3,"roleId":77,"leftRight":0,"NpcWords":"You just don't understand, brother. Power of Jinchuriki isn't all for Naruto and me. Our real power is feelings that we can't give up."},{"id":211083,"idx":1,"roleId":94,"leftRight":1,"NpcWords":"Bee, I can understand it more or less as you want to help Naruto so much\u2026Kid, to be a saviour, you must never fail."},{"id":211091,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Well, Uncle Octopus, the main battlefield is right ahead. Let's move and find out those guys with shapeshifts."},{"id":211092,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Uncle Octopus, my Nine Tails state may identify the enemies' malice. These ninjas are all enemy shapeshifts, let's move!"},{"id":211092,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Yeah, training results are demonstrated. Let me handle it."},{"id":211092,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"No way, it's impossible. How can this guy see through my technique?"},{"id":211101,"idx":1,"url":"qiandaipopo","name":"qiandaipopo1","leftRight":1,"NpcWords":"What a disgusting technique! I was even reincarnated to attack our side even if I died..."},{"id":211102,"idx":1,"roleId":32,"leftRight":0,"NpcWords":"...Granny Chiyo, are you also reincarnated?"},{"id":211102,"idx":2,"url":"qiandaipopo","name":"qiandaipopo1","leftRight":1,"NpcWords":"Kankuro, your Puppet Technique is further improved. Sasori also gave his puppet to you, right? Hi, don't hold your hand and beat me down quickly."},{"id":211111,"idx":1,"url":"junmalv","name":"junmalv1","leftRight":1,"NpcWords":"What happened? Didn't I die?"},{"id":211112,"idx":1,"url":"junmalv","name":"junmalv1","leftRight":1,"NpcWords":"I'm fully immersed in Lord Orochimaru's power. I won't let him down this time."},{"id":211112,"idx":2,"url":"junmalv","name":"junmalv1","leftRight":1,"NpcWords":"Though I don't understand, Corrupt Reincarnation is one of Lord Orochimaru's techniques. I'll follow him for no reason even if I die."},{"id":211112,"idx":3,"roleId":26,"leftRight":0,"NpcWords":"It's this terrible guy again. He's highly loyal to Orochimaru..."},{"id":211121,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"A few terrible Chakras are ahead. Which strong enemies are summoned?"},{"id":211122,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"This dirty move can summon and restrain the dead. How dare you use such a move to summon me?"},{"id":211122,"idx":2,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"Enemies and lovers are destined to meet. We once killed each other, but I didn't expect that we would be summoned by someone."},{"id":211122,"idx":3,"roleId":93,"leftRight":0,"NpcWords":"Previous Kages are all summoned. It's hard to deal with\u2026"},{"id":211131,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"We're summoned one by one, but what if we personally destroy our successors in the villages?"},{"id":211132,"idx":1,"url":"sandaileiying","name":"sandaileiying1","leftRight":1,"NpcWords":"Don't be so pessimistic. The children in the villages have grown."},{"id":211132,"idx":2,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"That's good\u2026"},{"id":211132,"idx":3,"roleId":97,"leftRight":0,"NpcWords":"Among them\u2026including my father\u2026"},{"id":211141,"idx":1,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"Onoki? You little guy has become an old man? You have lived too long."},{"id":211142,"idx":1,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"It's okay to combat ninjas from other villages, but how can we combat our own people?"},{"id":211142,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"Mentor, power of previous Dust Release is still so strong."},{"id":211151,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"\u2026Are you Gaara?"},{"id":211152,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"Judged from power, are you Shukaku? No, you're Gaara?"},{"id":211152,"idx":2,"roleId":97,"leftRight":0,"NpcWords":"Shukaku doesn't exist, father. I won't be a Jinchuriki created by you any more."},{"id":211161,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"Hello, why are you ninjas so weak? Can anyone stop me?"},{"id":211162,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"Anyway, we can't control ourselves and may automatically launch counterattacks. However, I'll tell you our weakness. Let us go back earlier."},{"id":211171,"idx":1,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"Hum, Onoki, you can use your Dust Release skillfully now. So you've made great progress when I'm not with you."},{"id":211172,"idx":1,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"Onoki, stop me and then seize loots quickly in the fight to win advantages. Did you get it?"},{"id":211172,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"I'll stop you, Lord Mu. But I won't seize loots."},{"id":211181,"idx":1,"url":"sandaileiying","name":"sandaileiying1","leftRight":1,"NpcWords":"Why didn't I see A? Is his temper still irritable? He's really like me..."},{"id":211182,"idx":1,"url":"sandaileiying","name":"sandaileiying1","leftRight":1,"NpcWords":"Try to stop us whatever you do though it's a little hard."},{"id":211191,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"Gaara, your technique has become so strong and amazing without Shukaku's power..."},{"id":211192,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"You were once a loser in my eyes, Gaara. Now let me re-evaluating your value. Try exceeding me."},{"id":211192,"idx":2,"roleId":97,"leftRight":0,"NpcWords":"\u2026"},{"id":211201,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Ur, are those figures Pain and Itachi?"},{"id":211202,"idx":1,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"I didn't expect my opponents would be you. Naruto, you've grown and is worthy of my younger disciple."},{"id":211202,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"Thanks for helping me recognizing my pains, my Dad and Mom and everyone thus you can meet me now."},{"id":211202,"idx":3,"url":"you","name":"you1","leftRight":1,"NpcWords":"Tell me what has happened to Sasuke, Naruto? Why didn't he return to the village? It's bad, my body\u2026evade my technique quickly!"},{"id":211211,"idx":1,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"Which guy cast such a technique? Didn't Orochimaru die earlier?"},{"id":211212,"idx":1,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"Stay away from me, Naruto. I almost can't move or control myself!"},{"id":211221,"idx":1,"url":"you","name":"you1","leftRight":1,"NpcWords":"Where is Sasuke? Did Madara tell him something about me\u2026Ur, don't look into my eyes\u2026"},{"id":211222,"idx":1,"url":"you","name":"you1","leftRight":1,"NpcWords":"Stay away, don't look into my eyes. My body will start the Sharingan!"},{"id":211222,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"\u2026"},{"id":211222,"idx":3,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Hi, Bee, wake up, idiot! That's an Illusion Skill!"},{"id":211231,"idx":1,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"Naruto, beat me down quickly before I cast Six Paths of Pain next time."},{"id":211232,"idx":1,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"Naruto, I'll go back to our teacher. Do let me see your stories."},{"id":211232,"idx":2,"url":"peien","name":"peien1","leftRight":1,"NpcWords":"For this story, step 1 is Jiraiya, a perfect start; step 2 is me, extremely bad; and step 3 is you, do have a perfect ending."},{"id":211233,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"Elder disciple, you can rest assured that I'll inherit your will."},{"id":211241,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I also know about you, Itachi. Sasuke wanted to retaliate upon the Hidden Leaf that made his elder brother suffer."},{"id":211242,"idx":1,"url":"you","name":"you1","leftRight":1,"NpcWords":"I originally wanted to use Shisui's eyes to impose the strongest Illusion Skill guarding the Hidden Leaf and prevent Sasuke from falling into a wrong path, but deviation still happened\u2026"},{"id":211242,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"You've contributed too much to the village, Itachi. Let me handle the remaining work."},{"id":211242,"idx":3,"url":"you","name":"you1","leftRight":1,"NpcWords":"It's great for my younger brother to have such a friend like you. Please take care of Sasuke."},{"id":211243,"idx":1,"url":"you","name":"you1","leftRight":0,"NpcWords":"I've broken away from the caster for now. Let me handle this technique. Go and do what you should do, Naruto. Take care of him, Killer Bee."},{"id":211251,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"My woman died when delivering Gaara, so I transferred pains and hatred to this kid. I'm quite mistaken."},{"id":211252,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"You really grow up. Of course we always trust you. We once cornered you to test if you would be out of control..."},{"id":211252,"idx":2,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"These sands are power of your mother. She has been deeply loving and guarding you. It's me who deprived you of your life. I'm not a qualified father."},{"id":211252,"idx":3,"roleId":97,"leftRight":0,"NpcWords":"My mother is really great, but I originally obtained medicine to heal my soul from my father. "},{"id":211253,"idx":1,"url":"sidaifengying","name":"sidaifengying1","leftRight":1,"NpcWords":"Take care of the village, Gaara\u2026You've exceeded us."},{"id":211261,"idx":1,"roleId":97,"leftRight":0,"NpcWords":"Ur? Is that figure Naruto? Isn't he on the turtle island? Why did Raikage allow him to come here?"},{"id":211262,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I'm here, Gaara. Cover me, dwarf Grandpa."},{"id":211262,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"Dwarf Grandpa? I'm Tsuchikage!"},{"id":211262,"idx":3,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"Dwarf Grandpa! What a funny name! Hi, Onoki, I'll see how many moves you can resist."},{"id":211263,"idx":1,"url":"wu","name":"wu1","leftRight":1,"NpcWords":"You've hated other villages. I didn't expect you would cooperate with them seamlessly..."},{"id":211271,"idx":1,"roleId":31,"leftRight":0,"NpcWords":"So strong\u2026Is 3rd Raikage a monster? How could he die at that time?"},{"id":211272,"idx":1,"url":"sandaileiying","name":"sandaileiying1","leftRight":1,"NpcWords":"I use Lightning Release. Ask ninjas using earth release to attack me. It's bad. I can't control my body."},{"id":211272,"idx":2,"roleId":31,"leftRight":0,"NpcWords":"No, their attack doesn't work at all. The only guy exceeding me in wind release in the Allied Ninja Force is ..."},{"id":211272,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"You! I'm here!"},{"id":211273,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"3rd Raikage is really unrivalled. I won't resist him unless I hit his wrist and let him hurt himself."},{"id":211281,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"Gosh, I didn't feel I won because I'm too strong\u2026"},{"id":211282,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"I told you to stay away from me because my technique is hard to deal with. Is there anyone stronger in the Allied Ninja Force?"},{"id":211282,"idx":2,"leftRight":0,"NpcWords":"Mix gold dust into sands and I'll end the fight before it stops hailing."},{"id":211283,"idx":1,"url":"erdaishuiying","name":"erdaishuiying1","leftRight":1,"NpcWords":"Hey, kid, you're a real glittering gold! I haven't had great fun for long."},{"id":211291,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"New Corrupt Reincarnation? Wait, that figure, that Chakra, impossible, it's impossible\u2026"},{"id":211292,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"That guy even revived me in the way of Corrupt Reincarnation, violating our agreement\u2026"},{"id":211292,"idx":2,"roleId":93,"leftRight":0,"NpcWords":"Is that guy Madara? He must be dead as he's reincarnated\u2026"},{"id":211292,"idx":3,"roleId":97,"leftRight":0,"NpcWords":"Who is that masked man? He always calls himself Madara\u2026what's his real intent?"},{"id":211301,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"That masked man calling himself Madara has cheated us\u2026this man is Madara!"},{"id":211302,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"He used Susanoo. Don't look at his eyes which is Mangekyo Sharingan. "},{"id":211302,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"No, no, it's The Rinnegan. How can he have The Rinnegan?"},{"id":211303,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Sharingan can finally evolve to The Rinnegan. Nagato's eyes are mine. It's time to take them back."},{"id":211311,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"I didn't die but obtain his cell capabilities when combating 1st Hokage. Now I'll let you see the gap of Ninjutsu."},{"id":211312,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"It's...Meteorite. What is this power? How can I resist it..."},{"id":211312,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Damn it! Madara has such a Chakra! Naruto, I\u2019ll lend my power to you. I hate him. I would rather help you than be manipulated by him."},{"id":211312,"idx":3,"roleId":102,"leftRight":1,"NpcWords":"Hum, Nine Tails, you remember my Chakra so clearly. No hurry. I'll place a collar on this animal."},{"id":211321,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Five Kages? Why look so weak\u2026"},{"id":211322,"idx":1,"roleId":93,"leftRight":0,"NpcWords":"This war is not to purely protect you, Naruto."},{"id":211322,"idx":2,"roleId":92,"leftRight":0,"NpcWords":"It has evolved to a war of protecting everyone."},{"id":211322,"idx":3,"roleId":94,"leftRight":0,"NpcWords":"Previously scattered ninja villages have been united."},{"id":211322,"idx":4,"roleId":97,"leftRight":0,"NpcWords":"We'll deal with this Madara. Go and handle the other one, Naruto."},{"id":211322,"idx":5,"roleId":90,"leftRight":0,"NpcWords":"Naruto, our Five Kages have something to tell you: do win!"},{"id":211322,"idx":6,"roleId":106,"leftRight":0,"NpcWords":"You can rest assured that I'll definitely win."},{"id":211322,"idx":7,"roleId":81,"leftRight":1,"NpcWords":"Hah, previous rival ninjas are just a rabble even if you're united. Now let me smash your funny alliance."},{"id":211331,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Hi, test my move, false Madara!"},{"id":211332,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"You shouldn't be so weak after mastering power of Nine Tails. Come on, let me see a great duel among Jinchuriki."},{"id":211332,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Take care, Naruto. These guys are all previous Jinchuriki."},{"id":211332,"idx":3,"url":"erweirenzhuli","name":"erweirenzhuli1","leftRight":1,"NpcWords":"Ur, completely out of control. What is this technique?"},{"id":211341,"idx":1,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"An order, must be obeyed\u2026"},{"id":211342,"idx":1,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Bee, these guys are all products of Corrupt Reincarnation with both Rinnegan and Sharingan."},{"id":211342,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"We became pawns after being killed\u2026This cruel persecution made me very angry, yo!"},{"id":211342,"idx":3,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Damn it! We're being used. Hi, kill us quickly to destroy this technique."},{"id":211351,"idx":1,"url":"siweirenzhuli","name":"siweirenzhuli1","leftRight":1,"NpcWords":"Kill\u2026"},{"id":211352,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Who are you? I'll stop two Madaras!"},{"id":211352,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Kabuto was stupid and called Madara\u2026Don't care who I am. My only wish is to realize Eye of the Moon Plan."},{"id":211352,"idx":3,"url":"siweirenzhuli","name":"siweirenzhuli1","leftRight":1,"NpcWords":"We're even used to deal with our partners in the village\u2026oh, my head really hurts\u2026"},{"id":211361,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Eye of the Moon? What did you guys consider these Jinchuriki and Tailed Beasts to be?"},{"id":211362,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"This world filled with despair is completely worthless. I'll definitely get Eight Tails, Nine Tails and Eye of the Moon as well."},{"id":211362,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"You're not supposed to start a war willfully even if you feel worthless. I'll definitely remove your outdated mask!"},{"id":211362,"idx":3,"url":"wuweirenzhuli","name":"wuweirenzhuli1","leftRight":1,"NpcWords":"Evade our moves, kid!"},{"id":211371,"idx":1,"url":"liuweirenzhuli","name":"liuweirenzhuli1","leftRight":1,"NpcWords":"Stay away from me\u2026I can't control myself\u2026"},{"id":211372,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"A Jinchuriki with Dojutsu power gets stronger and is hard to deal with."},{"id":211372,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"These guys should carry a Chakra receiver like Pain."},{"id":211372,"idx":3,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Really? So we should pull them out and defeat them one by one."},{"id":211372,"idx":4,"url":"liuweirenzhuli","name":"liuweirenzhuli1","leftRight":1,"NpcWords":"Oh, no, Tailed Beast's power is almost out of control\u2026"},{"id":211381,"idx":1,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"No\u2026my internal Tailed Beast already\u2026"},{"id":211382,"idx":1,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"These Jinchuriki all realized Tailed Beast Evolution. Should we retreat for now, Naruto?"},{"id":211382,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"You have a Sharingan, so do we."},{"id":211382,"idx":3,"roleId":84,"leftRight":0,"NpcWords":"Plus prideful Might Guy in the Hidden Leaf. we're here, Naruto and Killer Bee!"},{"id":211382,"idx":4,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"Please eliminate us quickly!"},{"id":211391,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"This masked man isn't Madara? Who is it?"},{"id":211392,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"You won't stop Eye of the Moon Plan whatever you do. I'll destroy this worthless world!"},{"id":211401,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Ur...Madara's strength is really strong. He's worthy of my grandpa's rival\u2026"},{"id":211402,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Too weak! Is this strength of Five Kages? You're doomed to failure\u2026"},{"id":211403,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"The world will bow to my power soon\u2026"},{"id":211411,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Long entanglement may weaken control over the techniques\u2026"},{"id":211412,"idx":2,"roleId":78,"leftRight":1,"NpcWords":"Hum, I can't trust that masked man. Perhaps he'll deal with me after eliminating the Allied Ninja Force."},{"id":211412,"idx":3,"roleId":78,"leftRight":1,"NpcWords":"If I take advantage of the fight to seize Kakashi's Sharingan plus my own study, he can do nothing to me."},{"id":211412,"idx":4,"url":"siweirenzhuli","name":"siweirenzhuli1","leftRight":1,"NpcWords":"Kill!"},{"id":211412,"idx":5,"roleId":106,"leftRight":0,"NpcWords":"Ur, now his target is Teacher Kakashi. Take care!"},{"id":211421,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Do Jinchuriki want to attack my eyes? Damn it! Kabuto\u2026"},{"id":211422,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"It seems that Kabuto isn't in the same boat with that masked man. Does he want to benefit himself in the fight?"},{"id":211422,"idx":2,"url":"wuweirenzhuli","name":"wuweirenzhuli1","leftRight":1,"NpcWords":"Sorry, Kakashi. Next move is my unique skill. Do evade it."},{"id":211431,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Damn it! Kabuto controlled Jinchuriki and changed his target!"},{"id":211432,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"It's not so easy to get my eyes. How can I give them to others as they were left by my best friend?"},{"id":211432,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"...Kakashi\u2026"},{"id":211432,"idx":3,"url":"liuweirenzhuli","name":"liuweirenzhuli1","leftRight":1,"NpcWords":"What abhorrent guys! Never want to use me. Target me with your next move, Naruto."},{"id":211433,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Do you want to betray me, Kabuto? If you dare take this opportunity to seize Sharingan and let go of Eight Tails and Nine Tails ..."},{"id":211433,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"I'll kill you immediately! Don't forget, even if Madara is reincarnated by you. He's likely to break away from you."},{"id":211433,"idx":3,"roleId":78,"leftRight":1,"NpcWords":"Ur, shit, I'm spotted\u2026I have no choice. Attack Eight Tails and Nine Tails, Jinchuriki!"},{"id":211441,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"Hey, it's delayed too long."},{"id":211442,"idx":1,"roleId":69,"leftRight":1,"NpcWords":"Hey, quickly recover our force. Our plan can't be delayed."},{"id":211442,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Well, I know. Don't bother it. Do you watching my back spot?"},{"id":211442,"idx":3,"roleId":83,"leftRight":0,"NpcWords":"Who the hell is the man in this mask?  Where?"},{"id":211451,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"These field could be full of trash!"},{"id":211452,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"There is a mistake itself in the ninja. If needed in any case, I will end it by my hand!"},{"id":211453,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Ninja, Tailed Beast, their existence is not necessary! You will be punished immediately!"},{"id":212011,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Damn it! This masked man is tough and I can't find a way to hurt him\u2026"},{"id":212012,"idx":1,"url":"erweirenzhuli","name":"erweirenzhuli1","leftRight":1,"NpcWords":"\u2026ur, internal Two Tails was bound with Chakra chain\u2026"},{"id":212012,"idx":2,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Ur, that guy is torturing Two Tails to control it completely? Our Tailed Beasts also have feelings and may get angry in this case."},{"id":212012,"idx":3,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Hum, ninjas always consider our Tailed Beasts as pets. Seen from the number of tails, you're second to me only. Immediately go and eliminate them."},{"id":212012,"idx":4,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Strength is irrelevant to the number of tails. You're so disgusting. No wonder that One Tail Shukaku dislikes you so much."},{"id":212012,"idx":5,"url":"erweirenzhuli","name":"erweirenzhuli1","leftRight":1,"NpcWords":"So painful\u2026Damn it! I have no choice but to attack again\u2026"},{"id":212021,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"Tailed Beasts lack sufficient attack. These animals should wear their collars earlier. "},{"id":212022,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Purely using Dojutsu power to control 6 Tailed Beasts needs to consume a huge amount of Chakra."},{"id":212022,"idx":2,"roleId":81,"leftRight":1,"NpcWords":"Did your eye spot it, Kakashi? Well, I'll make them stronger."},{"id":212022,"idx":3,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Internal Chakra, already\u2026It'll be thoroughly bound up with this chain."},{"id":212031,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Damn it! Stop! Do find a way to help Tailed Beasts unlock their chains! Shadow Clone!"},{"id":212032,"idx":1,"roleId":77,"leftRight":0,"NpcWords":"Naruto, you can't use Shadow Clone like that. You're swayed by personal feelings and will die."},{"id":212032,"idx":2,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Bee, theoretically Naruto shouldn't withstand it any more, but he's still okay. It seems that Nine Tails has stopped absorbing his Chakra, they're likely\u2026"},{"id":212032,"idx":3,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"\u2026Want to help Tailed Beasts? Naruto \u2026"},{"id":212032,"idx":4,"url":"siweirenzhuli","name":"siweirenzhuli1","leftRight":1,"NpcWords":"My internal Tailed Beast is highly painful. Kid of Nine Tails, kill me and pull out these black sticks."},{"id":212041,"idx":1,"url":"wuweirenzhuli","name":"wuweirenzhuli1","leftRight":1,"NpcWords":"Please stop us, kid from the Hidden Leaf..."},{"id":212042,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Thanks for lending me power when combating Madara. You did me a great favor."},{"id":212042,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"You're so modest and sound disgusting! Connect your Chakra to mine!"},{"id":212042,"idx":3,"url":"wuweirenzhuli","name":"wuweirenzhuli1","leftRight":1,"NpcWords":"Sorry, I can't stop attacking you while being controlled. Take care."},{"id":212051,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"\u2026Why? This kid let me remember Six Paths\u2026"},{"id":212052,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Nine Tails, you're no longer a Demon Fox now but a partner of a ninja from the Hidden Leaf. Let's move!"},{"id":212052,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Let's clarify it first. It's the first Tailed Beast Evolution and the synchronization isn't perfect. Take care!"},{"id":212052,"idx":5,"url":"liuweirenzhuli","name":"liuweirenzhuli1","leftRight":1,"NpcWords":"Evade my attack, kid from the Hidden Leaf! Come on, so close\u2026"},{"id":212061,"idx":1,"roleId":81,"leftRight":1,"NpcWords":"When could Naruto synchronize Tailed Beast Evolution with Nine Tails?"},{"id":212062,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Has Naruto assimilated Nine Tails completely? This power is awesome."},{"id":212062,"idx":2,"roleId":84,"leftRight":0,"NpcWords":"It's a real monster war."},{"id":212062,"idx":3,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"Good, well done, just eliminate us all. As ninja, how can we be used as pawns by others?"},{"id":212062,"idx":1,"url":"sanweirenzhuli","name":"sanweirenzhuli1","leftRight":1,"NpcWords":"Well done, ninja from the Hidden Leaf\u2026thank you for not letting us kill our own people\u2026"},{"id":212062,"idx":2,"url":"siweirenzhuli","name":"siweirenzhuli1","leftRight":1,"NpcWords":"We're going back to another world, kid. Please take care of power of Tailed Beasts and this world!"},{"id":212063,"idx":3,"roleId":81,"leftRight":1,"NpcWords":"\u2026I, I even sweated, these guys\u2026"},{"id":212071,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Look, Teacher Kakashi. That guy's mask has a wound. We hit him!"},{"id":212072,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Kakashi, our attack worked to that guy, youthful vigor!"},{"id":212072,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"This guy's alien space seems to be connected to mine, is he...Naruto and Guy, help me and I'll confirm something."},{"id":212072,"idx":3,"roleId":81,"leftRight":1,"NpcWords":"Hum\u2026it seems that Kakashi has found secrets about the alien space\u2026"},{"id":212073,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Great, we finally got him. Let's look at the man under the mask."},{"id":212073,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"It's you...Obito\u2026"},{"id":212073,"idx":3,"roleId":98,"leftRight":1,"NpcWords":"...Kakashi\u2026"},{"id":212081,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"Obito, why Obito? Wasn't he one of Kakashi's teammates?"},{"id":212082,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"He was once my partner...Obito, I thought you died\u2026Why did start this war in the Ninja World?"},{"id":212082,"idx":2,"roleId":98,"leftRight":1,"NpcWords":"My life or death doesn't matter. If you insist on asking me, it's because you didn't keep your promise and didn't save Rin."},{"id":212091,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"\u2026hum, does that masked guy want to trap me here? You just think it too simple\u2026"},{"id":212092,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Why is it so noisy? What happened? Where is that masked guy?"},{"id":212092,"idx":2,"roleId":69,"leftRight":1,"NpcWords":"Why did you come out? Damn it! My boss asked me to stop you. Did you wipe out all my clones?"},{"id":212093,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Get away, you bastard! Don't delay my retaliation upon the Hidden Leaf."},{"id":212101,"idx":1,"url":"you","name":"you1","leftRight":1,"NpcWords":"Hurry up. I'm not sure how long the reincarnated body will last\u2026I'll definitely find the caster behind the technique."},{"id":212102,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Is that \u2026 is that figure Itachi? \u2026wait, didn't you die, Itachi? Why are you here?"},{"id":212102,"idx":2,"url":"you","name":"you1","leftRight":1,"NpcWords":"I have no time to explain to you. I'll go and stop that Corrupt Reincarnation skill, otherwise \u2026"},{"id":212102,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"I don't care what you want. I've lots of questions to ask you as you've appeared before me, wait!"},{"id":212111,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Itachi, don't want to evade me\u2026ur, is this guy Kabuto? But he looks like Orochimaru."},{"id":212112,"idx":1,"url":"you","name":"you1","leftRight":0,"NpcWords":"Well, Sasuke, I'll talk to you later provided that you can defeat but won't kill him."},{"id":212112,"idx":2,"roleId":78,"leftRight":1,"NpcWords":"Itachi, I didn't expect you could break away from Corrupt Reincarnation\u2026Which side will you select, Sasuke?"},{"id":212112,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"You always said next time, but you died, Itachi. So do keep your promise now."},{"id":212121,"idx":1,"url":"you","name":"you1","leftRight":0,"NpcWords":"Sasuke, do you still remember our catching a wild boar in childhood? Just use that tactics to deal with him!"},{"id":212122,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"Hah, it's funny. Cooperation of brothers? Don't disregard me."},{"id":212122,"idx":2,"roleId":78,"leftRight":1,"NpcWords":"I found Ryuchi Cave and received trainings from White Snake Sage. Now I have exceeded Lord Orochimaru in every aspect."},{"id":212131,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Hum, are you evaded by Orochimaru's cells? Itachi, I won't look at your figure this time. Wait and see! "},{"id":212132,"idx":1,"roleId":78,"leftRight":1,"NpcWords":"I'll never let go of the Hidden Leaf where we were used and abandoned. I've become a sage and will establish my presence."},{"id":212133,"idx":1,"url":"you","name":"you1","leftRight":0,"NpcWords":"I've used a technique to thoroughly trap Kabuto. Corrupt Reincarnation will also be removed soon. There is no time left\u2026"},{"id":212133,"idx":2,"url":"you","name":"you1","leftRight":0,"NpcWords":"I've been deceiving you and hope you can forgive me. I'll love you deeply no matter how you develop in the future..."},{"id":212133,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"Elder brother\u2026"},{"id":212141,"idx":1,"url":"junmalv","name":"junmalv1","leftRight":1,"NpcWords":"\u2026I, am disappearing? Is Corrupt Reincarnation already removed? I really want to see you again, Lord Orochimaru\u2026"},{"id":212142,"idx":1,"roleId":90,"leftRight":0,"NpcWords":"Why? Wasn't Corrupt Reincarnation skill removed? Why didn't Madara vanish?"},{"id":212142,"idx":2,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"This technique has only a risk. If affected guys can form hand gestures, they won't be controlled but will have Undying Shells as well as endless Chakra."},{"id":212143,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Hum\u2026the barriers are cleared. Now it's time to go and take back Eight Tails and Nine Tails out there."},{"id":212151,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Ur, this disgusting Chakra is Madara's. He's coming. Take care, Naruto."},{"id":212152,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Not finished yet, Obito? Clearly you should use Nagato's Art of Rinne Rebirth to revive me. Why Corrupt Reincarnation?"},{"id":212152,"idx":2,"roleId":98,"leftRight":1,"NpcWords":"Something wrong happened. Nagato betrayed and used that technique to revive all ninjas of the Hidden Leaf."},{"id":212152,"idx":3,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Hum, I can still be revived with power of Ten Tails. Let me deal with Jinchuriki. You should go and handle others."},{"id":212161,"idx":1,"roleId":98,"leftRight":1,"NpcWords":"Kakashi, you didn't keep your promise. Rin died due to your weakness\u2026"},{"id":212162,"idx":1,"roleId":98,"leftRight":1,"NpcWords":"What this world breeds are all wastes. I'll re-create a world with Rin."},{"id":212162,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Obito, I admit I was useless and failed to protect Rin. What I can do now is to protect current Naruto."},{"id":212171,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Eight Tails and Nine Tails, come and be absorbed quickly because you're originally a part of Ten Tails, hah\u2026"},{"id":212172,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"What's that? That terrible guy has endless Chakra."},{"id":212172,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"We must defeat Ten Tails before it's revived completely. Listen, Octopus, first see through his moves in the distance and then attack from close range. "},{"id":212172,"idx":3,"url":"bawei","name":"bawei","leftRight":0,"NpcWords":"Great! Let's move!"},{"id":212172,"idx":4,"roleId":98,"leftRight":1,"NpcWords":"Come on, power of Ten Tails will be perfect after absorbing you two."},{"id":212181,"idx":1,"roleId":98,"leftRight":1,"NpcWords":"What a rabble! Your power won't work at all."},{"id":212182,"idx":1,"roleId":75,"leftRight":0,"NpcWords":"No. 1 and No. 2 Troops have arrived!"},{"id":212182,"idx":2,"roleId":28,"leftRight":0,"NpcWords":"No. 3 and No. 4 Troops have arrived!"},{"id":212182,"idx":3,"roleId":32,"leftRight":0,"NpcWords":"No. 5 and Surprise Attack Troops have arrived!"},{"id":212182,"idx":4,"roleId":29,"leftRight":0,"NpcWords":"Medic and Perception Troops have arrived!"},{"id":212182,"idx":5,"roleId":106,"leftRight":0,"NpcWords":"We're the strongest Ninjutsu in the history of Ninja World - technique of Allied Ninja Force instead of a rabble. Wake up!"},{"id":212182,"idx":6,"roleId":98,"leftRight":1,"NpcWords":"Hum, Allied Ninja Force Technique? You're just bluffing. The buildup of sands is only a pile of sands."},{"id":212191,"idx":1,"roleId":28,"leftRight":0,"NpcWords":"Naruto, we lack Chakra, so we can't do anything to that guy. Can you please transmit Chakra of the Nine Tails?"},{"id":212192,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Naruto, I've extracted it. Immediately transmit my Chakra."},{"id":212192,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"Ok! Shadow Clones, transmit Chakra of Nine Tails to every member of Allied Ninja Force."},{"id":212192,"idx":3,"roleId":28,"leftRight":0,"NpcWords":"Everyone can have their Combat power increased several times after obtaining Chakra of the Nine Tails. This will enable them to launch an effective attack on Ten Tails with individual Ninjutsus."},{"id":212192,"idx":4,"roleId":98,"leftRight":1,"NpcWords":"The kid could even distribute Chakra of the Nine Tails? It's good, but you're still useless after obtaining power."},{"id":212201,"idx":1,"roleId":49,"leftRight":0,"NpcWords":"Ur, Jugo, look, this scroll\u2026great I'll be able to present a big gift to Sasuke."},{"id":212202,"idx":1,"roleId":49,"leftRight":0,"NpcWords":"I finally found you, Sasuke. You see, I got this scroll. We'll be able to dominate the Ninja World with it."},{"id":212202,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"I'm not interested in that. What's in this scroll may let me decide if I'll continue destroying the Hidden Leaf. So, I'll recall Orochimaru."},{"id":212202,"idx":3,"roleId":51,"leftRight":0,"NpcWords":"Sasuke's will is Kimimaro's. I'm glad to help you. Start to cast the technique and prevent Chakra of Orochimaru from being out of control."},{"id":212202,"idx":4,"roleId":89,"leftRight":1,"NpcWords":"Ur\u2026ah\u2026oh\u2026"},{"id":212203,"idx":1,"roleId":89,"leftRight":0,"NpcWords":"I didn't expect you would reorganize my Chakra and revive me. I'll help you this time. Follow me\u2026"},{"id":212211,"idx":1,"roleId":89,"leftRight":0,"NpcWords":"This scroll records Anti the Reaper Death Seal. So I'll be able to take back my hands and use Corrupt Reincarnation to revive previous Hokages."},{"id":212212,"idx":1,"roleId":89,"leftRight":0,"NpcWords":"We need to sacrifice something living to cast the reincarnation skill, i.e. Zetsu's clones monitoring from Sasuke."},{"id":212212,"idx":2,"roleId":69,"leftRight":1,"NpcWords":"Damn it! Orochimaru, you made things worse and drove me out of Sasuke."},{"id":212213,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":0,"NpcWords":"Ur, alas, why was I reincarnated again?"},{"id":212213,"idx":2,"url":"feijian","name":"feijian1","leftRight":0,"NpcWords":"It seems that my Kinjutsu is misused by someone in this world."},{"id":212213,"idx":3,"url":"sandaihuoying","name":"sandaihuoying1","leftRight":0,"NpcWords":"Orochimaru, didn't I seal your hands? How could you take them back?"},{"id":212213,"idx":4,"url":"shuimen","name":"shuimen1","leftRight":0,"NpcWords":"Hi, predecessor, I'm 4th Hokage Minato."},{"id":212221,"idx":1,"url":"sandaihuoying","name":"sandaihuoying1","leftRight":0,"NpcWords":"Why is Sasuke with Orochimaru? What happened?"},{"id":212222,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Hokages, I need you to tell the truth before I decide whether to destroy the Hidden Leaf or not."},{"id":212222,"idx":2,"url":"feijian","name":"feijian1","leftRight":1,"NpcWords":"What a rampant kid! I'll kill you here before you destroy the village."},{"id":212223,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":0,"NpcWords":"Stop, Tobirama! Don't you listen to me?"},{"id":212223,"idx":2,"url":"feijian","name":"feijian1","leftRight":0,"NpcWords":"My elder brother's furious Chakra was also terrifying\u2026"},{"id":212231,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":0,"NpcWords":"I tried to protect the village but led to tragedies like Uchiha. I'll tell you something starting with past stories of Senju and Uchiha..."},{"id":212232,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"...I decided to guard the Hidden Leaf Itachi wished to guard..."},{"id":212232,"idx":2,"url":"zhujian","name":"zhujian1","leftRight":0,"NpcWords":"Well, get prepared to fight, Hokages. Let's end it with Madara now!"},{"id":212232,"idx":3,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"This Chakra is Hashirama. Hah, I'm looking forward to seeing it. Many years have passed and previous opponents meet again."},{"id":212233,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Sasuke! You're back!"},{"id":212233,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"Sasuke, you've kept me waiting for so long!"},{"id":212233,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"Many things happened all the way\u2026Now I'll fight along with you."},{"id":212241,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"This moment finally came. We'll end it immediately, Hashirama \u2026"},{"id":212242,"idx":1,"roleId":98,"leftRight":1,"NpcWords":"You're all a bunch of bums, Kakashi. You'll finally become what I am like now no matter how you struggle."},{"id":212242,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Obito, Naruto is just like what you used to be. I'll guard what you used to be even if you're killed now. The war is to be ended soon."},{"id":212243,"idx":1,"roleId":104,"leftRight":1,"NpcWords":"You, why did you say the war would end? I, I'm Jinchuriki of Ten Tails."},{"id":212251,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"This guy absorbed all of power of Ten Tails and became Jinchuriki."},{"id":212252,"idx":1,"url":"feijian","name":"feijian1","leftRight":0,"NpcWords":"This guy even broke all sage skills and seals confining Ten Tails, really strong!"},{"id":212252,"idx":2,"url":"shuimen","name":"shuimen1","leftRight":0,"NpcWords":"First find a way to create opportunities and then analyze the enemies' moves and capabilities."},{"id":212252,"idx":3,"roleId":104,"leftRight":1,"NpcWords":"I'm Jinchuriki of Ten Tails and own power of all Tailed Beasts. The only way before you is to die."},{"id":212261,"idx":1,"url":"shuimen","name":"shuimen1","leftRight":0,"NpcWords":"Naruto, you've grown up and let's talk about the old days later. Now let's us, son and father, beat down this guy."},{"id":212262,"idx":1,"roleId":104,"leftRight":1,"NpcWords":"It's time to make preparations prior to Tsukuyomi. Start to clear all barriers."},{"id":212262,"idx":2,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Naruto, Minato once split me in half and sealed me inside his body and your body respectively. Now it's time for us to combat together."},{"id":212271,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Hi, Dad, what's that? Why did a huge tree grow out of it?"},{"id":212272,"idx":1,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Is that final form of Shinju for Ten Tails? It's said that humans seized Shinju's Chakra to put down the war, generating Ninjas."},{"id":212272,"idx":2,"roleId":104,"leftRight":1,"NpcWords":"Hah, you'll fall into despair soon. When Shinju blossoms, Sharingan may be mirrored in the moon and unlimited Tsukuyomi will start."},{"id":212281,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Naruto, go and pull power of Tailed Beast from that guy, just like the tug-of-war with me at that time. Then he will die."},{"id":212282,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Naruto, I'll use power of Susanoo to cover Chakra of the Nine Tails as armor. Let's move!"},{"id":212282,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"I'll never give up. Let's move, everyone. Pull all Tailed Beasts out of his body!"},{"id":212282,"idx":3,"roleId":104,"leftRight":1,"NpcWords":"These guys even\u2026no, it's impossible, Ten Tails is unbeatable!"},{"id":212283,"idx":1,"roleId":104,"leftRight":1,"NpcWords":"\u2026Did I lose it? Did I choose a wrong path? Tell me, Rin..."},{"id":212291,"idx":1,"url":"zhujian","name":"zhujian1","leftRight":0,"NpcWords":"Madara, you have nowhere to run. Let's end it finally. Everything should come to an end."},{"id":212292,"idx":1,"roleId":97,"leftRight":0,"NpcWords":"Hi, One Tail, I need your power to seal Madara? Can you please help me?"},{"id":212292,"idx":2,"url":"yiwei","name":"yiwei","leftRight":0,"NpcWords":"Hum, I don't accept your request, but act as I wish. I don't want to be defeated by Nine Tails, that damned fox. Lead the way!"},{"id":212292,"idx":3,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Obito, so you lost it. Hum, well, my real plan finally started\u2026"},{"id":212293,"idx":1,"roleId":104,"leftRight":1,"NpcWords":"What I did can't be remedied. I can't face Rin once I die. Now let me use Rinnegan Reincarnation skill to revive those guys killed by me\u2026"},{"id":212293,"idx":2,"url":"ban","name":"ban1","leftRight":1,"NpcWords":"Hah, Obito, I won't let you do it. When your internal Tailed Beasts are pulled out, I'll be finally revived. Go to hell!"},{"id":212301,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"That is Art of Rinne Rebirth Nagato also used. Take care, Madara is to be revived."},{"id":212302,"idx":1,"roleId":102,"leftRight":1,"NpcWords":"Only such flesh and blood can arouse my combat passion. Damned Tailed Beasts, I'll immediately absorb you."},{"id":212302,"idx":2,"roleId":107,"leftRight":1,"NpcWords":"Is this Power of the Six Paths\u2026"},{"id":212311,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Damned Madara, I'll be absorbed by him if it continues. Naruto will also die\u2026hi, Kazekage kid, come here, let me tell you something\u2026"},{"id":212312,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"Naruto's Nine Tails was also controlled by Madara. What should I do...Naruto, you're so close to your dream. I'll never let you die!"},{"id":212312,"idx":2,"roleId":97,"leftRight":0,"NpcWords":"Hurry up! Nine Tails told me the only way is to let 4th Hokage transmit the other half of Nine Tails to Naruto. Only by this can Naruto be saved!"},{"id":212312,"idx":3,"roleId":69,"leftRight":1,"NpcWords":"How can I let you succeed? I'll definitely help Lord Madara to capture the remaining Nine Tails!"},{"id":212321,"idx":1,"url":"shuimen","name":"shuimen1","leftRight":0,"NpcWords":"Naruto, I'll transmit the remaining power of Nine Tails to you. Do save this world. You're our hope, my son!"},{"id":212322,"idx":1,"roleId":98,"leftRight":0,"NpcWords":"I'm always in Madara's shadow and try to realize his plan on his behalf, forgetting my self...Kakashi, just let me atone for my sins with my last power."},{"id":212322,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Obito, you finally retrieved your self? I'm so glad to be able to fight along with you in this decisive battle."},{"id":212322,"idx":3,"roleId":107,"leftRight":1,"NpcWords":"A bunch of bums, I won't allow you to pass power of Nine Tails to Naruto\u2026"},{"id":212331,"idx":1,"roleId":83,"leftRight":0,"NpcWords":"Didn't Naruto wake up? How should we resist Madara's attack in this period because our Chakra is almost used up."},{"id":212332,"idx":1,"roleId":84,"leftRight":0,"NpcWords":"As a ninja, death is the most brilliant moment of youthful vigor. Now it's time for me to make a decision, 8th gate of Octagate Release, Gate of Death, opened!"},{"id":212332,"idx":2,"roleId":83,"leftRight":0,"NpcWords":"Guy will inevitably die after opening 8th gate. However, this power is really strong. I can't believe that Guy's vitality skill can reach such an ultimate level."},{"id":212332,"idx":3,"roleId":107,"leftRight":1,"NpcWords":"It's funny. Opening all 8 gates of Octagate Release is rarely seen in the fights. Hope you can let me enjoy myself."},{"id":212333,"idx":1,"roleId":107,"leftRight":1,"NpcWords":"You're really strong and almost kill me\u2026You can injure me so seriously with vitality skill only. Let me help you start another journey!"},{"id":212341,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I'm back!"},{"id":212342,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I won't let you die, Teacher Heavy Eyebrow! I just saw Grandpa Six Paths in my spiritual world. I'm a reincarnated body of his son Ashura, while Sasuke \u2026"},{"id":212342,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"Six Paths gave me power. I'm a reincarnated body of his another son Indra. Now let's jointly defeat Madara, Naruto!"},{"id":212342,"idx":3,"roleId":107,"leftRight":1,"NpcWords":"One of them enabled the Rinnegan, the other enabled Sage of the Six Paths mode\u2026these two kids suddenly enhanced their power. What happened?"},{"id":212351,"idx":1,"roleId":107,"leftRight":1,"NpcWords":"Shinju was cut off by them\u2026Damn it! I've obtained Power of the Six Paths, so I won't fail."},{"id":212352,"idx":1,"roleId":107,"leftRight":1,"NpcWords":"Only I can control Power of the Six Paths. Only my power can become the only God in this world. Go to hell, you all!"},{"id":212352,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"Madara, you're Indra's first reincarnation, while I'm the other one. We have similar experience, but the fate will come to an end from me."},{"id":212352,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"Though this world isn't so perfect. I'll advance bravely and never give up with my important partners."},{"id":212353,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"I finally won it. I have a lot of things to do, including reconstruction of the village, eating Ramen, deciding on a wife, and most importantly, try to become Hokage as soon as possible!"},{"id":212353,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"\u2026Whir, how can I have such an idiot partner like you\u2026but, did you see the path I've chosen, brother\u2026"},{"id":212353,"idx":3,"roleId":90,"leftRight":0,"NpcWords":"Hi, Naruto, try to become Hokage as soon as possible? I'm still alive!!!"},{"id":212361,"idx":1,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"Ur? Ur? Ur? What's wrong? Why was I reincarnated again?"},{"id":212362,"idx":1,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"It's strange. Didn't the war end? Why was I reincarnated again? Moreover, this place is ...Hidden Leaf Village?"},{"id":212362,"idx":2,"roleId":18,"leftRight":0,"NpcWords":"Sorry, we're doing an experiment on reincarnation skill. Naruto wanted to ask you a few questions, so we reincarnated you."},{"id":212362,"idx":3,"roleId":106,"leftRight":0,"NpcWords":"Hah, you came at the right time, Seven Tails. I want to test you with a brain-twister: why a frog jumps higher than a tree?"},{"id":212362,"idx":4,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"Because a tree can't jump\u2026How could you kid reincarnated me for fiddle-faddle? Do you consider me to be a toy?"},{"id":212363,"idx":1,"url":"qiweirenzhuli","name":"qiweirenzhuli1","leftRight":1,"NpcWords":"Remember, I'll directly kill you if you dare play tricks on me again."},{"id":212363,"idx":2,"leftRight":0,"NpcWords":"Sorry, sorry\u2026"},{"id":212371,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Whir, so boring, let me make fun of Eight Tails\u2026"},{"id":212372,"idx":1,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Hi, Eight Tails, the strength of Tailed Beasts always depends on the number of tails. So, you'll never match me."},{"id":212372,"idx":2,"url":"bawei","name":"bawei","leftRight":1,"NpcWords":"I'm not One Tail Shukaku, so I won't be instigated by your words\u2026"},{"id":212372,"idx":3,"url":"jiuwei","name":"jiuwei","leftRight":0,"NpcWords":"Hah, Eight Tails will never match Nine Tails. Hah, see you, younger brother!"},{"id":212372,"idx":4,"url":"bawei","name":"bawei","leftRight":1,"NpcWords":"(Get angry) ...Nine Tails, don't you guy know you'll never die if you don't make troubles!"},{"id":212373,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Hey, don't quarrel with each other even if you're bored. Moreover, you never combat in person but control our two Jinchuriki."},{"id":212373,"idx":2,"roleId":77,"leftRight":0,"NpcWords":"Right, right, check it out! Do you want us to die!"},{"id":212381,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"Naruto \u2026(in a low voice)"},{"id":212382,"idx":1,"roleId":24,"leftRight":0,"NpcWords":"Ur, Naruto \u2026(in a low voice) People say that actually you like Sasuke, right..."},{"id":212382,"idx":2,"roleId":106,"leftRight":1,"NpcWords":"Are you kidding? How is it possible? (Blushing) How can I like that indifferent, cool guy?"},{"id":212382,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"(Blushing) \u2026 you, what did you say? Who's indifferent?"},{"id":212382,"idx":4,"roleId":106,"leftRight":1,"NpcWords":"(Blushing) It's you, hum, want to have a fight?"},{"id":212383,"idx":1,"roleId":18,"leftRight":0,"NpcWords":"What should I do if they fall in love with each other\u2026"},{"id":212391,"idx":1,"roleId":105,"leftRight":1,"NpcWords":"Come on, Naruto, this time I will fight together with you!"},{"id":212392,"idx":1,"roleId":105,"leftRight":1,"NpcWords":"Come on, Naruto, this time I will fight together with you! I already know what are you thinking!"},{"id":212392,"idx":2,"roleId":106,"leftRight":0,"NpcWords":"Hey, already waiting you for a long time, Sasuke. I also have this idea!"},{"id":212393,"idx":1,"roleId":105,"leftRight":0,"NpcWords":"Sure enough. I know, you are my most important person."},{"id":212401,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Naruto, inside your heart. Me and Sasuke, who is more important......"},{"id":212402,"idx":1,"roleId":97,"leftRight":1,"NpcWords":"Naruto, inside your heart. Me and Sasuke, who is more important......"},{"id":212402,"idx":2,"roleId":105,"leftRight":0,"NpcWords":"As you already know, from the first time Naruto always chasing me."},{"id":212402,"idx":3,"roleId":97,"leftRight":1,"NpcWords":"Sasuke, you are the biggest obstacle in my love. I want you to disappear!"},{"id":212403,"idx":1,"roleId":106,"leftRight":0,"NpcWords":"Don\u2019t fight! Me and Hinata will be married. "},{"id":212403,"idx":2,"roleId":97,"leftRight":0,"NpcWords":"Yamete!"},{"id":212403,"idx":3,"roleId":105,"leftRight":0,"NpcWords":"Yamete!"},{"id":213011,"idx":1,"roleId":118,"leftRight":0,"NpcWords":"It's time for my generation to shine too. I may be Naruto's son, but I am Boruto Uzumaki."},{"id":213012,"idx":1,"url":"nobody","name":"nobody","leftRight":0,"NpcWords":"Boruto's desire to leave a mark on Konoha and establish his own identity is a driving force behind this daring act."},{"id":213012,"idx":2,"url":"nobody","name":"nobody","leftRight":0,"NpcWords":"As he carefully selects his colors and prepares his brushes, he contemplates his father's legacy and the heavy burden he carries as the Hokage's son."},{"id":213012,"idx":3,"roleId":118,"leftRight":0,"NpcWords":"Becoming Hokage is a dream of my old man's, and he's done a lot for this village. But it's time for my generation to shine too. I may be Naruto's son, but I am Boruto Uzumaki."},{"id":213012,"idx":4,"roleId":118,"leftRight":0,"NpcWords":"I'll find my own path, and I'll protect this village in my own way. This painting is just the beginning. Remember this moment, Konoha, because I'm going to make sure you never forget it!"},{"id":213012,"idx":5,"roleId":10,"leftRight":1,"NpcWords":"N-no, the Hokage Rock Statue! Boruto, please stop!"},{"id":213012,"idx":6,"roleId":118,"leftRight":0,"NpcWords":"Haha, this is fun!"},{"id":213012,"idx":7,"roleId":10,"leftRight":1,"NpcWords":"H-how could Lord Hokage\u2019s son could do this?"},{"id":213012,"idx":8,"roleId":118,"leftRight":0,"NpcWords":"Don\u2019t call me Hokage\u2019s son!"},{"id":213021,"idx":1,"roleId":118,"leftRight":0,"NpcWords":"Come on adventure with me\uff01"},{"id":214011,"idx":1,"roleId":111,"leftRight":0,"NpcWords":"So, this is Kyuubi Chakra? I can even feel the surge of power"},{"id":214012,"idx":1,"url":"nobody","name":"nobody","leftRight":0,"NpcWords":"In the desolate and eerie landscape known as the \"God Tree Wasteland,\" a pivotal battle unfolds, marking a crucial moment in the life of Boruto Uzumaki, the son of the Seventh Hokage"},{"id":214012,"idx":2,"url":"nobody","name":"nobody","leftRight":0,"NpcWords":"Boruto's encounter with the formidable Otsutsuki clan member, Momoshiki, takes center stage in this intense arc"},{"id":214012,"idx":3,"roleId":111,"leftRight":0,"NpcWords":"So, this is Kyuubi Chakra? I can even feel the surge of power"},{"id":214012,"idx":4,"roleId":155,"leftRight":1,"NpcWords":"Let\u2026 me\u2026 go!"},{"id":214012,"idx":5,"roleId":111,"leftRight":0,"NpcWords":"Not so fast, Hokage, this huge amount of Chakra takes time to absorb"},{"id":214012,"idx":6,"roleId":155,"leftRight":1,"NpcWords":"Well, i\u2019m not making it easy for you!"}];
